insert into guides (id,content) values ('air-filter-tsi',$j${"id": "air-filter-tsi", "title": "Engine air filter (TSI airbox)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "alsoFits": "Mk6 GTI/Golf TSI, Mk5 Jetta TSI, CC (same side-mounted airbox)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "20 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$15–30", "risk": "None worth mentioning", "why": "The TSI moved the air filter out of the engine cover and into a proper airbox on the driver's side. Six captive screws and it's open. Still the easiest, most-forgotten job on the car.", "note": "FCP Euro's Mk6 procedure is the same box; IE's TSI intake guide confirms the fasteners."}, "heroCap": "On a TSI the airbox is a separate box at the front-left of the bay, behind the intake duct. The lid comes off with captive Torx screws; the engine cover is just a cover.", "lifespan": {"title": "When to expect it", "headline": ["Inspect yearly; owners replace around every 20,000–40,000 miles"], "earliest": null, "detail": "A paper filter fails gradually. Hold it up to the light: if you can't see light through the pleats, or there's grit and leaves in the airbox, change it. Dusty roads and a lot of highway bugs shorten it.", "factors": ["Dusty or gravel roads", "Unknown history", "Rodent activity in the engine bay (check the snorkel)"], "inspect": ["Every oil change: pull the cover and look. It's two screws."], "confidence": {"level": "single", "n": 1, "note": "Factory interval not confirmed in this pass. Owner practice and vendor advice only."}}, "should": {"yesIf": ["You don't know when it was last done", "Filter looks grey, or you can't see light through it", "Debris in the airbox", "Every year or so regardless"], "codes": [], "notes": ["Stock paper filter versus an oiled cotton cone: the forums are clear that the stock box pulls cool air from the grille and the paper element isn't a restriction on a stock or Stage 1 car. Oiled filters can also foul the mass-airflow sensor. Stay paper unless you're going to a full intake (that's a separate guide)."], "confidence": {"level": "high", "n": 3, "note": "Vendor write-ups and forum consensus agree."}}, "parts": [{"tier": "oe", "name": "Engine air filter, Genuine VW", "pn": "1K0 129 620 D (confirm against your VIN)", "note": "Panel filter for the TSI airbox", "price": "$20–30", "links": []}, {"tier": "oem", "name": "Engine air filter, Mann or Mahle", "pn": "Mann C 35 154 / equivalent (confirm)", "note": "Same filter, maker's box", "price": "$12–20", "links": []}], "aftermarket": [{"name": "Drop-in cotton panel (K&N, aFe)", "note": "Fits the stock box. Slight airflow gain on paper, real risk of oil on the MAF sensor if over-oiled, and no cold-air benefit. Forums are lukewarm.", "price": "$50–70", "signal": "Community verdict: stay paper", "links": []}], "tools": [{"name": "T25 Torx"}, {"name": "Pliers for the breather tube clip; shop vac or rag"}], "before": ["Engine off and cool enough to lean over.", "Have the new filter out of the box so you can compare it to the old one."], "steps": [{"n": 1, "title": "Find the box", "blocks": [{"t": "text", "b": "Driver's side, front, behind the plastic intake duct that runs from the grille. The lid has screws around its edge; the MAF sensor sits in the outlet tube at the back."}, {"t": "ill", "id": "airbox-tsi", "cap": "Side-mounted airbox: six captive T25 screws on the lid, two more where the outlet tube meets the box."}]}, {"n": 2, "title": "Loosen the lid screws", "blocks": [{"t": "text", "b": "Six T25 screws around the lid. They're captive: loosen them until they spin free, don't try to pull them out. Two more T25s at the back where the tube before the MAF joins the box; loosen those the same way."}]}, {"n": 3, "title": "Breather tube off", "blocks": [{"t": "text", "b": "The small breather tube at the front of the box: squeeze its sides and pull. It's stiff the first time. Cars with secondary air injection also have an SAI hose clipped to the box; unclip it."}]}, {"n": 4, "title": "Lid off, filter out", "blocks": [{"t": "text", "b": "Lift the lid clear. The panel filter sits in the lower half; lift it out and look at it (table below). Vacuum the box."}]}, {"n": 5, "title": "New filter, lid on", "blocks": [{"t": "text", "b": "New filter with its rubber edge seated all round. Lid on, snug the eight screws (plastic, don't crank), breather tube and SAI hose back. Start it and listen for hiss at the outlet tube."}]}], "alsoReplace": [{"name": "Cabin air filter", "why": "Same trip to the parts store, same 'nobody ever changed it' energy. It's behind the glovebox and takes ten minutes."}], "check": {"tab": "Read the filter", "title": "Reading your old filter", "illId": "airbox", "illCap": "Light through the pleats is the test.", "rows": [{"see": "Off-white, light passes through easily", "means": "Fine.", "do": "Put it back or replace if it's cheap and you're already here."}, {"see": "Grey, light passes with effort", "means": "Doing its job; near the end.", "do": "Replace."}, {"see": "Black, blocked, or debris/rodent nesting in the box", "means": "Restricting airflow; the previous owner never did this.", "do": "Replace, vacuum the box, check the snorkel and inlet pipe for debris."}], "c": {"level": "community", "n": 3, "note": "Standard practice; consistent across sources."}}, "aftercare": ["Note the mileage somewhere you'll find it.", "If you ever see oil residue on the MAF sensor after switching to an oiled filter, clean it with MAF cleaner and go back to paper."], "disagreements": [{"topic": "Interval", "pos": "FCP says 30–40k; owners inspect yearly.", "call": "Inspect at every oil change; replace when it fails the light test."}], "sources": ["FCP Euro Mk6 GTI engine air filter replacement", "IE Mk5/Mk6 TSI intake install guide (airbox fasteners)", "Pelican Parts (FSI article; reader note that late Mk5s differ)"], "embeds": [], "heroId": "airbox-tsi"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('intake-tsi',$j${"id": "intake-tsi", "title": "Aftermarket intake install (TSI)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "airbox-tsi", "alsoFits": "Mk6 GTI/Golf TSI, Mk5 Jetta TSI, Mk2 Beetle (same airbox and inlet)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake are you installing?", "hint": "TSI kits are engine-specific: an FSI intake will not fit. All of the common ones remove the side airbox and reuse its mounting points.", "options": [{"id": "ie", "label": "Integrated Engineering (TSI)", "when": "Full kit; PDF install guide"}, {"id": "cts", "label": "CTS Turbo", "when": "Full kit; brief sheet"}, {"id": "other", "label": "Other TSI kit (APR, Neuspeed, ECS…)", "when": "Same shape of job; follow your kit's sheet"}]}, "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$250–600", "risk": "MAF sensor is fragile · clamps at the turbo are awkward", "why": "Same story as the FSI: on a stock turbo it's sound and throttle feel; with a tune it earns its keep. The TSI's side airbox makes the swap simpler than on the FSI because the engine cover isn't involved.", "note": "IE's TSI PDF and owners agree on about an hour."}, "heroCap": "TSI kits replace the side airbox with a heat-shielded filter on the factory airbox mounts and a pipe to the turbo inlet. The engine cover stays.", "lifespan": {"title": "When owners do this", "headline": ["Usually the first engine mod, often with a Stage 1 tune"], "earliest": null, "detail": "There's nothing to wear out; owners do it for sound and looks first, and because a tune plus intake is the classic first step. Oiled cotton filters want cleaning every 20–30k; dry paper elements get replaced.", "factors": ["Stage 1/2 tune", "K04 or bigger turbo (then it matters for real)", "You miss induction noise"], "inspect": ["Cotton filter: clean and re-oil every 20–30k miles, lightly. Over-oiling fouls the MAF."], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor notes. Power claims are the vendors'."}}, "should": {"yesIf": ["You want induction sound and sharper throttle feel", "You're tuned or going to be", "You have or want to delete the engine cover look", "You accept that dyno gains on a stock turbo are small"], "codes": [], "notes": ["The factory MAF sensor moves to the new pipe. Pipe bore must match the sensor or fuel trims go off; buy a real kit, not an eBay pipe.", "Check the fitment: 2.0T FSI and 2.0T TSI intakes are not interchangeable, and both were sold for 'Mk5 GTI'. Your 2008.5–2009 car is TSI."], "confidence": {"level": "high", "n": 4, "note": "Method agrees across two manufacturer PDFs and two owner install threads."}}, "parts": [{"tier": "aftermarket", "name": "Intake kit", "pn": "see options below", "note": "Pipe, coupler(s), filter, heat shield, clamps, isolator hardware", "price": "$250–600", "links": []}, {"tier": "oe", "name": "Turbo inlet o-ring / gasket", "pn": "if reusing the factory inlet pipe", "note": "Only if it's cracked", "price": "$5", "links": [], "only": ["carbonio"]}, {"tier": "oe", "name": "Small zip ties, silicone spray", "pn": "—", "note": "For routing the MAF harness and seating grommets", "price": "$5", "links": []}], "aftermarket": [{"name": "Integrated Engineering TSI intake", "note": "Uses the factory airbox mounts; velocity stack under a heat shield; full PDF.", "price": "$400–500", "signal": "Best documented", "links": [{"store": "IE TSI install guide (PDF)", "url": "https://pbie.s3.amazonaws.com/guides/IE%20MK5_MK6%20TSI%20IEINCC2%20Intake%20Install%20Guide.pdf"}]}, {"name": "CTS Turbo TSI intake", "note": "Sealed box with scoop, 2.75\" pipe, factory MAF position. Sheet is short but the job matches IE's.", "price": "$300–400", "signal": "Tuner pick", "links": [{"store": "CTS sheet (PDF)", "url": "http://blog.moddedeuros.com/wp-content/uploads/2020/12/CTS-IT-105R.pdf"}]}, {"name": "APR Carbonio / Neuspeed P-Flo / ECS Luft-Technik (TSI versions)", "note": "All reuse the airbox mounts; same install shape. Buy the TSI part number.", "price": "$300–600", "signal": "Fine choices", "links": []}], "tools": [{"name": "T25 Torx, 8mm triple-square (inlet pipe bracket bolt)"}, {"name": "Hose-clamp pliers, Phillips (MAF screws), 10mm wrench"}, {"name": "Screwdriver for worm clamps; mirror for the turbo inlet"}], "before": ["Engine cold.", "Lay the kit out against its parts list.", "Handle the MAF by its housing only."], "steps": [{"n": 1, "title": "Intake duct off", "blocks": [{"t": "text", "b": "Two T25 screws hold the duct to the radiator support, one each side. Unclip the duct's plastic lid and lift the duct out."}]}, {"n": 2, "title": "MAF and inlet pipe", "blocks": [{"t": "text", "b": "Unplug the MAF. Squeeze the spring clamp holding the inlet pipe to the MAF and slide it back onto the pipe; pull the pipe off the MAF. Cars with secondary air injection: unclip the SAI hose from the airbox."}]}, {"n": 3, "title": "Airbox out", "blocks": [{"t": "text", "b": "One T25 at the back of the airbox, then pull the whole box straight up off its rubber mounts. Two screws hold the MAF into the box; slide the sensor out and set it somewhere clean."}, {"t": "ill", "id": "airbox-tsi", "cap": "The box lifts off two or three rubber-mounted posts; the kit's heat shield lands on the same posts."}]}, {"n": 4, "title": "Factory inlet pipe off", "blocks": [{"t": "text", "b": "Remove the inlet pipe's bracket bolt (8mm triple-square) and the clamp at the turbo coupler, and pull the factory inlet pipe. Keep the clamp if the kit reuses it."}]}, {"n": 5, "title": "Build and fit the kit", "blocks": [{"t": "text", "b": "MAF into the new pipe with the kit's screws, arrow toward the turbo. Coupler onto the turbo inlet, clamp loose. Pipe into the coupler, kit bracket onto the factory bracket point. Heat shield onto the airbox posts. Filter onto the pipe or stack, clamp snug. Reconnect the breather/SAI hose to the kit's fitting.", "only": ["ie", "cts", "other"]}]}, {"n": 6, "title": "Align, tighten, start", "caution": true, "blocks": [{"t": "text", "b": "Everything sitting relaxed and clear of the strut brace and coolant lines? Then tighten all clamps and the bracket, plug the MAF in, and start it. Listen for hiss at the couplers; a stumble that clears in a minute is the ECU adapting."}, {"t": "warn", "b": "A coupler clamped under tension slips off the turbo under boost. Relaxed first, tight second."}]}], "alsoReplace": [{"name": "PCV valve", "why": "Different part on the TSI and just as failure-prone. Same access."}, {"name": "Turbo inlet coupler", "why": "Hardened factory couplers are a common TSI boost leak; the kit's silicone one replaces it."}], "check": {"tab": "Which kit?", "title": "Which kind of intake suits you?", "illId": "intake-hero", "illCap": "Full kit (left) replaces the cover; Carbonio (right) keeps it.", "rows": [{"see": "Stock turbo, maybe Stage 1, want sound and looks", "means": "You're buying character, not horsepower. Any well-made kit does this.", "do": "Neuspeed or IE if you like the exposed-engine look; Carbonio Stage 1 if you want the cover."}, {"see": "K04 or bigger turbo, Stage 2+", "means": "Now the stock box is a real restriction.", "do": "Full kit: IE, CTS or Neuspeed. Skip Carbonio Stage 1."}, {"see": "Salt-belt daily, don't want to oil filters", "means": "Oiled cotton needs care and can foul the MAF.", "do": "Pick a kit with a dry filter option (Neuspeed) or budget for careful oiling."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; vendor claims noted as claims."}}, "aftercare": ["Re-tighten clamps after the first heat cycle.", "Oiled filter: clean and lightly re-oil every 20–30k. Dry filter: replace per the maker.", "Rough idle after install: check the MAF plug and that the pipe's MAF boss is the right diameter for your sensor."], "disagreements": [{"topic": "How much does it do?", "pos": "Vendors: 9–15 whp. Owners: 'louder, not faster' on a stock turbo.", "call": "Both are right for different cars. We say so."}, {"topic": "T20 or T25? T25 or T30?", "pos": "APR's sheet vs the owner who installed it; Pelican vs FCP on the stock screws.", "call": "Bring the set."}, {"topic": "Is Carbonio Stage 1 an intake?", "pos": "Forum argument since 2008.", "call": "It's the mild option. Fine if you want the cover; not the pick for a K04."}], "sources": ["IE Mk5/Mk6 TSI intake install guide (PDF)", "CTS Turbo Mk6 intake sheet (Mk5 TSI shown)", "Forum threads on TSI intakes"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('pcv-tsi',$j${"id": "pcv-tsi", "title": "PCV valve replacement (TSI)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "pcv-hero", "alsoFits": "All 2.0T TSI Gen 1 (CCTA/CBFA): Mk5/Mk6 GTI, Jetta, CC, Tiguan, A3", "category": "Engine", "kind": "repair", "variants": null, "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1, "cost": "$50–120 (valve) · $80–250 (plate)", "risk": "Brittle plastic pipe clips", "why": "Same diaphragm-in-a-plastic-box design as the FSI, same failure: torn diaphragm, giant vacuum leak, a loud whistle or howl at idle, rough running, codes. On the TSI a failed PCV also pressurises the crankcase and pushes oil out of the rear main seal, which is why you fix it promptly.", "note": "DAP's TSI procedure; forum threads agree it's a twenty-minute job."}, "heroCap": "On the TSI the PCV is a flat unit bolted to the top of the cylinder head at the back, with a vent hose to the intake manifold. Same failure, different part.", "lifespan": {"title": "When to expect it", "headline": ["Factory valves commonly fail between 40,000 and 80,000 miles, and the replacements fail too"], "earliest": "Some cars have eaten three or four", "detail": "TSI valves fail like FSI valves: heat and oil tear the diaphragm. Symptoms range from a howl at idle to a rough cold idle with lean codes. Check suction at the oil cap at idle. A long-failed PCV on a TSI shows up as an oil drip between the engine and transmission: that's the rear main seal it blew out.", "factors": ["Tuned car (more boost pressure on the check valve)", "Heat: hot climates, hard use", "Age of the rubber"], "inspect": ["Any rough idle or whistle: pull the oil cap at idle and feel for suction"], "confidence": {"level": "community", "n": 4, "note": "DAP articles and forum consensus. No factory interval; it's a failure item."}}, "should": {"yesIf": ["Whistle or howl from under the hood at idle", "Rough or hanging idle, misfires at idle", "Strong suction at the oil filler cap", "Codes P0171, P0507, misfire codes", "Oil leak at the rear main seal (check the PCV first, it's usually the cause)"], "codes": ["P0171", "P0507", "P0300"], "notes": ["Part number: 06H 103 495 AC is the current revision, replacing 06H 103 495 A and E. Unlike the FSI, there's one family; buy the latest.", "A failed TSI PCV can blow the rear main seal. If you find one, look for oil at the bellhousing too."], "confidence": {"level": "high", "n": 4, "note": "Symptoms and procedure agree across DAP, ECS and forum threads."}}, "parts": [{"tier": "oe", "name": "PCV valve, latest revision", "pn": "06H 103 495 AC", "note": "Gasket usually included", "price": "$60–120", "links": []}, {"tier": "oe", "name": "PCV vent hose to manifold", "pn": "if the clips are cracked", "note": "", "price": "$20", "links": []}], "aftermarket": [{"name": "Billet PCV delete / breather plate (TSI)", "note": "Same idea as the FSI plates: replace the diaphragm unit with a machined plate and route the vent to a catch can.", "price": "$80–200", "signal": "Pairs with a catch can", "links": []}], "tools": [{"name": "T30 Torx (check yours; some are E-Torx)"}, {"name": "Small flat screwdriver for the hose clasps"}], "before": ["Engine cool.", "Look at the pipe clips first: they're brittle plastic. Work them gently, and buy a new pipe if one has already cracked.", "Have the old valve's part number in hand before you order the new one."], "steps": [{"n": 1, "title": "Engine cover off", "blocks": [{"t": "text", "b": "Pull the cover up evenly at the corners; front corners first. The PCV is the flat black unit on the head at the back, driver's side."}]}, {"n": 2, "title": "Vent hose off", "blocks": [{"t": "text", "b": "The hose from the PCV back to the intake manifold has spring clasps at each end; a small screwdriver helps release them. Pull it off both ends."}, {"t": "ill", "id": "pcv-hero", "cap": "TSI layout differs from the FSI drawing here in detail; the idea is identical: one vent hose, a handful of screws, a flat valve on the head."}]}, {"n": 3, "title": "Valve off", "blocks": [{"t": "text", "b": "Remove the Torx screws holding the valve to the head (count them; typically five), lift the valve, and clean the head's face."}]}, {"n": 4, "title": "New valve on", "blocks": [{"t": "text", "b": "New gasket seated, valve down, screws snug in a criss-cross. Plastic into aluminium: don't overdo it."}, {"t": "torque", "label": "PCV screws (Torx)", "nm": 4, "c": {"level": "single", "n": 1, "note": "No figure in the sources this pass; kit sheets say snug, roughly 4 Nm. Plastic housing."}}]}, {"n": 5, "title": "Hose on, cover on, listen", "blocks": [{"t": "text", "b": "Vent hose clipped at both ends, cover on. Start it: howl gone, idle settling within a minute. Oil-cap test: gentle suction only."}]}], "alsoReplace": [{"name": "Rear main seal check", "why": "If the PCV failed long ago, look for oil at the bellhousing. A blown RMS is a transmission-out job (see the clutch guide) and the PCV must be fixed first or the new seal blows too."}, {"name": "Diverter valve", "why": "Same era, same diaphragm failure. Check it while you're here (its own guide)."}], "check": {"tab": "Is it the PCV?", "title": "Is the PCV really the problem?", "illId": "pcv-hero", "illCap": "The oil-cap test settles most of it.", "rows": [{"see": "Howl/whistle at idle, strong suck at the oil cap", "means": "Torn diaphragm.", "do": "Replace the valve."}, {"see": "Rough idle, lean codes, no noise", "means": "PCV, diverter valve, or an intake leak.", "do": "Oil-cap test; replace the PCV anyway if it's old."}, {"see": "Oil at the bellhousing", "means": "Rear main seal pushed out by crankcase pressure.", "do": "PCV first, then the seal."}], "c": {"level": "community", "n": 3, "note": "Vendor articles and forum diagnosis."}}, "aftercare": ["Note the revision you fitted for next time.", "If the idle stays rough after a day, look at the diverter valve next."], "disagreements": [{"topic": "Fix or delete?", "pos": "Forums split.", "call": "Latest valve for a stock car; plate plus catch can for a tuned one."}], "sources": ["DAP TSI PCV replacement DIY and symptoms article", "DAP 2.0T TSI common problems article", "Forum threads on TSI PCV and rear main seal"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('downpipe-tsi',$j${"id": "downpipe-tsi", "title": "Downpipe upgrade (TSI)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "downpipe-hero", "alsoFits": "Mk6 GTI/Golf TSI (same downpipe); Mk5 Jetta TSI", "category": "Engine", "kind": "upgrade", "variants": {"question": "What's the downpipe connecting to?", "hint": "The stock cat-back has a 60mm slip joint. A 3-inch aftermarket downpipe needs a reducer to meet it, or mates directly to a 3-inch cat-back.", "options": [{"id": "stockcb", "label": "Stock cat-back", "when": "You'll use the kit's reducer adapter and clamps"}, {"id": "aftcb", "label": "3-inch aftermarket cat-back", "when": "Direct slip-fit or V-band, no adapter"}]}, "glance": {"timeFirst": "3–4 hr", "timeRepeat": "2 hr", "difficulty": 3, "cost": "$500–1,000 + tune", "risk": "Seized nuts and O2 sensors · hot, heavy pipe · legality", "why": "The factory downpipe necks down right after the turbo and carries a dense cat. A 3-inch pipe with a high-flow cat lets the turbo breathe out, which is where a tuned FSI finds its next 20–30 hp and a lot of its sound.", "note": "Same pipe, same nuts as the FSI; only the way in from the top differs. ECS documents both."}, "heroCap": "Turbo flange (4 nuts) → flex → cat → bracket on the crossmember → slip joint to the cat-back. Two O2 sensors live in it. The chassis braces have to come off to get it out.", "lifespan": {"title": "When owners do this", "headline": ["With, or right after, a Stage 2 tune"], "earliest": null, "detail": "Stage 2 software assumes a high-flow downpipe. Doing the pipe without the tune gives you sound and a likely check-engine light; the tune without the pipe leaves power on the table. Owners pair them.", "factors": ["Stage 2 tune planned", "Cat-back already fitted", "Catalytic converter failing anyway (P0420)"], "inspect": ["Re-check all nuts and clamps after 1–2 days of driving"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus and vendor positioning."}}, "should": {"yesIf": ["You're going Stage 2", "Your factory cat is failing and you'd rather upgrade than replace", "You want the sound", "You're prepared to deal with a possible check-engine light"], "codes": ["P0420", "P0430", "P2096"], "notes": ["Catted or catless: a catless pipe is louder, smellier, will light the check-engine lamp without software, and is illegal for road use in the US (federal law, not just California). A 200-cell high-flow cat keeps most of the flow and most of the legality. This guide assumes catted.", "Even with a high-flow cat, some cars throw P0420 after a heat cycle or two. Stage 2 software from your tuner handles it; an O2 spacer is the workaround people argue about."], "confidence": {"level": "high", "n": 4, "note": "Procedure agrees across two manufacturer guides and an owner write-up; the legal point is federal regulation."}}, "parts": [{"tier": "aftermarket", "name": "3\" downpipe with high-flow cat", "pn": "see options below", "note": "Should include gasket, 4 flange nuts, bracket, clamps", "price": "$450–900", "links": []}, {"tier": "oe", "name": "Turbo-to-downpipe gasket", "pn": "in most kits", "note": "Never reuse the old one", "price": "$10", "links": []}, {"tier": "oe", "name": "Turbo flange nuts, M10 self-locking (×4)", "pn": "N 102 861 08", "note": "In most kits; buy spares, one always rounds", "price": "$8", "links": []}, {"tier": "oe", "name": "Turbo flange studs, M10 (×4)", "pn": "N 044 520 3", "note": "Only if one comes out with the nut or is chewed", "price": "$12", "links": []}, {"tier": "oe", "name": "Copper anti-seize, penetrating oil", "pn": "—", "note": "Studs, O2 threads, slip joints", "price": "$15", "links": []}], "aftermarket": [{"name": "ECS Tuning high-flow downpipe", "note": "Fits stock geometry, OE bracket and O2 positions, includes hardware and the best-documented install (with the cat-back in the same guide).", "price": "$500–650", "signal": "Best documented", "links": [{"store": "ECS install instructions", "url": "https://blog.ecstuning.com/vw-mk5-gti-ecs-valved-exhaust-system-installation-instructions/"}]}, {"name": "Integrated Engineering 3\" downpipe", "note": "V-band to a catted mid-pipe, slip-fit adapter to the stock cat-back. Full install PDF.", "price": "$600–750", "signal": "Well documented", "links": [{"store": "IE install guide (PDF)", "url": "https://cdn.performancebyie.com/guides/MK5MK6%20Downpipe%20Install%20Guide.pdf"}]}, {"name": "Unitronic 3\" downpipe", "note": "T304, V-band, 200-cell cat, OE O2 positions and an OE-style cat heat shield. Pairs with their software.", "price": "$800–1,000", "signal": "If you run Uni software", "links": []}, {"name": "CTS Turbo, APR, Eurojet", "note": "All well-regarded 3\" catted pipes with the same fitment. Eurojet's Mk5 turboback PDF is public.", "price": "$500–900", "signal": "Fine choices", "links": []}], "tools": [{"name": "Jack + stands (a lift makes this much easier)"}, {"name": "Sockets: 10, 13, 16, 17mm · 16mm wrench · M8 triple-square · T25/T30 · 5mm hex"}, {"name": "22mm O2 sensor socket or wrench, long extension for the upper flange nuts, mirror"}, {"name": "Torque wrench to 40 Nm; breaker bar; penetrating oil the night before"}, {"name": "Exhaust hanger pliers, silicone spray; second jack stand to support the pipe"}], "before": ["Soak the four turbo flange nuts and both O2 sensors with penetrating oil the night before. This is the difference between a two-hour job and a broken stud.", "Engine cold. The turbo and downpipe hold heat for an hour after a drive.", "Lay the new pipe out and test-fit every slip joint on the floor; gently round any shipping dings with a hammer.", "Get the stock pipe out over the chassis braces, so they come off. Support the pipe before you free it."], "steps": [{"n": 1, "title": "Clear the top of the engine (TSI)", "blocks": [{"t": "text", "b": "Engine cover off. Unplug the MAF and release the spring clamp on the flexible intake tube at the MAF; pull the tube off. Remove the T30 bolt holding the turbo inlet pipe to the heat shield behind the head, unclip the crank vent hose from the inlet pipe (pinch its tabs), release the lower spring clamp on the inlet pipe's coupler at the turbo and pull the pipe and coupler off."}, {"t": "text", "b": "Behind the head, the cover plate over the turbo: remove its fasteners (10mm, 18mm and an M8 triple-square; a mirror helps), drop it off its studs, and pull it straight out."}]}, {"n": 2, "title": "Front O2 sensor and upper flange nuts", "blocks": [{"t": "text", "b": "Unplug the front O2 sensor and free its harness from two clips. Remove the sensor with a 22mm O2 socket. Then the two upper turbo-flange nuts, 16mm, on a long extension from above."}, {"t": "note", "b": "If a nut won't move, more oil and patience. A rounded nut here becomes a stud extraction with the turbo in the car."}]}, {"n": 3, "title": "Underneath: belly pan, rear O2, axle shield", "blocks": [{"t": "text", "b": "Raise the car. Belly pan off (¼-turn fasteners or Torx). Loosen the four plastic nuts on the right underbody panel (10mm), fold it down and unplug the rear O2 sensor at its connector, then remove the sensor. Remove the CV-axle heat shield (two 17mm bolts)."}]}, {"n": 4, "title": "Lower flange nuts, braces, bracket", "caution": true, "blocks": [{"t": "text", "b": "Two lower flange nuts, 16mm wrench (a 3/8-drive socket fits where 1/2 won't). Loosen the sleeve clamp at the cat-back joint (17mm) and slide it clear. Put a jack stand under the cat. Remove both chassis braces (four 13mm nuts each). Remove the two 13mm bolts holding the downpipe bracket to the crossmember."}, {"t": "warn", "b": "Once the braces and bracket are out, the stand and the four studs are all that hold a heavy, awkward pipe. Keep your body out from under it."}, {"t": "ill", "id": "downpipe-hero", "cap": "What holds it: four flange nuts, the bracket on the crossmember, the slip joint. The braces are in the way, not holding it."}]}, {"n": 5, "title": "Out with the old pipe", "timeSink": true, "blocks": [{"t": "text", "b": "Slide the pipe off the turbo studs, twist it about a quarter turn counter-clockwise, and pull it back and down out of the car. Pry the rubber-mounted bracket off the old pipe with hanger pliers or a pick; the new pipe uses the factory mounts."}]}, {"n": 6, "title": "New pipe onto the turbo", "caution": true, "blocks": [{"t": "text", "b": "Anti-seize on the four studs. New gasket on the flange with its tab at the bottom, toward the turbo. Press the new bracket into the factory rubber mounts (curved edge up) and hang the kit's bolt in it loose. Lift the pipe onto the studs, sandwiching the gasket, and start four new nuts by hand. Bracket bolts back into the crossmember."}, {"t": "torque", "label": "Turbo flange nuts (M10 ×4)", "nm": 40, "c": {"level": "high", "n": 3, "note": "40 Nm (ECS) and 30 lb-ft (IE) are the same value; owner write-up consistent."}}, {"t": "torque", "label": "Downpipe bracket bolts (×2)", "nm": 25, "c": {"level": "medium", "n": 2, "note": "ECS instructions; IE reuses factory bolts without a figure."}}, {"t": "text", "b": "Anti-seize on the kit's O2 plug and thread it into the unused bung with its washer (30 Nm), then tighten the bracket-to-pipe bolt."}]}, {"n": 7, "title": "Join it to the cat-back", "blocks": [{"t": "text", "b": "Slide the kit's reducer adapter and clamps onto the stock cat-back with anti-seize on the pipe, then the new mid-pipe extension into it, twisting to seat. Nothing tight yet.", "only": ["stockcb"]}, {"t": "text", "b": "Mate the 3-inch joint directly: slip-fit with the clamp loose, or V-band with the clamp snug but not final. Nothing tight yet.", "only": ["aftcb"]}, {"t": "text", "b": "Look along the pipe: it must sit centred, clear of the braces and the subframe, with the flex section unstressed. Then tighten the clamps. ECS: snug by hand, then torque; IE's slip-fit adapter wants to be very tight."}, {"t": "torque", "label": "Exhaust sleeve clamps", "nm": 19, "c": {"level": "varies", "n": 2, "note": "ECS: 19 Nm, no impact. IE: 'very tight, use an impact' on their slip-fit adapter. Different joint designs; follow your kit."}, "only": ["stockcb", "aftcb"]}]}, {"n": 8, "title": "Sensors, shields, braces", "blocks": [{"t": "text", "b": "Anti-seize on both O2 sensor threads and refit them (22mm, snug; they have a taper seat). Plug them in and clip the harnesses. CV shield, both chassis braces, underbody panel, belly pan. Up top: cover plate, engine cover or intake, MAF."}]}, {"n": 9, "title": "Start, check, drive, re-check", "blocks": [{"t": "text", "b": "Start it cold and put a hand near each joint feeling for puffs. Drive it. After a day or two, re-torque the flange nuts and clamps and check the pipe hasn't shifted onto a brace. If the check-engine light comes on for P0420, that's the software conversation with your tuner."}]}], "alsoReplace": [{"name": "Front and rear O2 sensors", "why": "They're out. On a car past 100k with original sensors, new ones now avoid doing this twice, and a lazy front sensor hurts fuel trims on a tuned car."}, {"name": "Turbo flange studs", "why": "If any stud is chewed or backs out with its nut, replace all four while the pipe is off. A stud that fails later means the pipe comes off again."}, {"name": "Cat-back exhaust", "why": "Same afternoon, same braces off. If you're doing both, do them together and skip the reducer adapter."}], "check": {"tab": "Cat or catless", "title": "Catted or catless?", "illId": "downpipe-hero", "illCap": "The cat sits just past the flex. High-flow means a 200-cell metallic matrix in the same spot.", "rows": [{"see": "Street car, inspections, resale", "means": "You need to pass and you'd like to breathe.", "do": "200-cell high-flow catted pipe. This guide."}, {"see": "Dedicated track car, off-road use only", "means": "Legality isn't your constraint.", "do": "Catless is louder and marginally freer-flowing; expect a check-engine light without software."}, {"see": "Just want the noise", "means": "Cat-back or resonator delete does that cheaper.", "do": "Do the cat-back first."}], "c": {"level": "community", "n": 3, "note": "Forum consensus; legal point is US federal rule."}}, "aftercare": ["Re-torque after 1–2 days.", "Exhaust smell in the cabin or a tick on cold start: gasket or a clamp, check them.", "P0420 after a few heat cycles is common with a high-flow cat; talk to your tuner before buying anything."], "disagreements": [{"topic": "Getting at the top from above", "pos": "IE's Mk5/Mk6 guide removes the turbo heat shield and coolant crossover; ECS's TSI path pulls the inlet pipe and the cover plate.", "call": "ECS's path is enough on a Mk5 TSI; IE's crossover step gains room on the Mk6."}, {"topic": "Clamp tightening", "pos": "ECS: hand-snug, no impact, 19 Nm. IE: very tight, use an impact.", "call": "Different joint designs. Follow the kit; never impact a factory-style sleeve clamp."}, {"topic": "Catless", "pos": "Some forum voices treat it as normal.", "call": "Illegal on the road in the US and lights the lamp. We describe it, we don't recommend it."}], "sources": ["ECS Tuning Mk5 GTI exhaust instructions, TSI downpipe section", "ECS Tuning Mk5 GTI valved exhaust installation instructions (2017)", "ECS high-flow downpipe installation PDFs", "Integrated Engineering Mk5/Mk6 downpipe install guide (PDF)", "tasteslikepetrol.net Mk5 GTI downpipe install", "Unitronic downpipe listing (OE positions)", "UroTuning turbo hardware kit (part numbers)", "Eurojet Mk5 turboback install PDF (tool list)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('catch-can-tsi',$j${"id": "catch-can-tsi", "title": "Oil catch can install (TSI)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "catchcan-hero", "alsoFits": "2.0T TSI Gen 1", "category": "Engine", "kind": "upgrade", "glance": {"timeFirst": "1.5 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$250–450", "risk": "Winter freeze · routing", "why": "Same carbon problem as the FSI, different kits: TSI cans tap the PCV on the valve cover and return to the turbo inlet. Kits from IE, CTS, 034 and ECS exist for the TSI; the install follows the FSI catch can guide's shape with TSI hardware.", "note": "Stub: sourcing the TSI kit sheets is the next step."}, "heroCap": "Same flow as the FSI: crankcase vent → baffled can → turbo inlet.", "lifespan": {"title": "When owners do this", "headline": ["With a tune, or after the first carbon cleaning"], "earliest": null, "detail": "See the FSI catch can guide.", "factors": ["Tune"], "inspect": ["Check weekly at first"], "confidence": {"level": "community", "n": 2, "note": "Stub"}}, "should": {"yesIf": ["Tuned car", "Oil in the intercooler pipes"], "codes": [], "notes": ["This guide is a placeholder while the TSI kit instructions are sourced. The FSI catch can guide explains the reasoning and the winter warning, which apply unchanged."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [{"tier": "aftermarket", "name": "TSI catch can kit", "pn": "IE / CTS / 034 / ECS (TSI part numbers)", "note": "", "price": "$250–450", "links": []}], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "TSI-specific steps are being sourced from the IE, CTS and 034 TSI kit sheets. Until then, the FSI guide covers the principles."}]}], "alsoReplace": [], "check": {"tab": "Which path?", "title": "Which setup?", "illId": "catchcan-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["To be sourced: IE, CTS, 034 TSI catch can sheets"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('diverter-valve',$j${"id": "diverter-valve", "title": "Diverter valve replacement", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "dv-hero", "alsoFits": "Every 2.0T FSI/TSI with the K03 turbo (Mk5/Mk6 GTI, Jetta, A3, CC, Tiguan)", "category": "Engine", "kind": "repair", "variants": {"question": "Which engine?", "hint": "Same job, different part number.", "options": [{"id": "fsi", "label": "2.0T FSI (2006–2008.5)", "when": "Original diaphragm valve; replace with the piston-type revision"}, {"id": "tsi", "label": "2.0T TSI (2008.5–2009)", "when": "Early cars have the diaphragm valve; rev D is the fix"}]}, "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1.5, "cost": "$60–120", "risk": "Three bolts in an awkward spot; hot turbo", "why": "The diverter valve sits on the turbo and dumps boost back to the inlet when you lift off the throttle. The early one has a rubber diaphragm that tears, and then the turbo can't hold boost: soft power, a code, sometimes a flutter. VW's fix was a piston-type valve, and fitting it is three bolts.", "note": "Vendor articles and forum threads agree completely; the only variable is reaching the bolts."}, "heroCap": "Three Torx bolts hold the valve to the turbo's compressor housing. Unplug, unbolt, swap, done.", "lifespan": {"title": "When to expect it", "headline": ["Original diaphragm valves commonly fail by 60,000–100,000 miles; sooner with a tune"], "earliest": "20k on tuned cars", "detail": "Symptoms: boost that builds then falls away, a code for underboost or a DV circuit fault, and sometimes a fluttering noise on lift-off. Tuned cars kill diaphragm valves fast because they run more pressure across them.", "factors": ["Tune", "Age of the rubber", "Heat"], "inspect": ["Any underboost code: pull the valve and look at the diaphragm"], "confidence": {"level": "community", "n": 4, "note": "Vendor articles and forum consensus."}}, "should": {"yesIf": ["Underboost codes (P0299) or DV codes (P0033, P0034)", "Boost builds then drops", "Fluttering on lift-off", "You've tuned it and still have the diaphragm valve"], "codes": ["P0299", "P0033", "P0034"], "notes": [{"text": "FSI part: the piston-type revision (06F 145 710 G) replaces the original diaphragm valves. Any 'D' rev TSI valve also physically fits and many owners use it.", "only": ["fsi"]}, {"text": "TSI part: 06H 145 710 D is the piston-type revision that replaces the earlier diaphragm valves (A, B, C). Buy D.", "only": ["tsi"]}, "Aftermarket: Forge and GFB make mechanical spring-piston valves. On a stock or Stage 1 car the factory rev D is the right answer; the aftermarket ones are for big-turbo builds."], "confidence": {"level": "high", "n": 4, "note": "Part revisions and procedure consistent across DAP, ECS and forum threads."}}, "parts": [{"tier": "oe", "name": "Diverter valve, piston type", "pn": "06F 145 710 G", "note": "", "price": "$60–100", "links": [], "only": ["fsi"]}, {"tier": "oe", "name": "Diverter valve, revision D", "pn": "06H 145 710 D", "note": "", "price": "$60–120", "links": [], "only": ["tsi"]}], "aftermarket": [{"name": "Forge / GFB mechanical DV", "note": "Adjustable spring pressure, no electronics. Overkill unless you're past K04 boost.", "price": "$150–250", "signal": "Big-turbo only", "links": []}], "tools": [{"name": "T30 Torx on a ¼\" ratchet with a wobble extension; a mirror"}, {"name": "Flat screwdriver for the connector lock"}], "before": ["Engine cold; the valve is on the turbo.", "Look at the new valve first so you know what you're feeling for: three bolt holes in a triangle and one connector."], "steps": [{"n": 1, "title": "Find it", "blocks": [{"t": "text", "b": "On the compressor (cold) side of the turbo, at the back of the engine on the driver's side: a round black valve with an electrical connector, held by three Torx bolts. Engine cover off; on some cars pulling the inlet pipe gives the room you need."}, {"t": "ill", "id": "dv-hero", "cap": "Three bolts in a triangle. The lower one is the awkward one."}]}, {"n": 2, "title": "Unplug and unbolt", "blocks": [{"t": "text", "b": "Slide the connector lock and unplug. Three T30 bolts; the bottom one usually needs the wobble extension and patience. Lift the valve out; note the o-ring."}]}, {"n": 3, "title": "Look at the old one", "blocks": [{"t": "text", "b": "A diaphragm valve shows a rubber disc; if it's torn or holed, that was your problem. A piston valve is the revision already; if it looks fine, your underboost is elsewhere (PCV, a split hose, the wastegate)."}]}, {"n": 4, "title": "New valve in", "blocks": [{"t": "text", "b": "New o-ring seated, valve in the same orientation, three bolts snug in turn (about 8 Nm; small bolts into aluminium). Connector on until it clicks. Cover on."}, {"t": "torque", "label": "Diverter valve bolts (T30 ×3)", "nm": 8, "c": {"level": "single", "n": 1, "note": "Snug figure from kit sheets; no factory value confirmed this pass."}}]}, {"n": 5, "title": "Drive it", "blocks": [{"t": "text", "b": "Clear codes if you had them. Boost should hold to redline and the flutter should be gone."}]}], "alsoReplace": [{"name": "PCV valve", "why": "The other diaphragm on this engine, with overlapping symptoms. If one is original, the other is too."}, {"name": "Turbo inlet coupler and charge hoses", "why": "Split rubber is the other cause of underboost. Squeeze them while you're there."}], "check": {"tab": "Is it the DV?", "title": "Is the diverter valve the problem?", "illId": "dv-hero", "illCap": "Torn diaphragm settles it.", "rows": [{"see": "P0299 underboost, boost falls off", "means": "DV, PCV, or a leak.", "do": "DV first if it's the diaphragm type; it's cheap."}, {"see": "Flutter on lift-off", "means": "DV not sealing or opening late.", "do": "Replace."}, {"see": "Piston DV already fitted, still underboost", "means": "Not the DV.", "do": "PCV, charge hoses, wastegate actuator."}], "c": {"level": "community", "n": 3, "note": "Forum diagnosis and vendor articles."}}, "aftercare": ["None. If the code returns, move down the list above."], "disagreements": [{"topic": "Rev D on an FSI?", "pos": "Officially the FSI valve is 06F; many owners fit the TSI D.", "call": "Either works; both are piston type."}], "sources": ["DAP 2.0T TSI common problems (DV section)", "ECS / vendor DV listings and revision notes", "Forum threads on DV symptoms and revisions"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('timing-chain-tensioner',$j${"id": "timing-chain-tensioner", "title": "Timing chain tensioner (critical)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "dv-hero", "alsoFits": "2.0T TSI Gen 1 (CCTA/CBFA)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "4–6 hr", "timeRepeat": "—", "difficulty": 4, "cost": "—", "risk": "—", "why": "The Gen 1 TSI's original lower timing chain tensioner can fail and let the engine jump time, which usually means bent valves or a wrecked engine. VW revised the tensioner. If your car still has the original, this is the single most important job on a TSI, and a rattle on cold start is the warning.", "note": "Owners report failures from 60,000 miles; a rattle at cold start is the classic warning. Difficulty 4: valve cover and timing cover off."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Owners report failures from 60,000 miles; a rattle at cold start is the classic warning. Difficulty 4: valve cover and timing cover off."], "earliest": null, "detail": "The Gen 1 TSI's original lower timing chain tensioner can fail and let the engine jump time, which usually means bent valves or a wrecked engine. VW revised the tensioner. If your car still has the original, this is the single most important job on a TSI, and a rattle on cold start is the warning.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder. It exists so the job is on the map for TSI owners; the full procedure, torque values and illustrations are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "dv-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["DAP 2.0T TSI common problems article", "EA888 Gen 1 build/tuning guides"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('intake-manifold-flap',$j${"id": "intake-manifold-flap", "title": "Intake manifold flap (P2015)", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "dv-hero", "alsoFits": "2.0T TSI Gen 1 (CCTA/CBFA)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "2–3 hr", "timeRepeat": "—", "difficulty": 3, "cost": "—", "risk": "—", "why": "The TSI intake manifold has a tumble flap on a plastic actuator arm. The arm's bracket wears and the flap motor throws P2015. The fix is a replacement manifold, or a bracket repair kit that many owners fit instead.", "note": "P2015 typically appears between 60,000 and 100,000 miles. Difficulty 3: manifold off for the full fix, bracket kit is simpler."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["P2015 typically appears between 60,000 and 100,000 miles. Difficulty 3: manifold off for the full fix, bracket kit is simpler."], "earliest": null, "detail": "The TSI intake manifold has a tumble flap on a plastic actuator arm. The arm's bracket wears and the flap motor throws P2015. The fix is a replacement manifold, or a bracket repair kit that many owners fit instead.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder. It exists so the job is on the map for TSI owners; the full procedure, torque values and illustrations are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "dv-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["DAP 2.0T TSI common problems article", "EA888 Gen 1 build/tuning guides"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('water-pump-tsi',$j${"id": "water-pump-tsi", "title": "Water pump & thermostat housing", "fits": "2008.5–2009 VW GTI · 2.0T TSI (CCTA/CBFA)", "heroId": "dv-hero", "alsoFits": "2.0T TSI Gen 1 (CCTA/CBFA)", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "3–4 hr", "timeRepeat": "—", "difficulty": 3, "cost": "—", "risk": "—", "why": "The TSI's water pump is a plastic housing driven by a small belt off the balance shaft, and it leaks. Coolant smell, a low level, or pink crust around the housing behind the engine are the signs. Replacement pumps leak again if the mating face isn't clean or the belt is reused.", "note": "Commonly leaking by 60,000–90,000 miles. Difficulty 3: access from below and behind, coolant drain and refill."}, "heroCap": "Placeholder illustration.", "lifespan": {"title": "When to expect it", "headline": ["Commonly leaking by 60,000–90,000 miles. Difficulty 3: access from below and behind, coolant drain and refill."], "earliest": null, "detail": "The TSI's water pump is a plastic housing driven by a small belt off the balance shaft, and it leaks. Coolant smell, a low level, or pink crust around the housing behind the engine are the signs. Replacement pumps leak again if the mating face isn't clean or the belt is reused.", "factors": [], "inspect": [], "confidence": {"level": "community", "n": 2, "note": "Stub; sourcing pending"}}, "should": {"yesIf": [], "codes": [], "notes": ["This guide is a placeholder. It exists so the job is on the map for TSI owners; the full procedure, torque values and illustrations are being sourced."], "confidence": {"level": "community", "n": 1, "note": "Stub"}}, "parts": [], "aftermarket": [], "tools": [], "before": [], "steps": [{"n": 1, "title": "Coming soon", "blocks": [{"t": "text", "b": "Full procedure pending. The summary above is accurate; use it to decide urgency."}]}], "alsoReplace": [], "check": {"tab": "Notes", "title": "What we know so far", "illId": "dv-hero", "illCap": "", "rows": [], "c": {"level": "community", "n": 1, "note": "Stub"}}, "aftercare": [], "disagreements": [], "sources": ["DAP 2.0T TSI common problems article", "EA888 Gen 1 build/tuning guides"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('sway-rear',$j${"id": "sway-rear", "title": "Rear sway bar upgrade", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "alsoFits": "2006–09 GTI/Rabbit (multilink) · 06–08 Jetta · 06–08 A3 8P FWD · 08+ TT 8J FWD · Mk6 GTI/Golf", "category": "Suspension", "kind": "upgrade", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$200–350", "risk": "Car on jack stands · exhaust clearance", "why": "Your GTI understeers because VW wanted it to. A stiffer rear bar hands some of that grip back to the front, so the car turns in sharper and stays flatter, without touching the ride.", "note": "Manufacturer guides say about 2 hours; owners report closer to 1. Wrestling the bar past the exhaust is the variable."}, "heroCap": "Looking up from under the rear of the car. The bar bolts to the subframe in two brackets and reaches each side through a short end link. Stock is 21.7 mm; upgrades run 24–27 mm.", "should": {"yesIf": ["The car pushes wide (understeers) in fast corners and you'd like it more neutral", "You've done tires and want the next real handling step", "You want a mod you can feel on the first drive", "You'd rather not change springs or dampers yet"], "codes": [], "notes": ["Rear-only is the classic first move on a front-wheel-drive car: the front already has plenty of roll stiffness from doing all the work, so stiffening the rear is what shifts the balance. Upgrading the front too mostly adds flatness, not balance.", "Trade-offs: a stiffer rear bar lifts the inside rear wheel sooner in hard cornering, and mid-corner bumps hit both sides. On all-season tires in the rain, the stiffest setting can make the tail livelier than you want."], "confidence": {"level": "high", "n": 4, "note": "Consistent across manufacturer descriptions, forum consensus, and basic vehicle dynamics."}}, "parts": [{"tier": "aftermarket", "name": "Rear sway bar kit (bar, bushings, hardware)", "pn": "see options below", "note": "Adjustable (two-hole) bars let you tune it later", "price": "$200–350", "links": []}, {"tier": "oe", "name": "Bracket bolts, M8 (×4)", "pn": "factory", "note": "Torque-to-yield style spec; new ones are cheap", "price": "$8", "links": []}, {"tier": "oe", "name": "End link nuts (×2)", "pn": "factory", "note": "Reusable, but replace if the nylon insert is tired", "price": "$4", "links": []}], "tools": [{"name": "Jack + two jack stands (or ramps)", "note": "final torque happens with the car on its wheels", "price": "$80–150"}, {"name": "10mm triple-square (XZN) bit", "note": "bracket bolts; decent quality, not a bargain-bin set", "price": "$10"}, {"name": "6mm triple-square bit", "note": "holds the end-link stud; it never turns anything", "price": "$8"}, {"name": "16mm wrench + 15mm wrench", "price": "$20"}, {"name": "Torque wrench, 20–60 Nm range", "price": "$40–80"}, {"name": "Poly bushing grease (if the kit's is stingy), tape or towels to protect the bar's finish", "price": "$10"}], "before": ["Level ground, wheels chocked, car in gear or Park. Jack stands on the rear jack points, never the subframe alone.", "Exhaust cold. You'll have your arms around it.", "Check the kit: bar, two bushings, two brackets (if supplied), hardware. Read the kit's sheet; where it gives its own torque values for its own hardware, those win.", "US 2006 GTIs have the multilink rear this guide covers. If your car has a solid beam axle (some base Golfs in other markets), this bar won't fit."], "steps": [{"n": 1, "title": "Raise the rear and support it", "blocks": [{"t": "text", "b": "Jack the rear and set both stands. Wheels can stay on; you're working inboard of them. A creeper or piece of cardboard makes the next hour nicer."}]}, {"n": 2, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "Each end of the bar has a short link with a stud through it. Put the 6mm triple-square into the stud's socket to hold it still, and turn the 16mm nut off. There's no room for a ratchet by the caliper; a wrench is fine, the nut isn't very tight."}, {"t": "ill", "id": "endlink", "cap": "The bit only holds the stud. If you try to turn the bit, it strips. Turn the nut."}, {"t": "warn", "b": "The bar is not under load. Nothing springs when the links come off."}]}, {"n": 3, "title": "Swing the bar free of the links", "blocks": [{"t": "text", "b": "Rotate the bar so each end drops out of its link. Leave the links attached to the trailing arms."}]}, {"n": 4, "title": "Unbolt the two brackets", "blocks": [{"t": "text", "b": "Two bolts per bracket into the subframe, 10mm triple-square. Support the bar as the last bolt comes out; it's heavier than it looks."}]}, {"n": 5, "title": "Wrangle the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "The bar has to rotate around the exhaust to clear. Turn it, tip it, and feed it out one side. If it won't go, loosen the rear muffler hangers (two bolts) to gain an inch of drop."}, {"t": "note", "b": "Pull the old bushings and brackets off it now if you're reusing them. Compare old and new bars side by side; the arm shape should match."}]}, {"n": 6, "title": "Bushings onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of each bushing with the supplied poly grease (not petroleum grease, which swells polyurethane). Slide them onto the bar at the same positions as the old ones, then set the brackets over them."}, {"t": "note", "b": "Powder coat scratches easily. Leave the plastic wrap on the bar until it's up in the car."}]}, {"n": 7, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of step 5. Get the brackets up to the subframe and start all four bolts by hand. Snug, don't torque, so the bar can still rotate."}]}, {"n": 8, "title": "Pick your setting and connect the links", "blocks": [{"t": "fork", "q": "Which hole?", "v": [{"label": "Forward (softer)", "when": "Start here", "blocks": [{"t": "text", "b": "Roughly double the stock bar's rate on a 25mm bar. A clear step up in turn-in and flatness with no drama. Drive it a week before you decide you want more."}]}, {"label": "Rearward (stiffer)", "when": "Sticky tires, track days", "blocks": [{"t": "text", "b": "About 2.5× stock on a 25mm bar. Sharper still, with more inside-rear wheel lift and a livelier tail in the wet. Common second step, rare first one."}]}]}, {"t": "text", "b": "Rotate the bar so the chosen hole lines up with each end-link stud, pass the stud through, and start the nuts. Snug only."}]}, {"n": 9, "title": "Lower the car, then torque everything", "caution": true, "blocks": [{"t": "text", "b": "The factory manual says these fasteners get their final torque with the car sitting on its wheels, not hanging on stands. Otherwise the bushings and links are clamped at the wrong angle and you get clunks and early bushing wear. Lower onto ramps, or onto the ground and reach under."}, {"t": "torque", "label": "Bracket bolts (M8, ×4) · factory hardware", "nm": 25, "c": {"level": "single", "n": 1, "note": "Bentley manual value via TDIClub: 25 Nm then a further 45° turn. If your kit supplied its own brackets and bolts, use the kit's number (034: 25 Nm flat, with Loctite)."}, "note": "+45° turn"}, {"t": "torque", "label": "End link nuts (M10, ×2)", "nm": 45, "alt": [35], "c": {"level": "varies", "n": 2, "note": "45 Nm is the factory value for factory hardware. 35 Nm is what 034 specifies for its own nylock hardware. Follow whichever hardware you're actually tightening."}}, {"t": "warn", "b": "A forum regular guessed 50 lb-ft (68 Nm) on these and stretched the bolts. Both fasteners are smaller than they feel. Use the wrench."}]}, {"n": 10, "title": "Test drive and re-check", "blocks": [{"t": "text", "b": "Drive 20–50 miles with a few firm corners, then re-torque all six fasteners. Clunking over one-wheel bumps means a bracket or link is loose or the bushing wasn't greased."}]}], "check": {"tab": "Pick a setting", "title": "Which setting is right for you?", "illId": "setting", "illCap": "Both holes are on the same bar. Closer to the pivot is stiffer because the lever is shorter.", "rows": [{"see": "Daily driver, all-season tires", "means": "You want turn-in and less lean, not a tail that steps out in the rain.", "do": "Forward hole. Most people never move it."}, {"see": "Summer tires, spirited driving", "means": "The chassis can use more rear roll stiffness before it gets nervous.", "do": "Start forward, try rearward after a week. Expect more inside-wheel lift."}, {"see": "Autocross or track", "means": "Balance matters more than comfort, and you'll adjust per event.", "do": "Rearward, and consider adjustable end links so both sides preload evenly."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus manufacturer stiffness figures. There is no factory guidance; this is a preference."}}, "aftercare": ["Re-torque after the first 20–50 miles, then forget about it.", "A squeak on slow speed bumps is a dry bushing. Some brackets have a grease port; otherwise pull the bracket and re-grease.", "Adjustable end links are the usual next step if you go to the stiff hole: they let you remove preload so the bar isn't twisted at rest."], "disagreements": [{"topic": "End link torque", "pos": "45 Nm (factory) vs 35 Nm (034's hardware) vs 55 Nm (Mk7 guides).", "call": "45 for factory hardware, kit value for kit hardware. Mk7 numbers are a different car and excluded."}, {"topic": "Torque on stands or on the ground?", "pos": "Manufacturer PDFs torque on the lift; the factory manual says curb weight.", "call": "Snug in the air, final torque on the wheels."}, {"topic": "Which hole first?", "pos": "“Full stiff rear” vs “start soft.”", "call": "Start soft. It's a two-minute change later."}, {"topic": "Front bar too?", "pos": "Some do both.", "call": "Rear first. On a FWD car it's the balance change; the front is mostly flatness."}], "sources": ["034Motorsport install guide (Mk5/6 FWD)", "Pelican Parts Mk5 GTI rear stabilizer DIY", "TDIClub torque thread citing the Bentley manual", "VWVortex APR 27mm install thread", "GolfMKV H&R 22mm install thread", "Neuspeed product data (stiffness by hole)", "Owner reviews (exhaust clearance, finish)"], "embeds": [{"id": "S8KnvgU-MLQ", "note": "ECS Tuning on a Mk5/Mk6. Same rear subframe and brackets as your car."}, {"id": "2ts5lTilGiM", "note": "034 install and the why-upgrade case"}], "aftermarket": [{"name": "Neuspeed 25mm, adjustable", "note": "Tubular, red, two-hole. Forward hole ≈2× stock, rearward ≈2.5×. The most-recommended bar in Mk5 threads.", "price": "$290", "signal": "Forum favorite", "links": [{"store": "Neuspeed", "url": "https://neuspeed.com/products/neuspeed-anti-sway-bar-rear-25mm-2502253"}]}, {"name": "034Motorsport solid, adjustable", "note": "Solid bar, billet brackets with grease ports, Teflon bushings. Stiffest of the common choices (150%+ over stock).", "price": "$300–350", "signal": "Track-leaning pick", "links": []}, {"name": "H&R 24mm", "note": "Non-adjustable, softer step up. Good if you want less body roll without changing the car's character much.", "price": "$200–250", "signal": "Mild option", "links": []}, {"name": "Whiteline 24mm, adjustable", "note": "Adjustable, well-reviewed, often bundled with their end links.", "price": "$230–280", "signal": "Value pick", "links": []}], "lifespan": {"title": "When owners do this", "headline": ["Usually the first or second handling mod, right after tires"], "earliest": null, "detail": "The stock bar doesn't wear out, so there's no failure mileage. Owners upgrade it when they notice the car pushing wide in fast corners, typically before touching springs or dampers because it's cheaper and reversible.", "factors": ["Sticky summer tires make the understeer more noticeable", "Lowering springs stiffen the front, which increases the case for a rear bar"], "inspect": ["While you're under there: end links and bushings are often tired by 80,000+ miles; replace them if they're loose or cracked"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus on ordering; the end-link mileage is anecdotal."}}, "heroId": "rsbhero"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('sway-front',$j${"id": "sway-front", "title": "Front sway bar upgrade", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "alsoFits": "2006–09 GTI/Rabbit · 05–10 Jetta · 06–08 A3 8P · Mk6 GTI/Golf (same PQ35 front subframe)", "category": "Suspension", "kind": "upgrade", "variants": {"question": "How far do you want to take it apart?", "hint": "The bar hides behind the subframe, so the subframe has to come down either way. Owners mostly lower it a few inches and unbolt the steering rack from it. Manufacturer instructions drop it further and also disconnect the steering column, ball joints and tie rods.", "options": [{"id": "partial", "label": "Partial lower (owner method)", "when": "Fewer parts touched, tighter to work in. Recommended for a driveway."}, {"id": "full", "label": "Full drop (manufacturer method)", "when": "More room, more disconnecting, steering-column care needed. Best on a lift."}]}, "glance": {"timeFirst": "3–5 hr", "timeRepeat": "2 hr with a lift and a helper", "difficulty": 4, "cost": "$250–450 + alignment", "risk": "Subframe on a jack · single-use stretch bolts · alignment afterwards", "why": "The rear bar changed the car's balance. The front bar is about grip: less roll means the outside front tire stays flatter on the road, so a strut car like this one stops giving away camber mid-corner.", "note": "One vendor calls this 'easy'. Every owner account says three hours, two people, and an alignment. Believe the owners."}, "heroCap": "The bar sits in the channel between the subframe and the steering rack. There is no way to get it out without lowering the subframe.", "lifespan": {"title": "When owners do this", "headline": ["Usually after the rear bar and tires, before or with coilovers"], "earliest": null, "detail": "The stock bar doesn't wear out. Owners add a front bar when they've already done the rear and want the front to stop washing out, or as part of a bigger suspension job while the subframe is already down.", "factors": ["Rear bar already installed", "Coilovers or lowering springs going in", "Track days"], "inspect": ["While the subframe is down: dogbone (pendulum) mount bushing and front control-arm bushings are worth a look"], "confidence": {"level": "community", "n": 5, "note": "Forum consensus on ordering. Which bar is a preference."}}, "should": {"yesIf": ["You've done the rear bar and the front still pushes wide", "You want flatter cornering without harsher ride", "You're already dropping the subframe for something else", "You have a torque wrench that does angle, or a patient helper and a marker"], "codes": [], "notes": ["A stiffer front bar on a front-driver sounds like it should add understeer. In practice it reduces body roll, which keeps the loaded front tire upright, so it usually adds front grip rather than taking it away. Rear bar first, then front, is the order almost everyone lands on.", "This is the most involved job in the app so far. Nothing is dangerous once the car is on stands, but a subframe on a floor jack wants a second person, and the alignment afterwards is not optional."], "confidence": {"level": "high", "n": 6, "note": "Method and rationale agree across the manufacturer guide, four forum DIYs, and a magazine test."}}, "parts": [{"tier": "aftermarket", "name": "Front sway bar kit (bar, poly bushings, brackets, grease)", "pn": "see options below", "note": "Most kits include the stretch bolts you need; check yours", "price": "$250–400", "links": []}, {"tier": "oe", "name": "Subframe & control-arm bolts, M12 (×6)", "pn": "single-use", "note": "Stretch bolts. Every source says replace", "price": "$30–50", "links": []}, {"tier": "oe", "name": "Steering rack bolts, M10 (×4)", "pn": "single-use", "note": "Also stretch bolts", "price": "$15", "links": []}, {"tier": "oe", "name": "Pendulum (dogbone) mount bolts", "pn": "single-use", "note": "Two into the transmission", "price": "$10", "links": []}, {"tier": "oe", "name": "End-link nuts (×2)", "pn": "self-locking", "note": "Replace whenever removed", "price": "$4", "links": []}, {"tier": "oe", "name": "Steering shaft u-joint bolt", "pn": "single-use", "note": "Full-drop method only", "price": "$5", "links": [], "only": ["full"]}], "aftermarket": [{"name": "ECS Tuning 26mm", "note": "Solid, non-adjustable, comes with poly bushings, all stretch bolts and subframe spacer plates. The install PDF is the most complete one available.", "price": "$300", "signal": "Best documented", "links": [{"store": "ECS Tuning install PDF", "url": "https://assets.ecstuning.com/edoc/PDF_9205_Volkswagen_MK5-MK6_ECS_Front_Sway_Bar_Installation.pdf"}]}, {"name": "H&R 26mm", "note": "Tubular, non-adjustable, rubber-lined bushings that need no greasing. The bar the 2008 owner DIYs were written around.", "price": "$250–300", "signal": "Forum favorite", "links": []}, {"name": "034Motorsport adjustable", "note": "Two-hole adjustable, billet brackets. Grassroots Motorsports ran it on the soft setting and set a personal best.", "price": "$350–450", "signal": "Track-leaning pick", "links": []}, {"name": "APR / Hotchkis", "note": "Same bar under two names. Instructions insisted on load on the wheels throughout; owners found that only matters for the end links.", "price": "$300–350", "signal": "Fine, with that caveat", "links": []}], "tools": [{"name": "Floor jack + two stands, plus a second jack (or transmission jack) for the subframe", "note": "A board on the jack pad spreads the load"}, {"name": "Sockets: 13, 16, 17, 18, 21mm · ½\" breaker bar", "note": "The 21mm subframe bolts are very tight"}, {"name": "6mm triple-square or 5mm hex (end links) · T20/T25 Torx (belly pan)"}, {"name": "Torque wrench that reads to 120 Nm, and an angle gauge (or a marker for the +90° turns)"}, {"name": "Pry bar, penetrating oil, wire brush, marker or paint pen for reference marks"}, {"name": "Angle grinder (optional)", "note": "Owners cut the hollow stock bar in two rather than wrestle it out", "only": ["partial"]}], "before": ["Level ground. Stands on the body jack points, never under the subframe you're about to drop.", "Raise both sides of the front together; one side up puts the bar under load.", "Mark the subframe's position on the body with a paint pen before a single bolt comes out. Its outline (the 'footprint') is your only alignment reference.", "Book an alignment for afterwards. Subframe position sets toe and camber; you will not get it back exactly by eye.", "Full-drop method: park with the steering wheel dead straight and keep it there. Rotating the wheel with the column disconnected can damage the airbag clockspring."], "steps": [{"n": 1, "title": "Steering shaft (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Inside the car, remove the two 13mm fasteners on the steering-shaft cover at the pedals and lift it off. Remove the u-joint bolt where the shaft meets the rack and slide the joint up off the rack. It's a single-use bolt."}, {"t": "warn", "b": "From this point until the joint is back on, nobody turns the steering wheel. A rotated clockspring is an airbag light at best."}]}, {"n": 2, "title": "Raise the front, wheels off, belly pan off", "blocks": [{"t": "text", "b": "Loosen the lug bolts (17mm) on the ground, raise both sides, stands under the body. Wheels off. Remove the plastic belly pan or insulation tray (T20/T25) so you can see the subframe."}]}, {"n": 3, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "18mm nut on each link at the bar. If the stud spins, hold it with a 6mm triple-square (some links: 5mm hex) and turn the nut. They're often seized: wire-brush the exposed thread, soak with penetrating oil, and work the nut back and forth. Don't heat them; the joint boot won't survive it."}, {"t": "ill", "id": "fsb-endlink", "cap": "Stud held, nut turned. Same technique front and rear."}]}, {"n": 4, "title": "Headlight level sensor (if you have HIDs)", "blocks": [{"t": "text", "b": "Driver's side, above the lower control arm: unplug the sensor and unbolt its arm bracket from the arm (10mm). Note which way the joint points so it goes back the same."}]}, {"n": 5, "title": "Ball joints and tie rods (full drop only)", "only": ["full"], "blocks": [{"t": "text", "b": "Remove the three 16mm ball-joint nuts each side and pull the control arm down off the joint; a pry bar between them if they're corroded together. Remove both outer tie-rod nuts (18mm) and pop the tie rods out of the bearing housings with a separator, or a sharp hammer blow to the housing."}]}, {"n": 6, "title": "Unbolt everything hanging on the subframe", "blocks": [{"t": "text", "b": "Two exhaust hanger bolts at the rear of the subframe (13mm). The four steering-rack bolts (13mm), two per side, where the rack sits on the subframe. The four sway-bar bracket bolts (13mm)."}, {"t": "text", "b": "Pendulum (dogbone) mount: two bolts into the transmission (16mm) and, on the partial method, the two into the subframe (13mm) so the mount comes free.", "only": ["partial"]}, {"t": "text", "b": "Pendulum mount: remove the two bolts into the transmission (16mm).", "only": ["full"]}]}, {"n": 7, "title": "Jack under the subframe, then the big bolts", "caution": true, "blocks": [{"t": "text", "b": "Second jack (with a board) snug under the middle of the subframe. Now the six 18mm/21mm subframe and control-arm bolts: two long ones at the rear, two at the rear control-arm brackets, two forward ones hidden behind the control arms (socket on a 6-inch extension). Loosen the forward pair first; remove them last."}, {"t": "warn", "b": "The subframe is heavy and the jack is the only thing holding it. Have your helper steady it from here on. Never put any part of you under it."}, {"t": "torque", "label": "Subframe & control-arm bolts (M12, on reassembly)", "nm": 70, "c": {"level": "varies", "n": 2, "note": "Manufacturer: 70 Nm + 90°. Owner table: 70 Nm (52 lb-ft) + 45°. Same base value; the angle differs. We show the manufacturer's."}, "note": "+90° turn"}]}, {"n": 8, "title": "Lower the subframe", "blocks": [{"t": "text", "b": "Lower the jack slowly and evenly, about four inches, watching the steering rack: it needs to lift off its dowel pins and come free of the subframe. A screwdriver under the rack helps release the pins. The rack stays connected to the column and just hangs.", "only": ["partial"]}, {"t": "text", "b": "Lower the jack a little at a time. As soon as you can reach it, remove the hidden 10mm bolt holding the steering-rack wiring harness to the rack (driver's side, inside the subframe) and release the harness clip a few inches along. Then lower until the bar is fully exposed, and lift the rack slightly rearward off its dowel pins.", "only": ["full"]}, {"t": "ill", "id": "fsb-drop", "cap": "Subframe on the jack, lowered. The bar comes out over the passenger side of the subframe, forward and down, while the driver's end threads between the subframe and rack."}]}, {"n": 9, "title": "Get the old bar out", "timeSink": true, "blocks": [{"t": "text", "b": "Lift the bar up and over the passenger-side subframe arm, bring it forward and down, and guide the driver's end between the subframe and the rack. Two people, some swearing, several attempts. The bushings snag on the rack; snapping the old brackets off the bar first helps."}, {"t": "note", "b": "Owner shortcut: with the bar still bolted in, cut it in half with a grinder. The stock bar is hollow and goes quickly. Eye protection; you're on your back under sparks. Then each half comes out easily.", "only": ["partial"]}]}, {"n": 10, "title": "Bushings and brackets onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of poly bushings with the kit's grease (never petroleum grease; never any grease on factory rubber bushings). Slide them on against the stops. Lower brackets under, uppers on top, raised face up, bolt holes outboard. Some kits fit the brackets loosely at this point; others want them fully seated. Follow the kit sheet."}]}, {"n": 11, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of removal: driver's end between rack and subframe first, then lift the passenger end over. Set the bar in front of the rack. Adjust the rack's position as needed so the bar drops into place."}]}, {"n": 12, "title": "Raise the subframe and start every bolt by hand", "caution": true, "blocks": [{"t": "text", "b": "Raise the jack until the subframe meets the body. Seat the steering rack onto its dowel pins first; if it isn't fully seated you'll end up with a loose rack. Then start, by hand and loosely, in this order: rear control-arm bolts, the four rack bolts, the four sway-bar bracket bolts, forward subframe bolts, then the two long rear subframe bolts. Full-drop: reconnect the harness clip and its 10mm bolt as the subframe comes up.", "only": ["partial", "full"]}, {"t": "text", "b": "Kits that supply subframe spacer plates: they go between the subframe and body at the rear mounts. Fit them whether or not the car had them.", "only": ["partial", "full"]}, {"t": "text", "b": "Now align. Nudge the subframe until every bolt hole lines up with your paint marks and the footprint. Loosen the 'horns' and rear brackets if it won't move; snug bolts fight you. Only when everything lines up do you tighten anything."}, {"t": "warn", "b": "Tighten nothing to torque until all fourteen bolts are started and the subframe is on its marks. One bolt torqued early locks the subframe in the wrong place and you'll be doing this again after the alignment shop calls."}, {"t": "torque", "label": "Steering rack bolts (M10)", "nm": 50, "c": {"level": "varies", "n": 2, "note": "Manufacturer 50 Nm + 90°; owner table 37 lb-ft + 45°. Same base value."}, "note": "+90° turn"}, {"t": "torque", "label": "Sway bar bracket bolts (M8)", "nm": 20, "c": {"level": "varies", "n": 2, "note": "Manufacturer 20 Nm + 90°; owner table 15 lb-ft + 45°."}, "note": "+90° turn"}, {"t": "torque", "label": "Pendulum mount bolts", "nm": 40, "alt": [50], "c": {"level": "medium", "n": 2, "note": "40 Nm for 8.8-grade bolts, 50 Nm for 10.9-grade, each + 90°. Check the number stamped on the bolt head."}, "note": "+90° turn"}, {"t": "ill", "id": "fsb-bolts", "cap": "Order matters: seat the rack, start everything loose, align to your marks, then torque. Subframe and arm bolts get their angle last."}]}, {"n": 13, "title": "Reconnect the rest", "blocks": [{"t": "text", "b": "Exhaust hanger back on the subframe. Ball joints: three nuts each side, 60 Nm for a cast arm or 100 Nm for an aluminium/sheet-steel arm. Tie rods: 20 Nm + 90°. Level sensor arm and plug.", "only": ["full"]}, {"t": "text", "b": "Exhaust hanger back on the subframe. Level sensor arm and plug.", "only": ["partial"]}, {"t": "text", "b": "Steering shaft: seat the u-joint back on the rack and torque the new bolt to 30 Nm. Only now may the wheel turn.", "only": ["full"]}]}, {"n": 14, "title": "End links, on the ground", "blocks": [{"t": "text", "b": "Pass the studs through the bar's holes (adjustable bars: start on the softer, outer hole), start new self-locking nuts. Wheels on, torque to 120 Nm, lower the car. Then torque the end-link nuts with the car on its wheels so the links aren't preloaded."}, {"t": "torque", "label": "End-link nuts (M10)", "nm": 65, "c": {"level": "high", "n": 3, "note": "65 Nm / 48 lb-ft agrees across the manufacturer guide, an MQB guide and a forum torque thread."}}]}, {"n": 15, "title": "Alignment, then re-check", "blocks": [{"t": "text", "b": "Drive gently to the alignment shop. Tell them the subframe was lowered. After 50 miles, re-check the end links and that nothing clunks over one-wheel bumps."}]}], "alsoReplace": [{"name": "Pendulum (dogbone) mount insert or bushing", "why": "It's unbolted anyway, and a tired one is the usual source of drivetrain clunk on these cars. A poly insert is $30 and ten minutes here versus an hour on its own."}, {"name": "Front sway-bar end links", "why": "They're off. If the boots are cracked or the joints have play, new ones now save a second trip under the car."}, {"name": "Subframe alignment (Deadset-style) kit", "why": "Replaces the subframe's slop with locating sleeves so it can't shift under load. Only sensible while the bolts are already out."}], "check": {"tab": "Pick a setting", "title": "Which hole, if your bar is adjustable?", "illId": "setting", "illCap": "Same logic as the rear bar: the hole closer to the pivot is stiffer.", "rows": [{"see": "Street car, all-season or touring tires", "means": "You want the roll reduction without changing balance much.", "do": "Softer (outer) hole. Most stay here."}, {"see": "Summer tires, already on the stiff rear setting", "means": "The car may have gone tail-happy; the front bar brings balance back.", "do": "Softer hole first, evaluate, then stiffer if the front still rolls more than the rear."}, {"see": "Track use", "means": "You'll tune front and rear together per event.", "do": "Stiffer hole, adjustable end links front and rear."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus one magazine test (fastest lap on the soft setting)."}}, "aftercare": ["Alignment within the first drive or two. Not optional.", "Re-torque end links after 50 miles.", "Poly bushings squeak when dry; re-grease at the first squeak.", "Clunk from the front on take-off after this job: check the pendulum mount bolts."], "disagreements": [{"topic": "Full drop or partial lower?", "pos": "Manufacturer disconnects steering column, ball joints and tie rods and drops the subframe fully; owners lower it about four inches and unbolt the rack.", "call": "Both work. Partial for a driveway, full on a lift. You choose at the top of the guide."}, {"topic": "+45° or +90° on the stretch bolts?", "pos": "Manufacturer PDF says +90°; the 2008 owner table says +45° on the same base values.", "call": "Manufacturer, since it's current and cites the bolt sizes. The base torque agrees everywhere."}, {"topic": "How hard is it?", "pos": "'Skill Level 1 – Easy' vs. every owner account.", "call": "4 out of 5. Plan a full afternoon and a helper."}, {"topic": "Load on the wheels during install?", "pos": "APR's sheet said keep the car loaded throughout; owners found the subframe wouldn't align that way.", "call": "Unloaded for the subframe and rack; loaded only for the final end-link torque."}], "sources": ["ECS Tuning Mk5/Mk6 Front Sway Bar installation PDF (2019)", "VWVortex 'DIY: Front Sway Bar Install' (2008)", "MyFastGTI 'MK5 Front Swaybar DIY' (2008)", "Pelican Parts front sway bar bushings article", "GolfMKV APR install troubleshooting thread (2013)", "Golfmk6 install threads (2014, 2015)", "Grassroots Motorsports 034 front bar test (2023)"], "embeds": [], "heroId": "fsb-drop"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('endlinks',$j${"id": "endlinks", "title": "Sway bar end links", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "alsoFits": "2006–09 GTI/Rabbit · 05–10 Jetta · 06–08 A3 · Mk6 GTI/Golf", "category": "Suspension", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Front links run from the sway bar up to a bracket on the strut. Rear links run from the bar down to the trailing arm. Same technique, different sizes and torque.", "options": [{"id": "front", "label": "Front end links", "when": "18mm nut, 6mm triple-square"}, {"id": "rear", "label": "Rear end links", "when": "16mm nut, 6mm triple-square"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$30–120 a pair", "risk": "Car on stands · seized nuts", "why": "End links are the two little rods that connect the sway bar to the suspension. When their ball joints wear, the bar rattles instead of working, and you hear it as a clunk over every manhole cover.", "note": "Four sources, all under an hour. Seized nuts are the only variable."}, "heroCap": "Front link: bar to strut bracket. Rear link: bar to trailing arm. Each end has a stud with a socket in its tip so you can hold it while the nut turns.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front links: commonly loose or rattling past 80,000–120,000 miles", "only": ["front"]}, {"text": "Rear links: often still fine past 100,000; check whenever the bar is off", "only": ["rear"]}], "earliest": "Sooner on cars with stiffer aftermarket bars, which load the joints harder", "detail": "The symptom is a hollow clunk or rattle from one corner over small bumps, worst at low speed. Grab the link with the car on stands and wiggle: any play in the joint, or a torn boot, and it's done.", "factors": ["Aftermarket sway bar", "Lowered car (links at an angle)", "Salt-belt corrosion"], "inspect": ["Check whenever you're under the car with a wheel off"], "confidence": {"level": "community", "n": 4, "note": "Owner reports and vendor notes; no factory interval. Mileage is anecdotal."}}, "should": {"yesIf": ["Clunk or rattle from a corner over small bumps", "Visible play when you wiggle the link by hand", "Torn or missing rubber boot on a joint", "You just fitted a stiffer bar and the old links have miles on them"], "codes": [], "notes": ["Both sides. If one has worn, the other is close, and a mismatched pair loads the bar unevenly."], "confidence": {"level": "high", "n": 4, "note": "Symptoms and technique agree across vendor articles and forum threads."}}, "parts": [{"tier": "oe", "name": "Front end link, Genuine/OEM (each)", "pn": "Lemförder, TRW or Meyle HD", "note": "Lemförder is the OE maker", "price": "$25–45", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear end link, Genuine/OEM (each)", "pn": "Lemförder or Meyle HD", "note": "", "price": "$20–35", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Self-locking nuts (×4)", "pn": "factory", "note": "Replace every time they come off", "price": "$6", "links": []}], "aftermarket": [{"name": "Adjustable end links (034, Whiteline, SuperPro)", "note": "Let you set the length so the bar sits unloaded at rest, which matters once the car is lowered or the bar is on its stiff setting. Heim-joint types are noisier and want greasing.", "price": "$120–250 a pair", "signal": "Worth it if lowered", "links": []}, {"name": "Moog / heavy-duty fixed links", "note": "Bigger joints than OE at OE length. A common, cheap answer to a rattle on a stock-height car.", "price": "$40–70 a pair", "signal": "Budget pick", "links": []}], "tools": [{"name": "Jack + two stands; 17mm for the lug bolts"}, {"name": "18mm wrench (ratcheting open-end is ideal) and a 6mm triple-square bit", "only": ["front"]}, {"name": "16mm wrench and a 6mm triple-square bit", "only": ["rear"]}, {"name": "Penetrating oil, wire brush, torque wrench to 65 Nm"}], "before": ["Raise both sides of that axle together. One wheel up loads the bar and the links won't come off without a fight.", "Soak the nuts with penetrating oil while you get the wheels off.", "Final torque happens with the car back on its wheels."], "steps": [{"n": 1, "title": "Raise the axle, wheels off", "blocks": [{"t": "text", "b": "Loosen lugs on the ground, raise both sides of the axle, stands under the body, wheels off."}]}, {"n": 2, "title": "Find the link", "blocks": [{"t": "text", "b": "Behind the strut, a short rod from the end of the sway bar up to a bracket on the strut body. Two nuts: one at the bar, one at the strut.", "only": ["front"]}, {"t": "text", "b": "Inboard of the wheel, a short rod from the end of the sway bar down to the trailing arm. Two nuts: one at the bar, one at the arm.", "only": ["rear"]}, {"t": "ill", "id": "fsb-endlink", "cap": "Triple-square in the stud's tip to hold it still; wrench on the nut does the turning."}]}, {"n": 3, "title": "Remove the nuts", "blocks": [{"t": "text", "b": "18mm on the nut. If the whole stud spins, put the 6mm triple-square into the socket in the stud's tip and hold it while you turn the nut. Work a seized nut back and forth rather than forcing it, and re-oil. No heat; the boot won't survive it.", "only": ["front"]}, {"t": "text", "b": "16mm on the nut, 6mm triple-square holding the stud if it spins. Work a seized nut back and forth and re-oil. No heat.", "only": ["rear"]}, {"t": "note", "b": "The bar isn't under load with both wheels up. Nothing springs when the link comes off."}]}, {"n": 4, "title": "Swap the link", "blocks": [{"t": "text", "b": "Pull the old link out, compare lengths with the new one, and fit the new one the same way round. Start new self-locking nuts by hand at both ends. Snug only."}]}, {"n": 5, "title": "Other side", "blocks": [{"t": "text", "b": "Repeat. Both sides, always."}]}, {"n": 6, "title": "Wheels on, car down, then torque", "blocks": [{"t": "text", "b": "Wheels on (120 Nm), lower the car, roll it a foot to settle. Then torque the link nuts with the weight on the wheels so the joints aren't clamped at a strange angle."}, {"t": "torque", "label": "Front end-link nuts", "nm": 65, "c": {"level": "high", "n": 3, "note": "65 Nm / 48 lb-ft: manufacturer guide, MQB guide, forum torque thread."}, "only": ["front"]}, {"t": "torque", "label": "Rear end-link nuts", "nm": 45, "c": {"level": "single", "n": 1, "note": "Factory manual value via a forum thread. Kit hardware may specify less; follow the kit."}, "only": ["rear"]}]}], "alsoReplace": [{"name": "Sway bar bushings", "why": "Rear bushings are two bolts away once the links are off. Front bushings can be swapped without dropping the subframe (Pelican confirms), and a dry rubber bushing is the other source of front-end squeak."}], "check": {"tab": "Is it the link?", "title": "Is the noise really the end link?", "illId": "fsb-endlink", "illCap": "Wiggle test: any play here, or a torn boot, is a bad link.", "rows": [{"see": "Hollow clunk over small bumps, one corner, low speed", "means": "Classic end link. Confirm with the wiggle test.", "do": "Replace both links on that axle."}, {"see": "Creak or groan when turning into a driveway", "means": "More likely the sway bar bushings or a strut top mount.", "do": "Check bushings first; they're cheaper."}, {"see": "Knock on acceleration or gear change", "means": "Drivetrain mount, usually the pendulum (dogbone) mount.", "do": "Different job; see the front sway bar guide's 'while you're in there'."}], "c": {"level": "community", "n": 3, "note": "Forum diagnosis threads plus vendor articles."}}, "aftercare": ["Re-check torque after 50 miles.", "If a new link rattles immediately, the nut was torqued in the air or the link length is wrong for a lowered car."], "disagreements": [{"topic": "Which bit holds the stud?", "pos": "6mm triple-square (most sources), 5mm hex (ECS's own links), '16mm triple-square' (Pelican, clearly a typo).", "call": "6mm triple-square for factory links; check your new links' studs."}, {"topic": "Torque in the air or on the ground?", "pos": "Vendor guides torque on the lift; the factory manual says curb weight.", "call": "On the ground."}, {"topic": "Front torque", "pos": "65 Nm (PQ35/MQB sources) vs 90 Nm (a 2005 thread).", "call": "65. The 90 Nm figure is Mk4."}], "sources": ["ECS Tuning front sway bar PDF", "VWVortex 'Sway Bar Link Replacement?' (2016)", "Pelican Parts drop-link article", "1A Auto Mk5/6 end-link video guide", "IE and Eco-de Tuning MQB guides (technique only)", "TDIClub Bentley torque thread"], "embeds": [], "heroId": "fsb-endlink"}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('catback',$j${"id": "catback", "title": "Cat-back exhaust install", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "catback-hero", "alsoFits": "2006–09 GTI, 2- and 4-door (same system) · Jetta uses a longer system", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which downpipe is on the car?", "hint": "The stock downpipe ends in a 60mm slip joint, so an aftermarket cat-back needs a reducer adapter to meet it. A 3-inch aftermarket downpipe mates directly.", "options": [{"id": "stockdp", "label": "Stock downpipe", "when": "Fit the reducer adapter and clamps that came with the cat-back"}, {"id": "aftdp", "label": "3-inch aftermarket downpipe", "when": "Direct connection, leave the adapter in the box"}]}, "glance": {"timeFirst": "2–3 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$600–1,200", "risk": "Heavy · two people · patience with alignment", "why": "The stock cat-back is quiet and heavy, with a resonator and a big muffler tuned for silence. A straight-through 3-inch system gives the car its voice and drops real weight off the back. On a stock turbo it's the sound you're paying for; the power comes with a downpipe and tune.", "note": "Vendors and owners agree: the removal is easy, the last hour is alignment."}, "heroCap": "Downpipe joint at the front, mid-pipe over the chassis brace and past the fuel tank, muffler, tips. Five rubber hangers hold it. Nothing gets tightened until it all hangs straight.", "lifespan": {"title": "When owners do this", "headline": ["Usually the first exhaust mod; often before the downpipe"], "earliest": null, "detail": "Nothing to wear out on the aftermarket side. Owners do it for sound, weight and looks. A stock system that's rusted through or rattling at 120k+ makes the decision for you.", "factors": ["Stock muffler rusting or rattling", "Downpipe going in (do both, skip the adapter)", "You want the sound now"], "inspect": ["Re-check clamps and hanger positions after the first few heat cycles"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus and vendor positioning."}}, "should": {"yesIf": ["You want the car to sound like a GTI", "Stock system is rusting, dented or rattling", "You're planning a downpipe and want a 3-inch path all the way back", "You have a helper and an afternoon"], "codes": [], "notes": ["Two-door and four-door Mk5 GTIs use the same cat-back. Vendors list one part number for both; there's nothing to choose here. The Jetta is the longer car and uses a different system."], "confidence": {"level": "high", "n": 3, "note": "Fitment confirmed by vendor listings; procedure consistent across guides."}}, "parts": [{"tier": "aftermarket", "name": "Cat-back system", "pn": "see options below", "note": "Mid-pipe, muffler, tips, clamps, hangers, reducer adapter", "price": "$600–1,200", "links": []}, {"tier": "oe", "name": "Exhaust hanger rubbers (×5)", "pn": "factory", "note": "Cheap; replace any that are cracked or stretched", "price": "$6 each", "links": []}, {"tier": "oe", "name": "Silicone spray, anti-seize", "pn": "—", "note": "Hangers and slip joints", "price": "$10", "links": []}], "aftermarket": [{"name": "ECS Tuning 3\" cat-back (valved or non-valved)", "note": "T304, slip joints for adjustability, hangers welded in OE spots, adjustable tips. The valved version needs a boost tap. Install guide is the reference for this whole guide.", "price": "$900–1,200", "signal": "Best documented", "links": [{"store": "ECS install instructions", "url": "https://blog.ecstuning.com/vw-mk5-gti-ecs-valved-exhaust-system-installation-instructions/"}]}, {"name": "Borla S-Type 140248", "note": "2.5\" system, straight-through mufflers, listed for 2- and 4-door. Tamer volume, aluminised steel option. Long-running forum favourite for a daily.", "price": "$800–1,000", "signal": "Daily-driver pick", "links": [{"store": "Borla", "url": "https://www.borla.com/products/volkswagen-gti-cat-back-exhaust-system-140248"}]}, {"name": "Ultimate Racing 3\" configurable", "note": "Pick your mid-pipe (no muffler, centre muffler) and tips. Slip-fit to the stock downpipe with an adapter for their downpipe.", "price": "$700–1,000", "signal": "Build your own sound", "links": []}, {"name": "Unitronic, Milltek, APR, Eurojet", "note": "All 3\" T304 systems with OE hanger positions. Milltek is the quiet-and-refined end; Eurojet the loud end.", "price": "$800–1,500", "signal": "Fine choices", "links": []}], "tools": [{"name": "Jack + four stands, or a lift; a second person"}, {"name": "Sockets: 13, 15, 17mm · exhaust hanger pliers"}, {"name": "Torque wrench to 25 Nm; penetrating oil; silicone spray"}, {"name": "Ball-peen hammer for gently rounding shipping-dented slip joints"}], "before": ["Lay the new system out on the floor in order and test every slip joint. If one won't slide, tap the pipe end round with a hammer until it does.", "Leave the protective wrap on the mufflers until they're in the car.", "Support the exhaust from below at every stage. Never let it hang from one hanger.", "Two people to lower the old system. It is heavier than it looks."], "steps": [{"n": 1, "title": "Up on stands, split the front joint", "blocks": [{"t": "text", "b": "Car on four stands, level. Soak the sleeve-clamp nuts at the downpipe joint and the hanger rubbers. Loosen the two nuts on the sleeve clamp (17mm) and slide the sleeve forward or back to separate the joint. Don't remove the nuts."}]}, {"n": 2, "title": "Free the hangers", "blocks": [{"t": "text", "b": "Stand under the middle of the system. With hanger pliers (or a pry bar and silicone spray), pop every rubber hanger off its pin except the right-rear muffler hanger. Note where each hanger sits; the new system uses the same spots."}, {"t": "ill", "id": "catback-hero", "cap": "Five hangers. Leave the right-rear one until last; it's on a bolted bracket and holds the muffler while you work."}]}, {"n": 3, "title": "Lower the old system", "caution": true, "blocks": [{"t": "text", "b": "Loosen the two 13mm bolts on the right-rear hanger bracket, remove one, leave the other finger-tight. With your helper holding the muffler and you the front, pull the last bolt, make sure the front joint is separated, and lower the whole system as one piece, bracket attached."}, {"t": "warn", "b": "The stock system comes down as one long, heavy piece. Two people, both ready, or it comes down on one of you."}, {"t": "text", "b": "Put the right-rear bracket bolt back in on its own to hold the heat shield (23 Nm). Pry the factory hanger rubbers off the old muffler if the new system reuses them."}]}, {"n": 4, "title": "Adapter on the downpipe", "only": ["stockdp"], "blocks": [{"t": "text", "b": "Anti-seize on the downpipe's tail. Slide the kit's reducer adapter on with its clamp loose. This is what lets a 3-inch system meet the 60mm stock joint."}]}, {"n": 4, "title": "Check the 3-inch joint", "only": ["aftdp"], "blocks": [{"t": "text", "b": "No adapter. Clean the downpipe's slip end or V-band face and put anti-seize on the slip surface. Have the kit's clamp ready and loose."}]}, {"n": 5, "title": "Hang it front to back, everything loose", "blocks": [{"t": "text", "b": "Silicone spray on every hanger. Clamp over the muffler inlet, lift the muffler in, slide it onto the mid-pipe (or the adapter), and hook its brackets into the hangers. Stand under it. Then the tailpipe section, the Y-pipe with its hanger bracket, and the tips with their clamps, all twisting to seat, all loose."}, {"t": "note", "b": "The temptation is to snug each clamp as you go so it stops moving. Don't. A clamp tightened early locks a misalignment in and you'll take the whole thing apart again to fix it."}]}, {"n": 6, "title": "Align, patiently", "caution": true, "blocks": [{"t": "text", "b": "Set each hanger so the bottom hole is 10–15mm ahead of the top hole, leaning toward the front of the car; the pipe grows rearward as it heats and the hangers swing back. Then walk the system: clearance over the chassis braces at the front, around the fuel tank in the middle, at the rear crossmember, and tips centred in the bumper cut-out. Adjust slip joints by twisting, not forcing."}, {"t": "text", "b": "Snug the front clamps by hand, check again, snug the rear clamps, check again. Only then torque everything, front to back, and set the tips."}, {"t": "torque", "label": "Sleeve and slip-joint clamps", "nm": 19, "c": {"level": "medium", "n": 2, "note": "ECS instructions; no factory figure. Hand-snug first, no impact."}, "only": ["stockdp", "aftdp"]}, {"t": "warn", "b": "Anything that touches the body or a brace will resonate through the cabin at 2,000 rpm forever. Fifteen minutes of alignment now saves that."}]}, {"n": 7, "title": "Braces back, start it, drive it", "blocks": [{"t": "text", "b": "Refit any chassis brace you removed for access. Start the engine and feel each joint for leaks. Drive it, let it heat-cycle, and re-check hanger angle and clamp torque the next day. Expect the tips to have shifted a few millimetres; centre them again."}]}], "alsoReplace": [{"name": "Exhaust hanger rubbers", "why": "Original rubbers on a car this age are hard and cracked. Five new ones are a few dollars and stop the new system knocking on the body."}, {"name": "Downpipe", "why": "Same braces off, same afternoon. If Stage 2 is in your future, do both and connect them directly."}], "check": {"tab": "How loud?", "title": "How loud do you want it?", "illId": "catback-hero", "illCap": "Resonator and muffler choices are what set volume; pipe diameter mostly sets tone.", "rows": [{"see": "Daily, long drives, passengers", "means": "Drone on the highway will make you hate it.", "do": "Resonated system with a real muffler (Borla, Milltek, ECS non-valved). Avoid resonator deletes."}, {"see": "Weekend car, want to hear it", "means": "Some drone is acceptable for the sound.", "do": "3\" straight-through with a centre muffler; valved ECS if you want both."}, {"see": "Track or show", "means": "Volume is the point.", "do": "Muffler-less mid-pipe options. Check your track's dB limit first."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; volume is subjective."}}, "aftercare": ["Re-check clamps and hanger angle after the first heat cycles and again at 500 miles.", "A rattle over bumps is a hanger touching or a loose heat shield.", "Drone that appears later means a slip joint has crept; re-align."], "disagreements": [{"topic": "2-door vs 4-door", "pos": "Assumed to differ.", "call": "Same system on the Mk5 GTI; the Jetta differs."}, {"topic": "Tighten as you go?", "pos": "Instinct says yes.", "call": "Every guide says no. Loose until aligned."}], "sources": ["ECS Tuning Mk5 GTI valved exhaust installation instructions (2017)", "Borla 140248 fitment listing", "ECS, Ultimate Racing and Malian cat-back listings (adapter/fitment)", "IE Mk7 cat-back guide (technique)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-pads',$j${"id": "brake-pads", "title": "Brake pads", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "brake-hero", "alsoFits": "2006–09 GTI · 05–10 Jetta 2.0T (312mm front / 286mm rear) · A3 8P 2.0T", "category": "Brakes", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Different calipers, different tools. Front pistons push back; rear pistons have to be screwed back.", "options": [{"id": "front", "label": "Front pads", "when": "7mm hex guide bolts, 312mm rotor, wear sensor"}, {"id": "rear", "label": "Rear pads", "when": "13mm guide bolts, 286mm rotor, piston screws in"}]}, "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "40 min", "difficulty": 2, "cost": "$50–150 per axle", "risk": "Car on stands · brake fluid · never touch friction surfaces with greasy hands", "why": "Pads are the part of the brake that's designed to wear away. On the GTI the fronts do most of the work and go first; the rears last longer but bind up more. It's the most common job on any car, and one of the most satisfying to do yourself.", "note": "Vendor and forum times agree: about an hour an axle, longer the first time you meet a seized rotor screw."}, "heroCap": "Caliper (piston side) slides on two guide pins in the carrier. Two small bolts free the caliper; two big ones free the carrier. For pads only, the carrier stays.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front pads: typically 30,000–50,000 miles", "only": ["front"]}, {"text": "Rear pads: typically 50,000–70,000 miles", "only": ["rear"]}], "earliest": "Much sooner with track use or a sticking caliper slide pin", "detail": "The wear sensor on the front inner pad lights the dash when the pad reaches about 3mm. Rears have no sensor; look through the wheel or pull it. A pad worn to the backing plate scores the rotor and turns a pad job into a rotor job.", "factors": ["Spirited or track driving", "Sticking guide pins (uneven wear)", "City stop-and-go", "A stuck parking brake (rears)"], "inspect": ["Every tire rotation: pad thickness through the wheel spokes"], "confidence": {"level": "community", "n": 4, "note": "Owner reports and vendor notes; no factory mileage exists because it depends on the driver."}}, "should": {"yesIf": ["Pad warning light on the dash (front)", "Less than about 3mm of friction material left", "Squeal at low speed that goes away when you brake harder (wear indicator)", "Grinding: you're already into the rotor"], "codes": [], "notes": ["Pads and rotors: if the rotor has a lip at the edge you can catch a fingernail on, or the pads wore unevenly, do rotors too (that's the next guide). New pads on a worn rotor bed in badly and feel soft.", "Both sides of an axle, always, with the same pad compound."], "confidence": {"level": "high", "n": 4, "note": "Standard practice; consistent across sources."}}, "parts": [{"tier": "oe", "name": "Front pad set, Genuine/OEM (TRW or Textar)", "pn": "1K0 698 151 (confirm by VIN)", "note": "Includes wear sensor on most kits", "price": "$60–90", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear pad set, Genuine/OEM", "pn": "1K0 698 451 (confirm by VIN)", "note": "", "price": "$40–70", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Rear caliper guide-pin bolts, M8x22 (×4)", "pn": "self-locking", "note": "Replace every time (ECS, Bentley)", "price": "$6", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Front pad wear sensor", "pn": "if not in the kit", "note": "The old one is usually cut through", "price": "$10", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Brake caliper grease, brake cleaner", "pn": "—", "note": "Silicone or ceramic paste for pad ears and guide pins", "price": "$12", "links": []}], "aftermarket": [{"name": "Ferodo DS2500 / Hawk HPS", "note": "Street-performance compounds: more bite, more dust, fine cold. The forum default for a spirited daily.", "price": "$120–180", "signal": "Spirited-daily pick", "links": []}, {"name": "EBC Redstuff / Yellowstuff", "note": "Red for low dust street; Yellow for track days but noisy on the street.", "price": "$100–160", "signal": "Know which colour you want", "links": []}, {"name": "Akebono Euro ceramic", "note": "Quiet, very low dust, slightly less bite than OE. Popular for a clean-wheels daily.", "price": "$60–90", "signal": "Low-dust pick", "links": []}], "tools": [{"name": "Jack + stands, 17mm for lugs"}, {"name": "7mm hex bit (front caliper guide bolts), flat screwdriver for the spring clip", "only": ["front"]}, {"name": "13mm socket + 15mm wrench (rear caliper bolts), rear piston retractor tool (cube or wind-back kit)", "only": ["rear"]}, {"name": "Large C-clamp or piston spreader (front)", "only": ["front"]}, {"name": "Wire brush, brake cleaner, bungee or wire to hang the caliper, torque wrench to 35 Nm"}], "before": ["Loosen the reservoir cap and remove a little fluid if it's near MAX; pushing pistons back raises the level.", "Never let the caliper hang by its hose.", "Both sides of the axle in one session."], "steps": [{"n": 1, "title": "Wheel off, look", "blocks": [{"t": "text", "b": "Lugs loose on the ground, raise the axle, stands under the body, wheel off. Look at the pad through the caliper window and at the rotor edge for a lip."}]}, {"n": 2, "title": "Free the caliper", "blocks": [{"t": "text", "b": "Pry the big spring clip off the caliper face with a screwdriver. Unplug the wear-sensor wire from its clip. Pull the two rubber caps off the back of the caliper and remove the two 7mm hex guide bolts. Lift the caliper off the carrier and hang it from the spring with a bungee.", "only": ["front"]}, {"t": "text", "b": "Pry the spring clip off. Hold each guide pin with a 15mm wrench and remove the 13mm bolt; discard the bolts. Lift the caliper off and hang it. The parking-brake cable stays connected.", "only": ["rear"]}, {"t": "ill", "id": "brake-hero", "cap": "Guide bolts (small) free the caliper; carrier bolts (large) stay put for a pad job."}]}, {"n": 3, "title": "Old pads out, clean everything", "blocks": [{"t": "text", "b": "Pull the pads out of the carrier (front: the inner pad clips into the piston). Wire-brush the carrier's pad seats until the new pads slide freely in them; a pad that binds here is what causes uneven wear. Check the guide-pin boots and that the pins slide."}]}, {"n": 4, "title": "Retract the piston", "caution": true, "blocks": [{"t": "text", "b": "Put the old inner pad across the piston and squeeze it back with a C-clamp, slowly, watching the reservoir level.", "only": ["front"]}, {"t": "text", "b": "Rear pistons screw in. Use the retractor tool to turn the piston clockwise while pushing; do not just squeeze it or you'll wreck the parking-brake mechanism inside. Stop when it's flush and line up one of the piston's notches with the nub on the new inner pad.", "only": ["rear"]}, {"t": "warn", "b": "Slow. A piston forced back too fast can pop the master-cylinder seals or overflow the reservoir onto the paint."}]}, {"n": 5, "title": "New pads in", "blocks": [{"t": "text", "b": "Thin smear of caliper grease on the pad ears and the back of the pads (never the friction face). Outer pad into the carrier, inner pad clipped into the piston (front) or seated with its nub in the piston notch (rear). New wear sensor clipped into the inner pad and routed the same way as the old one."}]}, {"n": 6, "title": "Caliper back on", "blocks": [{"t": "text", "b": "Lower the caliper over the pads, grease and fit the guide bolts, and torque them. Refit the rubber caps and the spring clip.", "only": ["front", "rear"]}, {"t": "torque", "label": "Front caliper guide bolts (7mm hex)", "nm": 28, "alt": [35], "c": {"level": "varies", "n": 3, "note": "28 Nm (Bentley), 30 and 35 Nm in forum tables for the same caliper. Any of these is fine; they're small bolts, don't overdo them."}, "only": ["front"]}, {"t": "torque", "label": "Rear caliper bolts (M8, new, 13mm)", "nm": 35, "c": {"level": "high", "n": 3, "note": "ECS, Bentley and forum agree: 35 Nm, new self-locking bolts."}, "only": ["rear"]}]}, {"n": 7, "title": "Other side, then pump the pedal", "blocks": [{"t": "text", "b": "Repeat on the other side. Wheels on (120 Nm). Before you drive: pump the brake pedal until it's firm so the pistons take up the gap. Check the reservoir level and cap it."}]}, {"n": 8, "title": "Bed them in", "blocks": [{"t": "text", "b": "A few gentle stops, then five or six firm stops from 40 mph without coming to a complete halt, then a few minutes of driving without braking to cool. Skip this and the pads glaze and squeal for weeks."}]}], "alsoReplace": [{"name": "Rotors", "why": "If there's a lip or scoring, the extra work is two carrier bolts and a set screw. See the rotor guide."}, {"name": "Brake fluid", "why": "If it's dark or over two years old, you already have the wheels off. See the flush guide."}], "check": {"tab": "Read the wear", "title": "Reading the old pads", "illId": "brake-hero", "illCap": "Uneven wear is a caliper problem, not a pad problem.", "rows": [{"see": "Both pads worn evenly, 2–3mm left", "means": "Normal end of life.", "do": "Replace pads."}, {"see": "Inner pad far more worn than outer", "means": "Guide pins sticking or piston sluggish.", "do": "Clean and grease pins; if the piston won't retract smoothly, rebuild or replace the caliper."}, {"see": "Tapered wear across one pad", "means": "Carrier pad seats corroded; pad can't float.", "do": "Wire-brush the carrier seats hard, or replace the carrier."}, {"see": "Pad worn to metal, rotor scored", "means": "Way past due.", "do": "Pads and rotors."}], "c": {"level": "community", "n": 3, "note": "Standard diagnosis; consistent across sources."}}, "aftercare": ["Bed in properly.", "Re-check guide bolt torque after 100 miles if you had to fight the caliper on.", "Squeal after a week: pads not bedded, or the anti-rattle spring is off."], "disagreements": [{"topic": "Front guide-bolt torque", "pos": "28, 30 and 35 Nm across sources for the same caliper.", "call": "28–35. Not a critical value."}, {"topic": "Reuse caliper bolts?", "pos": "Rear bolts are self-locking and every source says replace; front OE pads come with new bolts and thread-locker.", "call": "New on the rear; front, reuse with blue thread-locker if the kit didn't include them."}], "sources": ["ECS Tuning Mk5 GTI rear pads and rotors procedure", "myturbodiesel Mk5 Golf torque thread (Bentley)", "Golfmk7 and Golfmk6 brake torque threads", "Audizine PQ35 rear caliper thread"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-rotors',$j${"id": "brake-rotors", "title": "Brake rotors (and pads)", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "brake-hero", "alsoFits": "2006–09 GTI · 05–10 Jetta 2.0T · A3 8P 2.0T", "category": "Brakes", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Front rotors are 312mm and the carrier bolts are big and tight. Rear rotors are 286mm and the carrier bolts are stretch bolts you replace.", "options": [{"id": "front", "label": "Front rotors", "when": "Carrier bolts 190–200 Nm, reuse"}, {"id": "rear", "label": "Rear rotors", "when": "Carrier bolts 90 Nm + 90°, replace"}]}, "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$120–300 per axle with pads", "risk": "Very tight carrier bolts · seized set screw · heavy front rotors", "why": "Rotors wear a fraction of a millimetre per pad set and warp if they overheat. When there's a lip at the edge, grooves you can feel, or a shudder under braking, they're done. Always with new pads: a fresh pad on a worn rotor never beds right.", "note": "The set screw is the wildcard. Plan for it to strip and have a drill ready."}, "heroCap": "Carrier off (two big bolts), set screw out, rotor off the hub. Clean the hub face before the new rotor goes on or you'll build in a wobble.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front rotors: typically every second pad set, 60,000–100,000 miles", "only": ["front"]}, {"text": "Rear rotors: typically 80,000–120,000 miles, often rust-limited rather than wear-limited", "only": ["rear"]}], "earliest": "Sooner if pads were run to metal, or on track cars", "detail": "Minimum thickness is stamped on the rotor hat (MIN TH). Measure with a caliper gauge away from the lip. Salt-belt cars usually lose rear rotors to rust pitting long before they're thin.", "factors": ["Pads run to the backing plate", "Track days", "Road salt (rears especially)", "Sticking caliper"], "inspect": ["Every pad change: thickness against the MIN TH stamp, and run a fingernail across the face"], "confidence": {"level": "community", "n": 4, "note": "Owner practice; the MIN TH stamp is the only hard number."}}, "should": {"yesIf": ["Lip at the rotor edge you can catch a nail on", "Shudder or pulsing pedal under braking", "Grooves or heat spots on the face", "Below the MIN TH stamped on the hat", "Pads wore to metal"], "codes": [], "notes": ["Slotted or drilled? On a street car neither does much beyond looks, and drilled rotors can crack from the holes with track heat. Plain or slotted blanks from a good maker are the value pick."], "confidence": {"level": "high", "n": 4, "note": "Standard practice; consistent."}}, "parts": [{"tier": "oe", "name": "Front rotors, 312mm (pair)", "pn": "1K0 615 301 (confirm by VIN)", "note": "Zimmermann, ATE, Brembo blanks are OE-quality", "price": "$90–160", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear rotors, 286mm (pair)", "pn": "1K0 615 601 (confirm by VIN)", "note": "", "price": "$70–120", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Pads for the same axle", "pn": "see the pads guide", "note": "Always with rotors", "price": "$40–150", "links": []}, {"tier": "oe", "name": "Rotor set screws, T30 (×2)", "pn": "N 906 218 01", "note": "You will destroy at least one", "price": "$3", "links": []}, {"tier": "oe", "name": "Rear carrier bolts (×4)", "pn": "M12, torque-to-yield", "note": "Replace (ECS, Bentley, forums)", "price": "$12", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Rear caliper guide-pin bolts (×4)", "pn": "M8x22 self-locking", "note": "Replace", "price": "$6", "links": [], "only": ["rear"]}], "aftermarket": [{"name": "Zimmermann coated / ATE PremiumOne (pairs with pads)", "note": "OE-spec blanks with an anti-rust coating on the hat and edges. The sensible upgrade.", "price": "$100–180", "signal": "Value pick", "links": []}, {"name": "StopTech / Brembo slotted", "note": "Slots help with pad gassing on track and look the part. Slightly more pad wear.", "price": "$180–300", "signal": "Spirited pick", "links": []}, {"name": "Big brake kit (R32 345mm carriers, or aftermarket BBK)", "note": "A different project: bigger rotors, different carriers, wheel clearance to check. Not this guide.", "price": "$500+", "signal": "Different job", "links": []}], "tools": [{"name": "Jack + stands, 17mm for lugs, breaker bar"}, {"name": "21mm socket for the front carrier bolts (½\" drive, they are very tight); 7mm hex for guide bolts; C-clamp", "only": ["front"]}, {"name": "18mm or 21mm for the rear carrier bolts (check yours); 13mm + 15mm for caliper bolts; rear piston retractor", "only": ["rear"]}, {"name": "T30 Torx and an impact driver for the set screw; drill and bits for when it strips"}, {"name": "Wire brush or Roloc disc for the hub face; torque wrench to 200 Nm; angle gauge (rear)"}], "before": ["Penetrating oil on the set screw and carrier bolts while you get the wheel off.", "Front rotors are heavy; don't drop one on a toe or the carrier's threads.", "Reservoir cap loose, level checked."], "steps": [{"n": 1, "title": "Wheel off, caliper off", "blocks": [{"t": "text", "b": "Follow the pads guide to free the caliper and hang it (spring clip, sensor wire, guide bolts). Pull the old pads."}]}, {"n": 2, "title": "Carrier off", "caution": true, "blocks": [{"t": "text", "b": "Two big bolts behind the hub hold the carrier to the knuckle. Breaker bar, steady pull. Lift the carrier away.", "only": ["front", "rear"]}, {"t": "warn", "b": "Rear carrier bolts are torque-to-yield: they stretch once and are done. Throw them away and fit new ones on reassembly, or they can back out.", "only": ["rear"]}, {"t": "warn", "b": "Front carrier bolts are torqued to 190–200 Nm and can be rusted in. Keep the breaker bar in line and your knuckles clear when it lets go.", "only": ["front"]}]}, {"n": 3, "title": "Set screw and rotor", "timeSink": true, "blocks": [{"t": "text", "b": "T30 impact driver on the set screw: a few sharp hits, then turn. If it rounds, drill the head off; the rotor comes off and the stub unscrews with pliers. Then the rotor: a few whacks with a hammer on the hat between the studs, or a bolt threaded into the hub's puller hole, breaks the rust bond."}, {"t": "ill", "id": "brake-hero", "cap": "Set screw is only there to hold the rotor while the wheel is off. Snug, never tight."}]}, {"n": 4, "title": "Clean the hub face", "blocks": [{"t": "text", "b": "Wire brush or Roloc disc the hub face back to bare metal, especially the raised ring the rotor sits on. Any rust flake left behind is runout you'll feel as a shudder in a month. Wipe the new rotor's face with brake cleaner to remove the shipping oil."}]}, {"n": 5, "title": "New rotor and carrier", "blocks": [{"t": "text", "b": "Rotor on, set screw in snug (about 4 Nm; just enough to hold it). Carrier over the rotor, bolts in.", "only": ["front", "rear"]}, {"t": "torque", "label": "Front carrier bolts (×2, reuse)", "nm": 190, "alt": [200], "c": {"level": "varies", "n": 3, "note": "190 Nm (Bentley) vs 200 Nm (forum tables). Either; it's a big bolt and both are in range."}, "only": ["front"]}, {"t": "torque", "label": "Rear carrier bolts (×2, NEW)", "nm": 90, "c": {"level": "high", "n": 3, "note": "90 Nm then a further 90° turn, new bolts every time. ECS, Bentley and forums agree."}, "note": "+90° turn", "only": ["rear"]}]}, {"n": 6, "title": "Pads and caliper", "blocks": [{"t": "text", "b": "Continue with the pads guide from 'Retract the piston': new pads, caliper on, guide bolts torqued, clip and sensor back."}]}, {"n": 7, "title": "Other side, pump, bed in", "blocks": [{"t": "text", "b": "Repeat. Wheels on at 120 Nm. Pump the pedal firm before moving. Bed in: several firm stops from 40 mph, then cool. New rotors and pads need this more than pads alone."}]}], "alsoReplace": [{"name": "Wheel bearing check", "why": "Hub is exposed. Spin it and feel for roughness; a grumble now is a bearing job later."}, {"name": "Brake fluid flush", "why": "Wheels are off; see the flush guide."}, {"name": "Rear caliper parking-brake return spring", "why": "If the lever is sluggish, the caliper is on its way to sticking.", "only": ["rear"]}], "check": {"tab": "Read the rotor", "title": "Reading the old rotor", "illId": "brake-hero", "illCap": "A lip means wear; blue spots mean heat; rust ring means the pad isn't contacting.", "rows": [{"see": "Even wear, small lip, above MIN TH", "means": "Serviceable.", "do": "Could reuse with new pads, but bedding is worse. Most replace."}, {"see": "Grooves, blue heat spots, shudder", "means": "Overheated or run with worn pads.", "do": "Replace. Check caliper function."}, {"see": "Heavy rust pitting on the outer inch (rears)", "means": "Pad isn't sweeping the whole face; typical salt-belt rear.", "do": "Replace rotor and pads; check the caliper slides."}], "c": {"level": "community", "n": 3, "note": "Standard diagnosis."}}, "aftercare": ["Bed in.", "Shudder after new rotors: hub face wasn't clean, or lug bolts were tightened in a star pattern by impact. Re-torque by hand.", "Re-check carrier bolts after 100 miles."], "disagreements": [{"topic": "Front carrier torque", "pos": "190 vs 200 Nm.", "call": "190–200."}, {"topic": "Drilled rotors", "pos": "Look good; some forum voices swear by them.", "call": "Slotted or plain for anything that sees heat."}], "sources": ["ECS Tuning Mk5 GTI rear pads and rotors procedure", "myturbodiesel Bentley torque thread", "Golfmk7 / Golfmk6 torque threads", "Audizine PQ35 caliper thread"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-flush',$j${"id": "brake-flush", "title": "Brake fluid flush", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "bleed-order", "alsoFits": "All Mk5 platform cars (Golf, Jetta, A3, Eos): same order", "category": "Brakes", "kind": "repair", "variants": {"question": "Manual or DSG?", "hint": "Manual cars share the brake reservoir with the clutch slave cylinder, which gets bled first.", "options": [{"id": "manual", "label": "6-speed manual", "when": "Clutch slave bled first"}, {"id": "dsg", "label": "DSG", "when": "Brakes only"}]}, "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$25–40 (fluid) + a $50 pressure bleeder once", "risk": "Fluid eats paint · don't let the reservoir run dry", "why": "Brake fluid absorbs water from the air through the hoses. Wet fluid boils at a lower temperature (soft pedal after hard stops) and corrodes the ABS unit and calipers from the inside. VW says change it every two years; almost nobody does.", "note": "An hour with a pressure bleeder. Double that with a helper on the pedal."}, "heroCap": "VW's order is front-left, front-right, rear-left, rear-right, because of how the ABS unit is plumbed. Clutch slave first on a manual.", "lifespan": {"title": "When to expect it", "headline": ["Factory: first change at 3 years, then every 2 years, regardless of miles"], "earliest": null, "detail": "Time, not distance. Fluid that's dark amber or brown in the reservoir is overdue. A cheap test strip or moisture tester tells you the water content; above 3% is time.", "factors": ["Humid climate", "Track days (boil it once and it's done)", "Unknown history"], "inspect": ["Look at the reservoir colour at every oil change"], "confidence": {"level": "medium", "n": 3, "note": "Factory schedule via a vendor summary; owner practice agrees."}}, "should": {"yesIf": ["Over two years since the last flush, or unknown", "Fluid is dark", "Pedal goes soft after repeated hard stops", "You just did calipers, lines, or a clutch"], "codes": [], "notes": ["DOT 4 only, from a sealed bottle. An opened bottle on the shelf has been absorbing water for months. Buy small bottles.", "If the reservoir runs dry during the job, air enters the ABS unit and a scan tool (VCDS) is needed to cycle it out. Keep it topped."], "confidence": {"level": "high", "n": 4, "note": "Method and rationale consistent across the manual, two owner write-ups and vendor guidance."}}, "parts": [{"tier": "oe", "name": "DOT 4 brake fluid, 1.5 L", "pn": "VW 501 14 spec (ATE TYP200, Pentosin, Motul DOT 4)", "note": "Sealed bottles", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Bleeder nipple dust caps", "pn": "if missing", "note": "", "price": "$4", "links": []}], "aftermarket": [{"name": "ATE TYP200 / Motul RBF600", "note": "Higher dry and wet boiling points for track use. RBF600 needs more frequent changes; TYP200 is the sensible middle.", "price": "$20–35 / L", "signal": "Track-day pick", "links": []}], "tools": [{"name": "Pressure bleeder (Motive or similar) with the VW/Audi 45mm cap", "note": "Turns a two-person job into one"}, {"name": "11mm wrench (flare nut or ratcheting), clear hose, catch bottle"}, {"name": "Turkey baster, rags, spray bottle of water for drips"}], "before": ["Cover the paint around the reservoir and behind each wheel.", "Pump the bleeder to 10–15 psi, not 30; higher isn't needed and stresses the master-cylinder seals.", "Wheels off makes the rear nipples much easier, but it can be done through the spokes."], "steps": [{"n": 1, "title": "Wheels off (recommended)", "blocks": [{"t": "text", "b": "Raise the car on four stands, wheels off, or do it one axle at a time. Find the bleeder nipple on each caliper (top, inboard) and pop the dust cap."}]}, {"n": 90, "title": "Set up the pressure bleeder", "blocks": [{"t": "text", "b": "Turkey-baster the old fluid out of the reservoir down to the minimum line and refill with fresh DOT 4 from a sealed bottle. Screw the bleeder cap onto the reservoir and pump it to 10–15 psi. Keep the reservoir topped the whole time; if it runs dry the ABS unit takes in air and only a scan tool can bleed it."}, {"t": "warn", "b": "Brake fluid strips paint in minutes. Cover the fender and wing, keep a spray bottle of water handy, and wipe drips immediately."}]}, {"n": 91, "title": "Bleed in the manual's order", "caution": true, "blocks": [{"t": "text", "b": "Manual car first: 11mm on the clutch slave bleeder (on the bell housing), let 50 ml run, close, pump the clutch pedal 10–15 times, open again for another 50 ml, close.", "only": ["manual"]}, {"t": "text", "b": "The brakes: front-left, front-right, rear-left, rear-right. Yes, front first; the ABS unit's layout makes the usual furthest-first rule wrong on this car. At each caliper: dust cap off, 11mm wrench on the nipple, hose into a catch bottle, open until the fluid runs clear and bubble-free, close, cap."}, {"t": "ill", "id": "bleed-order", "cap": "The order VW specifies. Clutch slave first on a manual."}, {"t": "note", "b": "Finishing touch owners swear by: after the pressure bleed, have a helper do five firm pedal strokes per caliper (open the nipple with the pedal down, close before it comes up) to chase any last air."}]}, {"n": 92, "title": "Close up and test", "blocks": [{"t": "text", "b": "Release bleeder pressure, remove the cap, set the reservoir level between the marks (not above MAX; the pads will wear and the level will rise as they're changed). Pedal should be firm within the first inch. Drive gently around the block, brake progressively harder, and check every bleeder for weeping."}]}], "alsoReplace": [{"name": "Clutch slave bleed", "why": "On a manual it shares the reservoir; it's already first in the order.", "only": ["manual"]}, {"name": "Rear brake hose check", "why": "Look for cracks or bulges in the rubber hoses while you're at each corner. See the stainless-line guide if they're tired."}], "check": {"tab": "Read the fluid", "title": "What came out?", "illId": "bleed-order", "illCap": "Colour tells the story.", "rows": [{"see": "Pale yellow, clear", "means": "Recent. Someone loved this car.", "do": "Note the date; next in two years."}, {"see": "Amber to brown", "means": "Years old, wet.", "do": "Flush until clear at every corner. Expect more than a litre."}, {"see": "Black flecks or sludge", "means": "Seals breaking down or a caliper cooking the fluid.", "do": "Flush, then inspect that caliper for drag; rebuild if it's hot after a drive."}], "c": {"level": "community", "n": 3, "note": "Standard practice."}}, "aftercare": ["Write the date on a bit of tape on the reservoir.", "Firm pedal after the first drive: done. Soft pedal: bleed again in the same order; if still soft, the ABS unit has air and needs a scan-tool bleed."], "disagreements": [{"topic": "Bleed order", "pos": "VW manual: FL, FR, RL, RR. Pelican and general practice: RR, LR, RF, LF.", "call": "The manual. The ABS unit's layout is the reason, and VW says 'proper bleeding cannot be ensured' otherwise."}, {"topic": "Bleeder pressure", "pos": "10 psi vs 2 bar (30 psi).", "call": "10–15 psi."}], "sources": ["VWVortex threads quoting the Mk5 repair manual bleed sequence", "MicksGarage Project GTI bleeding write-up", "Pelican Parts Mk5 GTI bleeding article", "DAP Mk5 service schedule", "Passat B6 (same platform) bleed procedure"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-lines-ss',$j${"id": "brake-lines-ss", "title": "Stainless brake lines", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "bleed-order", "alsoFits": "All Mk5 platform cars", "category": "Brakes", "kind": "upgrade", "glance": {"timeFirst": "2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$100–180 for four", "risk": "Fluid on paint · line routing · full bleed required", "why": "The rubber hoses at each wheel swell a little every time you press the pedal. Braided stainless lines don't, so the pedal feels firmer and more consistent, especially when the fluid's hot. It's the same job as replacing tired rubber hoses, just with a better part.", "note": "Two hours including the flush that has to follow. The lines themselves are ten minutes a corner."}, "heroCap": "Each corner has one flexible hose from the hard line on the body to the caliper. Swap the hose, then bleed in VW's order.", "lifespan": {"title": "When owners do this", "headline": ["Usually with a pad/rotor upgrade or when a rubber hose shows cracks, often past 100,000 miles"], "earliest": null, "detail": "Rubber hoses don't have a factory replacement interval but they age: surface cracks, bulging under pressure, or a hose that's soft to squeeze means it's overdue. Owners fit stainless at that point because the price gap is small.", "factors": ["Track days", "Rubber hoses cracked or bulging", "Doing a brake flush anyway"], "inspect": ["Every fluid flush: squeeze and look at each hose"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus; no factory interval."}}, "should": {"yesIf": ["Pedal feels soft or inconsistent when hot", "Rubber hoses are cracked, bulging, or original at 100k+", "You're flushing the fluid anyway", "You want the last bit of pedal feel from a pad upgrade"], "codes": [], "notes": ["Buy DOT-compliant lines from a real brand with a PTFE core and a protective outer sleeve. The cheap unbranded sets are the one place in this app where 'aftermarket' can mean 'worse than stock'."], "confidence": {"level": "medium", "n": 3, "note": "Rationale and method consistent; no factory torque for the fittings was found this pass."}}, "parts": [{"tier": "aftermarket", "name": "Stainless brake line set (4)", "pn": "see options below", "note": "Front and rear, with new banjo bolts and copper washers if the kit includes them", "price": "$100–180", "links": []}, {"tier": "oe", "name": "DOT 4 fluid, 1.5 L", "pn": "—", "note": "Full flush follows", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Copper crush washers for banjo fittings", "pn": "if not in kit", "note": "Never reuse", "price": "$5", "links": []}], "aftermarket": [{"name": "StopTech / Goodridge G-Stop", "note": "DOT-compliant, PTFE core, colour sleeve, all clips and washers. The two names the forums trust.", "price": "$120–180", "signal": "Forum favorite", "links": []}, {"name": "ECS / USP stainless kits", "note": "Same construction, often bundled with a fluid flush kit.", "price": "$100–150", "signal": "Value pick", "links": []}], "tools": [{"name": "11mm flare-nut wrench (hard-line unions) and 14mm/17mm for banjo bolts; 11mm for bleeders"}, {"name": "Pressure bleeder, hose, catch bottle, turkey baster"}, {"name": "Line clamp or a bag over the reservoir to slow the drip while a line is off; rags; water spray"}], "before": ["Flare-nut wrench only on the hard-line unions; an open-end wrench rounds them and then you're replacing hard lines.", "One corner at a time, and cap or plug the open hard line to slow the drip.", "Everything gets bled afterwards, in VW's order."], "steps": [{"n": 1, "title": "Wheels off, find the hose", "blocks": [{"t": "text", "b": "Four stands, wheels off. At each corner: a rubber hose from a bracket on the body/strut (hard-line union, 11mm flare nut) to the caliper (banjo bolt or threaded fitting)."}]}, {"n": 2, "title": "Slow the flow", "blocks": [{"t": "text", "b": "Suck the reservoir down near MIN and put a plastic bag under the cap to seal it; the system will barely drip with a line open. Don't clamp the old rubber hose with pliers if you plan to keep it; you don't, so a hose clamp is fine."}]}, {"n": 3, "title": "Swap the line", "caution": true, "blocks": [{"t": "text", "b": "Flare-nut wrench on the hard-line union, back it off, pull the retaining clip and free the hose from the bracket. At the caliper, remove the banjo bolt (or unscrew the fitting). Fit the new line the same way round, new copper washers either side of the banjo, thread the hard-line union by hand first, then snug. Clip the line into the bracket."}, {"t": "warn", "b": "Route the new line exactly where the old one ran and turn the steering lock to lock (front) and bounce the suspension to confirm it can't touch the wheel, spring or strut at any angle. A stainless line rubbing a wheel wears through."}, {"t": "torque", "label": "Banjo bolt / hard-line union", "nm": 15, "alt": [35], "c": {"level": "single", "n": 1, "note": "No factory figure found this pass. Kit sheets range from 15 Nm (union) to 35 Nm (banjo). Snug, then check for weeping under pressure."}}]}, {"n": 4, "title": "Repeat at every corner", "blocks": [{"t": "text", "b": "Same at the other three. Keep the reservoir from running dry."}]}, {"n": 90, "title": "Set up the pressure bleeder", "blocks": [{"t": "text", "b": "Turkey-baster the old fluid out of the reservoir down to the minimum line and refill with fresh DOT 4 from a sealed bottle. Screw the bleeder cap onto the reservoir and pump it to 10–15 psi. Keep the reservoir topped the whole time; if it runs dry the ABS unit takes in air and only a scan tool can bleed it."}, {"t": "warn", "b": "Brake fluid strips paint in minutes. Cover the fender and wing, keep a spray bottle of water handy, and wipe drips immediately."}]}, {"n": 91, "title": "Bleed in the manual's order", "caution": true, "blocks": [{"t": "text", "b": "Manual car first: 11mm on the clutch slave bleeder (on the bell housing), let 50 ml run, close, pump the clutch pedal 10–15 times, open again for another 50 ml, close. Then the brakes: front-left, front-right, rear-left, rear-right. Yes, front first; the ABS unit's layout makes the usual furthest-first rule wrong on this car. At each caliper: dust cap off, 11mm wrench on the nipple, hose into a catch bottle, open until the fluid runs clear and bubble-free, close, cap."}, {"t": "ill", "id": "bleed-order", "cap": "The order VW specifies. Clutch slave first on a manual."}, {"t": "note", "b": "Finishing touch owners swear by: after the pressure bleed, have a helper do five firm pedal strokes per caliper (open the nipple with the pedal down, close before it comes up) to chase any last air."}]}, {"n": 92, "title": "Close up and test", "blocks": [{"t": "text", "b": "Release bleeder pressure, remove the cap, set the reservoir level between the marks (not above MAX; the pads will wear and the level will rise as they're changed). Pedal should be firm within the first inch. Drive gently around the block, brake progressively harder, and check every bleeder for weeping."}]}], "alsoReplace": [{"name": "Pads and rotors", "why": "Same wheels-off session; see those guides."}, {"name": "Clutch line (manual)", "why": "Stainless clutch line is the same idea for a firmer clutch pedal and lives on the same reservoir."}], "check": {"tab": "Rubber or steel?", "title": "Is it worth it on a street car?", "illId": "bleed-order", "illCap": "The gain is consistency, not stopping distance.", "rows": [{"see": "Stock pads, daily driving", "means": "You'll notice a slightly firmer pedal, mostly at first.", "do": "Do it when the rubber hoses need replacing anyway."}, {"see": "Performance pads, spirited driving", "means": "Pedal feel under heat is where stainless shows.", "do": "Yes, with a full flush and good fluid."}, {"see": "Track days", "means": "Consistency lap to lap.", "do": "Yes, with TYP200 or RBF600."}], "c": {"level": "community", "n": 3, "note": "Forum consensus."}}, "aftercare": ["Check every fitting for weeping after the first hard stops.", "Re-check routing after a week: nothing should show rub marks."], "disagreements": [{"topic": "Fitting torque", "pos": "No factory value found; kits vary.", "call": "Snug and leak-check. Flagged single-source."}, {"topic": "Worth it on a stock car?", "pos": "Forum split.", "call": "When the rubber hoses are due anyway, yes."}], "sources": ["Brake bleeding sources (see flush guide)", "StopTech / Goodridge / ECS product listings", "Forum threads on hose ageing and routing"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('dsg',$j${"id": "dsg", "title": "DSG fluid & filter service", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 6-speed DSG (02E / DQ250)", "heroId": "dsg-hero", "alsoFits": "Every 6-speed wet-clutch DSG (02E/0D9) 2005–2019: Golf, GTI, Jetta, Eos, Passat, A3, TT", "category": "Drivetrain", "kind": "repair", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$120–180", "risk": "Fluid level is set by temperature; get it wrong and the box shifts badly", "why": "The DSG's wet clutches and mechatronic unit live in this oil. It shears and fills with clutch material, and VW's 40,000-mile interval is not a suggestion: neglected fluid is behind most of the harsh-shift and mechatronic stories. This service is cheap and very doable at home.", "note": "An afternoon. The only fiddly part is setting the level at the right temperature."}, "heroCap": "Drain plug and overflow tube underneath; filter under a cap on top. The level is set by letting excess run out of the overflow tube with the engine running and the fluid at 35–45°C.", "lifespan": {"title": "When to expect it", "headline": ["Every 40,000 miles, per the factory schedule"], "earliest": "Sooner (30k) if tuned, towing, or tracked", "detail": "Owners who go long describe shudder on take-off, clunky low-speed shifts and hesitation in reverse. Fresh fluid often clears mild versions of these; it won't fix a worn mechatronic unit, but it's the first thing to do.", "factors": ["Tune (more torque through the clutches)", "Stop-and-go city driving", "Unknown history on a used car"], "inspect": ["Nothing to inspect between services; just do it on time"], "confidence": {"level": "high", "n": 4, "note": "Factory interval confirmed by three vendor sources; symptoms are forum consensus."}}, "should": {"yesIf": ["40,000 miles since the last service, or unknown", "Shudder on take-off, harsh or lazy low-speed shifts", "You just bought the car", "You've tuned it"], "codes": [], "notes": ["Fluid spec is VW TL 521 82 (G 052 182 A2). Nothing else. The dual clutches run in this oil and the friction spec matters.", "Filter part is 02E 305 051 C; the cap o-ring comes with a good kit."], "confidence": {"level": "high", "n": 4, "note": "Spec, capacity and interval agree across all sources."}}, "parts": [{"tier": "oe", "name": "DSG fluid, 6 × 1 L", "pn": "G 052 182 A2", "note": "Service fill is 5.2 L; buy six so the level-set doesn't run short", "price": "$90–120", "links": []}, {"tier": "oe", "name": "DSG filter with o-ring", "pn": "02E 305 051 C", "note": "", "price": "$30–45", "links": []}, {"tier": "oe", "name": "Drain plug crush washer", "pn": "in most kits", "note": "", "price": "$3", "links": []}], "aftermarket": [{"name": "Ravenol DCT/DSG, Eurol DCF 1404, Pentosin FFL-2", "note": "Third-party fluids that meet TL 521 82. Fine; the OE fluid is also made by a third party.", "price": "$15–20 / L", "signal": "Meets spec", "links": []}, {"name": "Blauparts / FCP Euro service kits", "note": "Fluid, filter, washer and the fill adapter in one box.", "price": "$130–180", "signal": "One-box pick", "links": [{"store": "FCP Euro DIY", "url": "https://www.fcpeuro.com/blog/vw/audi-dsg-automatic-transmission-service-diy"}]}], "tools": [{"name": "14mm hex bit (drain plug), 8mm hex bit (overflow tube), 24mm socket or filter socket (filter cap)"}, {"name": "DSG fill adapter (VAS 6262-style) with hose and pump, or a fluid transfer pump into the drain hole"}, {"name": "VCDS or a scan tool that reads transmission fluid temperature; an infrared thermometer as a fallback"}, {"name": "Drain pan ≥ 6 L, torque wrench to 45 Nm, ramps or four stands: the car must be level"}], "before": ["The car must be level for the level-set. Four stands or ramps at both ends.", "Fluid should be warm but not hot when you drain: a short drive, then let it sit 10 minutes.", "Read the level-set step twice before you start. It's the whole job."], "steps": [{"n": 1, "title": "Level, warm, belly pan off", "blocks": [{"t": "text", "b": "Car level on stands, belly pan off. Drain pan under the transmission's bottom plug."}]}, {"n": 2, "title": "Drain", "blocks": [{"t": "text", "b": "14mm hex: remove the drain plug. Fluid runs. When it slows, 8mm hex into the overflow tube inside the drain hole and unscrew it: another litre or so drops. Expect about 5 litres total; measure it roughly so you know what to put back."}, {"t": "ill", "id": "dsg-hero", "cap": "Plug, then the tube inside it. The tube's height is what sets the level later."}]}, {"n": 3, "title": "Filter", "blocks": [{"t": "text", "b": "Top of the transmission, under the airbox/battery area: the round filter cap. 24mm socket, unscrew, lift out the filter (fluid will follow; rag ready). New o-ring on the cap, new filter in, cap on."}, {"t": "torque", "label": "Filter cap", "nm": 20, "c": {"level": "medium", "n": 2, "note": "20 Nm (15 lb-ft) from two owner guides. Plastic cap: snug."}}]}, {"n": 4, "title": "Overflow tube back, fill", "blocks": [{"t": "text", "b": "Overflow tube back in (3 Nm, barely more than finger tight). Thread the fill adapter into the drain hole and pump in about 5 litres, shaking each bottle first. Leave the adapter on."}, {"t": "torque", "label": "Overflow tube (8mm hex)", "nm": 3, "c": {"level": "single", "n": 1, "note": "From the Mk5 FAQ procedure. Plastic; snug."}}]}, {"n": 5, "title": "Set the level", "caution": true, "blocks": [{"t": "text", "b": "Start the engine with the adapter connected and the pan underneath. Foot on the brake, move the lever through P–R–N–D–S, holding each about 3 seconds, back to P. Watch the fluid temperature on VCDS (Auto Trans, measuring block 19) or an IR gun on the pan. Between 35 and 45°C, open the adapter's valve (or remove the adapter and let the drain hole weep). Excess fluid runs out of the overflow tube: expect half a litre to three-quarters. When it slows to a drip, remove the adapter and fit the plug with a new washer."}, {"t": "warn", "b": "Do not let it go past 45°C with the plug out, and do not switch the engine off with the plug out. Hot fluid has expanded and the level will be set low; a stopped engine dumps the fluid held in the box. If more than a litre runs out, stop and reassess: something's wrong with the fill."}, {"t": "torque", "label": "Drain plug (14mm hex)", "nm": 45, "c": {"level": "high", "n": 3, "note": "45 Nm across FCP Euro, the Mk5 FAQ and Blauparts."}}]}, {"n": 6, "title": "Adaptation and test drive", "blocks": [{"t": "text", "b": "Engine off, belly pan on. Many owners run the DSG basic-settings adaptation in VCDS after a service; it's optional but helps if shifts were harsh. Drive it. Check around the filter cap and plug for leaks when you get back."}]}], "alsoReplace": [{"name": "Engine air filter", "why": "The airbox is in your way for the filter cap anyway."}, {"name": "Haldex/other fluids", "why": "Not on a GTI. On an R32 or Golf R the Haldex service shares the afternoon."}], "check": {"tab": "Read the fluid", "title": "What came out?", "illId": "dsg-hero", "illCap": "Fresh DSG fluid is pale amber and thin.", "rows": [{"see": "Amber, clean, smells like oil", "means": "On schedule.", "do": "Normal service."}, {"see": "Dark brown, opaque, burnt smell", "means": "Long overdue; clutch material in suspension.", "do": "Service now; consider a second change after 5–10k to dilute what's left."}, {"see": "Metal glitter or chunks on the magnet", "means": "Mechanical wear, not just old fluid.", "do": "Service, then a transmission specialist. Fluid won't fix this."}], "c": {"level": "community", "n": 3, "note": "Forum consensus."}}, "aftercare": ["Re-check the plug and filter cap for leaks after a day.", "Shifts may feel different for a few drives while the mechatronics adapt.", "Note the mileage; next in 40k."], "disagreements": [{"topic": "How to read the temperature", "pos": "VCDS measuring block vs an IR gun on the pan.", "call": "VCDS if you have it; the IR gun works on the pan and is what two vendor guides use."}, {"topic": "How much fluid", "pos": "5.2 L (spec) vs 5.5 L (FAQ fill).", "call": "Buy six litres; the overflow sets the level."}, {"topic": "Drain plug bit", "pos": "14mm hex (four sources) vs 14mm triple-square (one).", "call": "Hex."}], "sources": ["FCP Euro DSG service DIY (02E)", "Blauparts DSG articles (capacity, spec, interval)", "VWVortex 'DSG Fluid and Filter Technical Write-Up' / Mk5 FAQ", "Pelican Parts Mk5 GTI DSG article", "Golfmk7 DSG DIY and UroTuning guide (torques)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('clutch',$j${"id": "clutch", "title": "Clutch replacement", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI · 6-speed manual (02Q)", "heroId": "clutch-hero", "alsoFits": "Mk5/Mk6 GTI, Jetta, A3 with the 02Q 6-speed; TSI cars identical at the transmission", "category": "Drivetrain", "kind": "repair", "variants": {"question": "What's going back in?", "hint": "A factory-style kit keeps the dual-mass flywheel (quiet, softer pedal). A single-mass or stage kit is for tuned cars: lighter, more clamp, some chatter at idle.", "options": [{"id": "oe", "label": "OE-style (dual-mass flywheel)", "when": "Stock or Stage 1. Sachs, LuK. Replace the flywheel if it's worn."}, {"id": "stage", "label": "Aftermarket single-mass / stage kit", "when": "Stage 2+, K04. Southbend, Sachs Performance, Clutchmasters. Heavier pedal, idle chatter is normal."}]}, "glance": {"timeFirst": "10–16 hr (two days)", "timeRepeat": "6–8 hr", "difficulty": 5, "cost": "$600–1,500 parts", "risk": "Transmission on a jack · engine on a support bar · torque-to-yield bolts everywhere", "why": "The clutch is the one friction part in the drivetrain. When it slips, the pedal gets high, or the release bearing screams, the transmission has to come out to fix it. That's why this is the hardest job in the app, and why you replace everything you can reach while it's out.", "note": "One owner claims three hours. The manufacturer guide says plan two full days. Believe the manufacturer."}, "heroCap": "Flywheel bolts to the crank, clutch disc sandwiched between it and the pressure plate, release bearing and slave cylinder on the transmission nose. The whole gearbox has to come out to reach any of it.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Factory clutch: typically 100,000–150,000 miles on a stock car", "only": ["oe"]}, {"text": "Stock clutch on a Stage 2 tune: often 40,000–80,000 miles before it slips", "only": ["stage"]}], "earliest": "Much sooner with a tune and a heavy right foot, or a leaking rear main seal soaking the disc", "detail": "Symptoms in order: pedal engagement point creeping toward the top, slipping in high gears under boost, a whir or squeal with the pedal down (release bearing), then judder. The dual-mass flywheel usually fails around the same time on high-mileage cars: rattle at idle that goes away with the pedal down.", "factors": ["Stage 2+ tune", "Launches", "Rear main seal or input shaft seal leak", "City driving"], "inspect": ["Nothing to inspect from outside; watch the engagement point"], "confidence": {"level": "community", "n": 5, "note": "Owner reports across several forums; no factory interval."}}, "should": {"yesIf": ["Slipping: revs climb without speed, especially 4th–6th under boost", "Engagement point at the very top of the pedal travel", "Squeal or whir with the pedal pressed", "Rattle at idle that stops with the clutch in (dual-mass flywheel)", "You're going Stage 2 and the clutch is original"], "codes": [], "notes": ["Hydraulics first: a soft or sinking pedal is often the slave or master cylinder, not the clutch. Bleed it and rule that out before you pull a transmission.", {"text": "Single-mass flywheels chatter at idle and in neutral. It's the sound of gear lash without the dual-mass damper. Owners who don't know this take their cars back to the shop. It's normal.", "only": ["stage"]}, {"text": "If the dual-mass flywheel rocks more than a few millimetres by hand or has any radial play, it's done. Reusing a tired one under a new clutch is the classic false economy.", "only": ["oe"]}, "TSI cars (2008.5–2009): same 02Q transmission and identical procedure. The flywheel and clutch part numbers differ from the FSI, so buy by engine code; the ECS guide this follows was in fact photographed on a TSI."], "confidence": {"level": "high", "n": 4, "note": "Symptoms and procedure consistent across the manufacturer guide and three owner DIYs."}}, "parts": [{"tier": "oe", "name": "Clutch kit: disc, pressure plate, release bearing/slave", "pn": "Sachs or LuK for the 02Q", "note": "", "price": "$300–450", "links": [], "only": ["oe"]}, {"tier": "oe", "name": "Dual-mass flywheel", "pn": "LuK", "note": "If the old one has play or heat spots", "price": "$400–600", "links": [], "only": ["oe"]}, {"tier": "aftermarket", "name": "Stage clutch kit with single-mass flywheel", "pn": "see options below", "note": "Includes flywheel bolts, pressure plate bolts, alignment tool, slave", "price": "$900–1,500", "links": [], "only": ["stage"]}, {"tier": "oe", "name": "Flywheel bolts (×8) and pressure plate bolts (×6)", "pn": "torque-to-yield", "note": "New, always. Most kits include them", "price": "$25", "links": []}, {"tier": "oe", "name": "Concentric slave cylinder / release bearing", "pn": "02Q 141 671", "note": "Never reuse. In most kits", "price": "$60–90", "links": []}, {"tier": "oe", "name": "Rear main seal", "pn": "06D 103 171", "note": "Now or never", "price": "$25", "links": []}, {"tier": "oe", "name": "Transmission input shaft seal, axle flange seals", "pn": "—", "note": "Cheap, and you're there", "price": "$30", "links": []}, {"tier": "oe", "name": "DOT 4 fluid for the clutch bleed", "pn": "—", "note": "", "price": "$10", "links": []}], "aftermarket": [{"name": "Southbend Stage 2 Daily / Stage 3", "note": "The forum default for tuned FSIs. Stage 2 Daily holds Stage 2 power with a near-stock pedal; Stage 3 for K04 and up, heavier pedal.", "price": "$1,000–1,400", "signal": "Forum favorite", "links": []}, {"name": "Sachs Performance", "note": "OE maker's uprated kit; organic disc, more clamp, pairs with the stock dual-mass or their SMF.", "price": "$700–1,000", "signal": "Quiet upgrade", "links": []}, {"name": "Clutchmasters FX series", "note": "Wide range of disc materials; check the pedal effort rating before buying anything above FX300 for a daily.", "price": "$800–1,300", "signal": "Pick by pedal weight", "links": []}, {"name": "ECS lightweight flywheel kit", "note": "Chromoly SMF with clutch, slave and hardware. The install PDF is the reference for this guide.", "price": "$900–1,100", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_13689_Volkswagen_MKV_MKVI_TSI_Lightweight_Flywheel_Installation_R3.pdf"}]}], "tools": [{"name": "Engine support bar and a transmission jack. Not optional."}, {"name": "Sockets 10, 13, 16, 18, 22, 24mm (12-point) · M10 and M12 triple-square · 9mm 12-point for pressure-plate bolts (kit-dependent) · 6mm hex"}, {"name": "Torque wrenches: ¼\" for 12 Nm, ½\" for 80–200 Nm; angle gauge or paint pen for the +90° bolts"}, {"name": "Clutch alignment tool (in kit), flywheel lock or two old bolts and a pry bar, brake-fluid catch bottle, connector release tool"}, {"name": "A printed bolt template taped to a box: the bell-housing bolts are all different lengths"}], "before": ["Read the manufacturer PDF end to end first. This guide is the map; the PDF has the photos.", "Two days, a helper for the transmission, and a clean floor to lay parts out in order.", "Every bolt with a '+90°' is torque-to-yield and is replaced.", "Disconnect the battery negative first. It's coming out anyway.", "Bench-bleed the new slave in a jug of fluid before it goes on the transmission."], "steps": [{"n": 1, "title": "Top side: airbox, battery, tray", "blocks": [{"t": "text", "b": "Engine cover/airbox out (see the air filter guide), scoop off (T25). Battery cover, negative then positive terminals (10mm), hold-down (13mm), battery out, both halves of the box, then the three 10mm tray bolts and the tray. You now see the top of the transmission."}]}, {"n": 2, "title": "Shifter cables, clutch line, electrics", "blocks": [{"t": "text", "b": "Unclip both shift cable ends from the selector and relay levers (retaining clip, then a gentle pry) and unbolt the cable bracket (two 13mm bolts and a nut); wire it up out of the way. Pull the clips and pop the clutch line out of the bleeder block into a catch bottle, then the block off the slave inlet. Ground strap off the mount bracket (13mm). Unplug the reverse switch and the starter solenoid, starter cable nut (13mm) off."}, {"t": "warn", "b": "Brake fluid from the clutch line goes everywhere. Catch it, and don't pinch the plastic hard line."}]}, {"n": 3, "title": "Upper bolts and the driver's axle", "blocks": [{"t": "text", "b": "Upper starter bolt and both upper bell-housing bolts (18mm). Left front wheel off; six inner CV bolts (M10 triple-square) with a helper holding the brake; outer CV bolt (24mm 12-point) with the wheel off the ground. Fender liner and the cooling duct out. Lower starter bolt, harness bracket, starter out."}]}, {"n": 4, "title": "Underneath: charge pipes, shields, right axle, pendulum", "blocks": [{"t": "text", "b": "Belly pan off. Driver's-side charge hose off (clamp and clip), MAP sensor unplugged, charge duct's two T30 screws out and the duct wiggled out between engine and fans; passenger charge hose off. Right CV heat shield (two 17mm). Six right inner CV bolts, tie the shaft up. Three left ball-joint nuts (16mm), pull the arm down, and the left axle comes out. Two downpipe-bracket bolts (13mm)."}]}, {"n": 5, "title": "Support the engine, drop the mounts", "caution": true, "blocks": [{"t": "text", "b": "Engine support bar across the fenders, hook on the head's lift bracket, tension until the engine just lifts. Three pendulum bolts (16/22mm), slide the mount out. Oil level sensor unplugged if fitted. Three transmission mount bolts (18mm). Lower the engine about two inches on the bar and remove the three bracket bolts and the bracket. Relay lever off (clip, slide out); selector shaft nut (13mm) and lever off, gently, no hammering."}, {"t": "warn", "b": "From here the engine hangs on the bar and the transmission on its last bolts. Check the bar's feet and chain before every step. Nobody under the transmission."}]}, {"n": 6, "title": "Transmission out", "caution": true, "blocks": [{"t": "text", "b": "Rear bell-housing bolt (18mm). Transmission jack under the box, strapped. Front bolt and the two lower bolts (16mm). With your helper: pull it back off the block, rotate the diff end up, angle the nose forward and walk the right CV flange around the flywheel, adjusting the engine bar and jack for clearance. Once clear, lower it and move it to the bench."}, {"t": "ill", "id": "clutch-hero", "cap": "What you're looking at once it's out: flywheel and pressure plate on the engine, release bearing/slave on the transmission nose."}, {"t": "note", "b": "Owner alternative: unbolt the inner CV flanges from the transmission (6mm hex) instead of pulling the whole left axle, and pull the front intercooler pipe for more room. Same result."}]}, {"n": 7, "title": "Old clutch and flywheel off", "blocks": [{"t": "text", "b": "Loosen all six pressure-plate bolts, then remove them alternately with a hand on the plate; it comes off its three dowels with the disc, sometimes with a pry. Eight flywheel bolts (M12 triple-square): impact, or two old plate bolts and a pry bar to lock it. Firm grip on the last bolt; the dual-mass is heavy."}]}, {"n": 8, "title": "Clean up and the seal you came for", "blocks": [{"t": "text", "b": "Clean the crank flange, block face and separator plate. Look at the rear main seal: any wetness, replace it now (pry out, tap the new one square). Both alignment dowels in the block; the separator plate hooked behind the seal plate and resting on the dowels."}]}, {"n": 9, "title": "Flywheel and clutch on", "caution": true, "blocks": [{"t": "text", "b": "Flywheel onto the crank (offset holes, one position). New bolts, pre-coated with locker. Torque in the star sequence in three stages, marking each bolt with paint after the angle stage.", "only": ["oe", "stage"]}, {"t": "torque", "label": "Flywheel bolts (×8, NEW)", "nm": 60, "c": {"level": "high", "n": 3, "note": "Stage 1: 30 Nm, stage 2: 60 Nm, stage 3: +90°. Manufacturer PDF; owner DIYs consistent."}, "note": "30 → 60 → +90°"}, {"t": "text", "b": "Wipe the flywheel face and the new pressure plate with brake cleaner. Test the disc on the transmission's input-shaft splines first. Disc against the flywheel, 'transmission side' facing you, alignment tool through it into the crank. Pressure plate over the dowels, six new bolts evenly and alternately."}, {"t": "torque", "label": "Pressure plate bolts (×6, NEW)", "nm": 20, "alt": [22], "c": {"level": "varies", "n": 2, "note": "20 Nm for the aftermarket SMF kit's 9mm 12-point bolts; 22 Nm for the factory dual-mass plate bolts. Follow your kit's sheet."}}, {"t": "warn", "b": "No grease, no fingerprints on the friction faces. One oily thumbprint on the disc is a juddering clutch for its whole life."}]}, {"n": 10, "title": "Slave, splines, and back in", "caution": true, "blocks": [{"t": "text", "b": "Three 9mm bolts and the old slave/release bearing comes off the bell housing. Clean the housing and splines; check the input shaft seal. New (bench-bled) slave on with new bolts (12 Nm metal / 15 Nm plastic). Thin, even film of the kit's spline lube on the input shaft. Transmission back on the jack, up, and walked home against the block until it seats flat. Start the two lower bolts, front, rear, then the uppers, none tight, and check nothing's pinched."}, {"t": "note", "b": "Reconnect the clutch line before the box is pushed fully home: the pressure-plate fingers push the slave and it will spray fluid otherwise."}, {"t": "torque", "label": "Bell-housing bolts, upper M12 and rear M12", "nm": 80, "c": {"level": "high", "n": 3, "note": "80 Nm (manufacturer, owner DIYs)"}}, {"t": "torque", "label": "Bell-housing bolts, lower M10 and front M10", "nm": 40, "alt": [45], "c": {"level": "varies", "n": 2, "note": "40 Nm (manufacturer) vs 45 Nm (owner DIY). Either is fine; the base sizes match."}}]}, {"n": 11, "title": "Mounts, pendulum, axles, starter", "blocks": [{"t": "text", "b": "Selector lever and nut (20 Nm), relay lever and clip. Bracket back (60 Nm + 90°, new bolts), raise the transmission, three mount bolts (60 Nm + 90°, new). Pendulum in: transmission bolts 50 Nm + 90°, subframe bolt 100 Nm + 90°. Engine bar off. Downpipe bracket. Left axle in, ball joint nuts (60 Nm cast arm / 100 Nm aluminium). Inner CV bolts both sides (70 Nm for M10). Starter (80 Nm), cable, solenoid, reverse switch, ground. Charge pipes and MAP. Shields, liner, wheel (120 Nm), outer CV bolt per its type."}, {"t": "torque", "label": "Transmission mount & bracket bolts (NEW)", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm + 90° (manufacturer; owner DIY: 50 Nm + 90° on the older 02M)."}, "note": "+90° turn"}]}, {"n": 12, "title": "Cables, bleed, battery, test", "blocks": [{"t": "text", "b": "Bleeder block and clutch line, shifter cable bracket and cables. Battery tray, battery. Bleed the clutch: pressure bleeder on the reservoir, 11mm on the slave nipple, run fluid until clear, pump the pedal, repeat. Airbox on. Start it in neutral, clutch in, feel for a normal pedal. First drive: gentle, all gears, listen."}]}, {"n": 13, "title": "Break it in", "blocks": [{"t": "text", "b": "New friction surfaces need heat cycles. 500 miles of normal driving, no launches, no boost in low gears with the pedal slipping, before you lean on it.", "only": ["oe"]}, {"t": "text", "b": "Stage kits are stricter: most makers want 500–1,000 miles of city driving, no hard launches, no boosted slip, or the disc glazes and the warranty is void. The idle chatter you hear is the single-mass flywheel. It's normal.", "only": ["stage"]}]}], "alsoReplace": [{"name": "Rear main seal", "why": "It's staring at you with the flywheel off. If it leaks later, the whole job repeats."}, {"name": "Concentric slave cylinder / release bearing", "why": "Never reuse it. Most kits include one; if yours didn't, buy one."}, {"name": "Transmission input shaft seal and axle flange seals", "why": "Cheap, accessible with the box out, and a leaking flange seal drips onto the new clutch's neighbourhood."}, {"name": "Pendulum (dogbone) mount and transmission mount", "why": "Both are unbolted. Tired mounts are the usual source of driveline clunk, and stage clutches punish soft mounts."}, {"name": "Clutch bleeder block and line", "why": "The factory plastic block restricts flow; a high-flow block improves pedal feel and is $40 while you're bleeding anyway."}, {"name": "Starter", "why": "It's in your hand. On a 150k car, check the pinion and the solenoid contacts; a new starter is a lot cheaper than pulling the box again for one."}], "check": {"tab": "OE or stage?", "title": "Which clutch belongs in your car?", "illId": "clutch-hero", "illCap": "Dual-mass damps the driveline; single-mass revs faster and chatters.", "rows": [{"see": "Stock or Stage 1, daily driver", "means": "The factory setup is quiet, light and lasts.", "do": "OE-style kit; new dual-mass if the old one has play."}, {"see": "Stage 2 / K04, daily driver", "means": "Stock clutch will slip; you want clamp without a leg workout.", "do": "Southbend Stage 2 Daily or Sachs Performance with the stock-style flywheel."}, {"see": "Big turbo or track", "means": "Holding power first.", "do": "Stage 3+ with single-mass. Accept the pedal and the chatter."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; vendor tiers."}}, "aftercare": ["Break in as above.", "Re-torque nothing; the TTY bolts are done. Do re-check the pendulum and mount bolts didn't get missed.", "Clutch pedal soft after a week: air in the line; bleed again."], "disagreements": [{"topic": "How long?", "pos": "'About 3 hours' (one owner) vs 'plan two full days' (manufacturer).", "call": "Two days for a first time. The owner had done it before and skipped nothing."}, {"topic": "Pressure plate torque", "pos": "20 Nm (SMF kit) vs 22 Nm (OE dual-mass).", "call": "Follow the kit's sheet; both shown."}, {"topic": "Pull the axle or just the flanges?", "pos": "Manufacturer pulls the left axle; an owner unbolts both inner flanges instead.", "call": "Either works. Flanges is quicker; axle gives more room."}, {"topic": "Is the idle chatter a fault?", "pos": "New SMF owners think so.", "call": "No. It's the design."}], "sources": ["ECS Tuning Mk5/Mk6 02Q lightweight flywheel & clutch installation PDF (57 pages)", "VWVortex 'Transmission Removal Clutch Replacement diy Quick Version' (2008)", "Golfmk6 '6 Speed Manual Clutch Replacement DIY' (2014)", "Pelican Parts Mk4 clutch article (technique)", "NGP, Southbend, Sachs listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('coilovers',$j${"id": "coilovers", "title": "Coilover install", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "coilover-hero", "alsoFits": "Mk5/Mk6 Golf, GTI, Jetta, Eos · A3 8P (same PQ35 strut and multilink rear)", "category": "Suspension", "kind": "upgrade", "variants": {"question": "Does your kit include its own top mounts?", "hint": "Most European kits (KW, Bilstein, H&R, ST, Koni) reuse the factory strut mounts and bearings, so the old struts have to come apart. Kits with their own mounts or camber plates (BC Racing, some ECS kits) bolt straight in.", "options": [{"id": "reuse", "label": "Reuses factory mounts", "when": "KW, Bilstein, H&R, ST, Koni. Spring compressor needed, or buy new mounts."}, {"id": "own", "label": "Includes top mounts / camber plates", "when": "BC Racing, ECS kits with HD mounts. Stock struts stay assembled."}]}, "glance": {"timeFirst": "6–8 hr (a full day)", "timeRepeat": "4 hr", "difficulty": 3.5, "cost": "$900–2,500 + alignment", "risk": "Compressed springs · seized pinch bolts · axle bolt at 200 Nm · alignment required", "why": "Coilovers replace the springs and dampers at all four corners with adjustable ones: you set the ride height, and on adjustable kits the damping. It's the biggest single change you can make to how the car drives, and the most involved bolt-on in this app after the clutch.", "note": "ECS rates it moderate; owners say a full day, two if a pinch bolt is seized. The alignment afterwards is not optional."}, "heroCap": "Front: strut clamped in the wheel-bearing housing by one pinch bolt, hung from three bolts under the cowl. Rear: separate spring in the control arm and a shock on two upper bolts and one big lower bolt.", "lifespan": {"title": "When owners do this", "headline": ["Usually after sway bars and tires, or when the original dampers are done around 100,000 miles"], "earliest": null, "detail": "Original dampers on a 2006 car are tired by now; a bouncy ride, nose-dive under braking and inner-edge tire wear are the signs. Owners choosing between new factory-style dampers and coilovers usually go coilover because the price gap has closed and the springs come with it.", "factors": ["Worn original dampers", "Sway bars already fitted", "Want the stance"], "inspect": ["Bounce test each corner: more than one rebound means the damper is gone"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus; no factory interval for dampers."}}, "should": {"yesIf": ["Original dampers are worn", "You want adjustable ride height and, on some kits, damping", "Sway bars are done and you want the next step", "You have a full day, a helper for the front struts, and an alignment booked"], "codes": [], "notes": ["Buy the installation kit, or its parts: new strut mounts and bearings, pinch bolts and nuts, axle bolts, rear shock mounts and bolts. Half of these are torque-to-yield and all of them are twenty years old. The kit also saves you a spring compressor if your coilovers reuse factory mounts.", "Lower it sensibly. Below about 1.5 inches of drop on a PQ35 car the geometry goes off, inner tires wear fast, and you'll want camber correction and adjustable end links. Set height for how you drive, not for the photo.", {"text": "Reusing the factory mounts means compressing the old springs to get the mounts off. A spring compressor is the most dangerous tool in a home garage. Rent a good one, use both claws, and never put any part of you in line with the spring.", "only": ["reuse"]}], "confidence": {"level": "high", "n": 4, "note": "Procedure agrees across the manufacturer guide and owner DIYs; the parts-replacement advice is universal."}}, "parts": [{"tier": "aftermarket", "name": "Coilover kit (4 corners)", "pn": "see options below", "note": "", "price": "$900–2,500", "links": []}, {"tier": "oe", "name": "Front strut mounts (×2) and bearings (×2)", "pn": "1K0 412 331 B · 6N0 412 249 C", "note": "Old ones are worn and you're compressing springs to reuse them", "price": "$60–120", "links": [], "only": ["reuse"]}, {"tier": "oe", "name": "Front pinch bolts and nuts (×2)", "pn": "M14, torque-to-yield", "note": "Replace", "price": "$15", "links": []}, {"tier": "oe", "name": "Outer axle bolts (×2)", "pn": "24mm 12-point, torque-to-yield", "note": "Replace", "price": "$20", "links": []}, {"tier": "oe", "name": "Rear shock mounts (×2) and upper bolts", "pn": "1K0 513 353 G", "note": "Cheap; replace", "price": "$40", "links": []}, {"tier": "oe", "name": "Alignment", "pn": "—", "note": "Book it for the day after", "price": "$100–150", "links": []}], "aftermarket": [{"name": "KW V1 / V2 / V3", "note": "Stainless bodies, reuse factory mounts. V1 fixed damping, V2 rebound-adjustable, V3 rebound and compression. The reference kit; priced like it.", "price": "$1,400–2,500", "signal": "Reference kit", "links": []}, {"name": "Bilstein B14 (PSS) / B16 (PSS10)", "note": "B14 fixed damping, B16 ten-click adjustable. Reuse factory mounts. Firm, controlled, long-lived.", "price": "$1,200–2,200", "signal": "Daily-and-track pick", "links": []}, {"name": "ST X / XA / XTA", "note": "KW's value brand, same threads and install. XA adds damping, XTA adds camber plates (so it needs no factory mounts).", "price": "$900–1,700", "signal": "Value pick", "links": []}, {"name": "H&R Street Performance", "note": "Reuse factory mounts; comfortable side of the range; H&R's spring rates.", "price": "$1,100–1,500", "signal": "Comfort pick", "links": []}, {"name": "BC Racing BR", "note": "Includes camber plates and top mounts, 30-way damping, rear separate spring perch. No spring compressor needed. Softer bodies; the price shows.", "price": "$1,000–1,300", "signal": "Own mounts included", "links": []}, {"name": "ECS Tuning adjustable kit", "note": "Budget kit; the ECS install PDF this guide follows was written around a similar design. Pair with their install kit.", "price": "$700–900", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_6302_Volkswagen_MK5-6_Coilover_Installation_Instructions.pdf"}]}], "tools": [{"name": "Jack, four stands, a second jack for the control arms; wheel hanger helps"}, {"name": "M14 triple-square (pinch bolt) and M6 triple-square (end links); 24mm 12-point socket and a breaker bar or impact (axle bolt)"}, {"name": "Spindle housing spreader tool", "note": "The strut will not come out of the housing without it; rent or buy (ECS ES#3894)"}, {"name": "Strut nut sockets (21/22mm pass-through) and a 7mm hex to hold the rod; 19mm offset wrench for the rear"}, {"name": "Spring compressor (rent a good one)", "only": ["reuse"]}, {"name": "Sockets 10, 13, 16, 18, 21mm; torque wrench to 200 Nm; angle gauge or paint pen; penetrating oil; tape measure"}], "before": ["Measure fender-to-ground at all four corners on level ground and write it down. It's your only reference for setting height.", "Soak the pinch bolts, axle bolts and end-link nuts the night before.", "Loosen the axle bolts with the wheels on the ground or a helper on the brakes, never with the wheel off the ground and the bearing taking the load.", "Do fronts first (harder), then rears. Both sides of an axle before you move on."], "steps": [{"n": 1, "title": "Measure, raise, wheels off", "blocks": [{"t": "text", "b": "Fender heights recorded. Loosen the two axle bolts (24mm 12-point) with the car on the ground. Raise it on four stands, all wheels off."}]}, {"n": 2, "title": "Front: disconnect around the strut", "blocks": [{"t": "text", "b": "End-link nut at the strut (18mm, M6 triple-square holding the stud). Brake hose and ABS wire bracket bolt (10mm) off the bearing housing; don't stretch the hose. Axle bolt fully out. Driver's side: level-sensor arm bracket off the control arm (10mm). Three ball-joint nuts (16mm), pry the control arm down off the joint, pull the bearing housing outward so the CV joint comes out of the hub, and wire the shaft up. Reconnect the ball joint loosely so the arm is controlled."}, {"t": "ill", "id": "coilover-hero", "cap": "Front strut: one pinch bolt below, three bolts above. The housing has to be spread to release it."}]}, {"n": 3, "title": "Front: pinch bolt and spreader", "caution": true, "blocks": [{"t": "text", "b": "Jack under the control arm. Pinch bolt out: M14 triple-square one side, 18mm the other. Spreader tool into the slot at the back of the bearing housing, rotate it to open the gap, then lower the jack and tap the housing down off the strut with a hammer until it's free."}, {"t": "warn", "b": "A seized pinch bolt is where the day goes. Heat, oil and patience; if the triple-square rounds, you're drilling. Never hammer the housing without the spreader in; the aluminium cracks."}]}, {"n": 4, "title": "Front: strut out from the top", "blocks": [{"t": "text", "b": "Peel back the cowl seal at the strut tower to reach the three 13mm top bolts. One hand on the strut, remove all three, and lower it out of the car."}]}, {"n": 5, "title": "Front: strip the old mounts", "only": ["reuse"], "caution": true, "blocks": [{"t": "text", "b": "Old strut in a vise. Spring compressor on, both claws, compressed until the spring lifts off the upper seat. Hold the rod with a 7mm hex, remove the top nut with a 21mm strut socket, lift the mount and bearing off. Release the compressor slowly. Inspect: if the bearing is notchy or the mount's rubber is cracked, use new ones instead."}, {"t": "warn", "b": "A compressed coil spring stores enough energy to kill. Claws seated, hooks facing each other, never over the ends of the spring. Do this on the bench, never in the car."}]}, {"n": 6, "title": "Front: build the coilover", "blocks": [{"t": "text", "b": "Light grease on the threads. Perch and lock ring threaded to the bottom. Spring on, kit's upper spacer, then the mount and bearing (new, or the factory ones you just freed). Arrows or marks on the mount point fore and aft. New top nut, rod held with a 7mm hex.", "only": ["reuse"]}, {"t": "text", "b": "Light grease on the threads. Perch and lock ring to the bottom, spring on, then the kit's top mount or camber plate per its sheet: camber plates have a marked orientation and an adjustment slot that should start centred. New top nut, rod held with a hex.", "only": ["own"]}, {"t": "torque", "label": "Front strut top nut", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm from the manufacturer guide and the Koni owner DIY. Kit-supplied nuts may differ; check."}}, {"t": "text", "b": "Wind the perch up until the spring just touches both seats. Height comes later."}]}, {"n": 7, "title": "Front: into the car", "blocks": [{"t": "text", "b": "Up into the tower, mount arrows fore/aft, three new top bolts started. Spreader back in the housing, jack the control arm up and guide the strut's foot fully into the housing until it bottoms on the stop, then a new pinch bolt and nut."}, {"t": "torque", "label": "Upper strut mount bolts (×3)", "nm": 15, "c": {"level": "high", "n": 2, "note": "15 Nm + 90°, new bolts (manufacturer; forum tables agree)."}, "note": "+90° turn"}, {"t": "torque", "label": "Pinch bolt (M14)", "nm": 70, "c": {"level": "high", "n": 2, "note": "70 Nm + 90°, new bolt and nut (manufacturer, forum). The Mk7 figure of 70 + 180° is a different car."}, "note": "+90° turn"}, {"t": "text", "b": "Ball joint back on (60 Nm cast arm, 100 Nm aluminium), CV into the hub, new axle bolt started, level sensor, brake bracket, end link (65 Nm). Other side. Wheels on at 120 Nm; final axle-bolt torque with the car on the ground."}, {"t": "torque", "label": "Outer axle bolt (NEW)", "nm": 200, "alt": [70], "c": {"level": "varies", "n": 2, "note": "Depends on the bolt: hex head or smooth 12-point is 200 Nm + 180°; a ribbed 12-point is 70 Nm + 90°. The owner DIY's '180 or 200' confusion is this. Look at the underside of the bolt head."}, "note": "+180° / +90°"}]}, {"n": 8, "title": "Rear: shock and spring out", "blocks": [{"t": "text", "b": "Driver's side: level-sensor arm nut (10mm). Lower shock bolt (21mm). Two upper shock bolts (13mm on a long extension) and the shock comes down. Jack under the control arm; counter-hold and remove the outer control-arm bolt (18mm both sides), then lower the jack and lift the spring out of its cushion."}]}, {"n": 9, "title": "Rear: build and fit", "blocks": [{"t": "text", "b": "New rear shock: mount (new, or the old one freed with a 16mm and a hex on the rod) onto the rod, upper nut to 25 Nm with a 19mm offset wrench. Rear spring: kit's perch into the top of the spring with the collar wound up (or, on kits with a lower perch, pry the factory lower cushion out of the arm and fit the kit's perch and collar there). Spring into the arm, end coil against its stop, aligned with the body's centring pin."}, {"t": "torque", "label": "Rear shock upper mount bolts (×2)", "nm": 50, "c": {"level": "high", "n": 2, "note": "50 Nm + 45° (manufacturer)."}, "note": "+45° turn"}, {"t": "text", "b": "Shock up and its two upper bolts torqued. Jack the arm until the outer arm bolt slides in; nut on loose. Lower shock bolt in, not torqued."}]}, {"n": 10, "title": "Rear torques at ride height", "caution": true, "blocks": [{"t": "text", "b": "The lower shock bolt and the outer control-arm bolt clamp rubber bushings; torqued in the air they'd be wound up at the wrong angle. Wheels on (120 Nm), lower the car onto its wheels (or onto ramps), then torque both."}, {"t": "torque", "label": "Rear shock lower bolt", "nm": 180, "c": {"level": "high", "n": 2, "note": "180 Nm at ride height (manufacturer). Not the Mk7's 70 + 180°."}}, {"t": "torque", "label": "Rear outer control-arm bolt", "nm": 90, "c": {"level": "high", "n": 2, "note": "90 Nm + 90° at ride height, new bolt."}, "note": "+90° turn"}, {"t": "warn", "b": "On stands, these bolts are just snug. Torque only with the weight on the wheels. Forgetting this is how bushings tear in a month."}]}, {"n": 11, "title": "Set ride height", "blocks": [{"t": "text", "b": "Lift the car so the springs are unloaded (weight off), wind the perches to your target using the measurements from step 1 (a sensible street drop is 1 to 1.5 inches), lower, roll it a few feet, re-measure, repeat. Left and right within a few millimetres. Tighten the front lock rings against the perches. Turn the wheel lock to lock and bounce each corner: nothing touches."}]}, {"n": 12, "title": "Alignment, then re-check", "blocks": [{"t": "text", "b": "Alignment next day, after the springs have settled. Re-measure height after a week; kits settle a few millimetres. Re-check the pinch bolts and end links at 100 miles. Set damping (if adjustable) from the maker's baseline and change one click at a time."}]}], "alsoReplace": [{"name": "Strut mounts and bearings", "why": "They're off the strut (or in the way of it). Notchy steering return and clunks over bumps come from these.", "only": ["reuse"]}, {"name": "Adjustable sway-bar end links", "why": "Lowering shortens the link geometry; adjustable links let the bars sit unloaded at the new height."}, {"name": "Rear shock mounts", "why": "Cheap rubber on a 20-year-old car; they're in your hand."}, {"name": "Camber correction (front camber bolts or plates; rear camber/toe kit)", "why": "Below about 1.5 inches of drop the factory adjustment range runs out and the alignment shop will tell you so."}, {"name": "Front control-arm bushings and dogbone mount", "why": "You've pulled the ball joints; a look at the arm bushings costs nothing, and a worn dogbone shows up more with stiffer suspension."}], "check": {"tab": "How low?", "title": "How low, and how stiff?", "illId": "coilover-hero", "illCap": "Height and damping are separate decisions.", "rows": [{"see": "Daily driver, rough roads", "means": "You want control, not slam.", "do": "1 inch drop, damping at or near the maker's baseline. Bilstein B14, H&R, ST X."}, {"see": "Spirited street, occasional track", "means": "Adjustable damping earns its keep.", "do": "1–1.5 inch, adjustable kit (KW V2/V3, B16, ST XA), adjustable end links, alignment with a little extra negative camber."}, {"see": "Show car", "means": "Looks first.", "do": "Go low, but budget for camber correction, adjustable links and tire wear, and expect the ride to suffer."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; the geometry point is standard suspension practice."}}, "aftercare": ["Alignment after settling.", "Re-torque pinch bolts and end links at 100 miles; re-measure height at a week.", "Grease the threads and lock rings once a year in the salt belt or they seize."], "disagreements": [{"topic": "How hard?", "pos": "Manufacturer: 'Moderate, a couple of hours'. Owners: a full day, more if the pinch bolt fights.", "call": "3.5 out of 5 and a full day."}, {"topic": "Axle bolt torque", "pos": "'180 or 200 Nm depending on which page of Bentley' (owner). Manufacturer table gives three values by bolt type.", "call": "By bolt type. Check the head."}, {"topic": "Brand-specific steps?", "pos": "Brands differ in details.", "call": "The manufacturer guide is explicitly cross-brand and the procedure matches the owner DIYs. The real fork is whether your kit brings its own top mounts, which is the question the guide asks."}], "sources": ["ECS Tuning Mk5/Mk6 coilover installation PDF (2018, cross-brand)", "VWVortex Koni coilover install DIY (part numbers, tools)", "Golfmk7 spring/damper reference (excluded values noted)", "Brand listings: KW, Bilstein, ST, H&R, BC Racing, ECS"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('short-shifter',$j${"id": "short-shifter", "title": "Short shifter install", "fits": "2006 VW GTI · 6-speed manual (02Q)", "heroId": "shifter-hero", "alsoFits": "Any 02M/02Q/MQ350 6-speed: Mk5–Mk7 GTI/Golf/Jetta/R, A3, TT", "category": "Drivetrain", "kind": "upgrade", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$250–350", "risk": "Adjustment is everything; a badly adjusted shifter grinds gears", "why": "The factory shifter has a long throw and rubber-isolated cable ends that add slop. A short-shift kit swaps the lever on top of the transmission for a shorter one and the cable ends for solid ones, so each shift is shorter and more direct. It's the mod you feel every single time you drive.", "note": "Owners who'd never touched a transmission report two hours with the PDF printed out. Adjustment is where the time goes."}, "heroCap": "Two cables from the cabin shifter to two levers on top of the transmission. The kit replaces the front-to-back lever (shorter arm = shorter throw) and the cable ends. Adjustment locks the transmission in neutral and pins the cabin shifter, then sets the cables between them.", "lifespan": {"title": "When owners do this", "headline": ["Often the first interior mod; any time"], "earliest": null, "detail": "Nothing wears out to force it. Worn shifter bushings in the cabin base do make the stock shifter sloppy by 100k, and Dieselgeek says to replace those first or the new shifter can't be adjusted properly.", "factors": ["Sloppy or vague stock shifter", "You want shorter throws", "Doing a clutch (cables are off anyway)"], "inspect": ["Wiggle the shift knob side to side in neutral: excessive play is the bushings, not the cables"], "confidence": {"level": "community", "n": 3, "note": "Vendor guidance and owner reports."}}, "should": {"yesIf": ["Long, vague throws bother you", "Shifter has side-to-side slop in neutral", "You're pulling the airbox anyway for another job"], "codes": [], "notes": ["Set expectations: a short shifter is shorter and more direct, and also a bit notchier with a heavier throw. Dieselgeek says so on their own product page. If you want buttery, this isn't it.", "Check the cabin shifter bushings before you buy. If the knob has a lot of side-to-side play in neutral, the base bushings are worn and the kit won't adjust right until they're replaced (Dieselgeek sells them; ten-minute job under the console trim)."], "confidence": {"level": "high", "n": 3, "note": "Consistent across the vendor and two owner DIYs."}}, "parts": [{"tier": "aftermarket", "name": "Short shift kit", "pn": "see options below", "note": "Lever, cable ends, hardware, locking pin", "price": "$250–350", "links": []}, {"tier": "aftermarket", "name": "Shifter base bushings + aluminium side-to-side cable end", "pn": "Dieselgeek", "note": "If the cabin shifter has play", "price": "$40–80", "links": []}, {"tier": "oe", "name": "Lithium or silicone grease for the cable ends", "pn": "—", "note": "", "price": "$5", "links": []}], "aftermarket": [{"name": "Dieselgeek Sigma 6", "note": "The reference kit for the 02Q: all-aluminium front-to-back cable end on a steel spherical bearing, lifetime guarantee, and the only kit with a full public install PDF and videos. Slightly notchier feel by design.", "price": "$280–330", "signal": "Forum favorite · best documented", "links": [{"store": "Dieselgeek (install guide linked on page)", "url": "https://dieselgeek.com/products/sigma-6-six-speed-short-shift-kit-for-vw"}]}, {"name": "VF Engineering / 42 Draft Designs", "note": "Transmission-side short-shift brackets of the same idea; less documentation available.", "price": "$200–300", "signal": "Alternatives", "links": []}, {"name": "Weighted shift knob (Raceseng, BFI)", "note": "Not a shifter, but the other half of the feel. Adds mass to the throw so it falls into gear.", "price": "$80–200", "signal": "Pairs well", "links": []}], "tools": [{"name": "Engine cover/airbox off (see air filter guide); 13mm and 10mm sockets; small flat screwdriver and needle-nose pliers for the cable-end clips"}, {"name": "Trim tool for the cabin shifter surround; the kit's transmission locking pin and shifter pin (or a drill bit of the size the PDF specifies)"}, {"name": "Grease, zip ties, the install PDF printed"}], "before": ["Car in neutral, parking brake on.", "Print the kit's PDF. This guide is the map; the PDF has the photos and the adjustment procedure specific to the kit.", "Do the bushing wiggle test first."], "steps": [{"n": 1, "title": "Room to work", "blocks": [{"t": "text", "b": "Engine cover/airbox off (air filter guide). The two shift cables run from the firewall to the top of the transmission on the driver's side; you now have a clear view."}]}, {"n": 2, "title": "Unclip the cables from the levers", "blocks": [{"t": "text", "b": "Two levers on the transmission: the selector (front-to-back) and the relay lever (side-to-side). Each cable end sits on a lever pin with a retaining clip. Lift the spring tab, slide the clip off, lift the cable end off the pin. The relay-lever end may need a gentle pry with needle-nose pliers."}, {"t": "ill", "id": "shifter-hero", "cap": "Selector lever (the one the kit replaces) and relay lever, each with a cable on a pin and a clip."}]}, {"n": 3, "title": "Stock lever off, kit lever on", "blocks": [{"t": "text", "b": "Remove the nut on the selector shaft (13mm) and lift the factory selector lever off the splined shaft; wiggle, don't hammer or pry the shaft. Note the double tooth on the splines: the lever only goes on one way. Fit the kit's shorter lever the same way and torque its nut per the PDF (the factory figure is 20 Nm)."}, {"t": "torque", "label": "Selector shaft nut", "nm": 20, "c": {"level": "medium", "n": 2, "note": "20 Nm factory value (ECS transmission guide); Dieselgeek's PDF governs their hardware."}}]}, {"n": 4, "title": "New cable ends", "blocks": [{"t": "text", "b": "Slide the kit's cable ends onto the cables until the threads disappear inside the end; slide each on and off a couple of times so it moves freely, then set it. Grease the ball on the new lever's pin and the cable-end socket. Press each cable end onto its pin and fit the clip."}]}, {"n": 5, "title": "Adjust", "caution": true, "blocks": [{"t": "text", "b": "Lock the transmission in neutral with the kit's locking pin (it goes into the hole beside the selector shaft; the PDF shows exactly where). Inside the car, pop the shifter surround, pull the boot down, and pin the cabin shifter in its neutral gate with the kit's pin. Now both ends are fixed. Release the cable adjusters (the locking collars on the cable sheaths at the transmission bracket), let the cables find their length, and re-lock the collars. Remove both pins."}, {"t": "warn", "b": "Everything about how this shifter feels is set here. If the adjusters were locked with tension on either cable, gears will be hard to find or will grind. Both pins in, cables relaxed, then lock. If it's notchy afterwards, redo this step; don't live with it."}, {"t": "note", "b": "Side-to-side cable preload: Dieselgeek's PDF describes lightly pulling the cable out of its end before locking; their later guidance is that newer cars may not need it. Follow the current PDF for your kit, then adjust by feel if 1st/2nd is reluctant."}]}, {"n": 6, "title": "Test every gate, then reassemble", "blocks": [{"t": "text", "b": "Engine off, clutch in: select all six gears and reverse from neutral. Each should engage with the same effort and the shifter should self-centre to the 3–4 gate. Then with the engine running, clutch in, the same. Zip-tie the cables clear of anything hot or moving. Airbox back on, shifter surround back on."}]}, {"n": 7, "title": "Drive and re-adjust", "blocks": [{"t": "text", "b": "Drive it a few days. A slight notchiness is the kit; a grind or a missed gate is adjustment. Re-pin and re-adjust if needed."}]}], "alsoReplace": [{"name": "Shifter base bushings (cabin)", "why": "Worn bushings make any shifter sloppy and can prevent proper adjustment. Ten minutes with the surround already off."}, {"name": "Side-to-side cable end (aluminium)", "why": "Replaces the last rubber-isolated part in the linkage; Dieselgeek sells it as an add-on for a reason."}, {"name": "Weighted shift knob", "why": "You've got the boot down. Mass in the knob is the other half of the feel."}], "check": {"tab": "Is it the shifter?", "title": "Is the shifter the problem?", "illId": "shifter-hero", "illCap": "Slop in the cabin base and slop at the transmission feel similar from the driver's seat.", "rows": [{"see": "Knob wobbles side to side in neutral", "means": "Cabin shifter base bushings.", "do": "Bushings first; then decide on the kit."}, {"see": "Long throw but precise gates", "means": "Just the factory geometry.", "do": "Short shift kit."}, {"see": "Grind into 2nd or reverse, hard to find gates", "means": "Adjustment, or a clutch that isn't fully releasing.", "do": "Re-adjust cables; bleed the clutch; if it persists, synchro."}], "c": {"level": "community", "n": 3, "note": "Vendor guidance and forum diagnosis."}}, "aftercare": ["Re-check the cable clips after a week.", "Notchy 1–2 that doesn't settle: re-adjust, and consider the side-to-side preload note."], "disagreements": [{"topic": "Preload the side-to-side cable?", "pos": "The PDF says yes; Dieselgeek later said newer cars may not need it.", "call": "Follow the current PDF, then by feel."}, {"topic": "Is notchy normal?", "pos": "Some owners expected a smoother shifter.", "call": "Yes; the vendor says so. Precision, not butter."}], "sources": ["Dieselgeek Sigma 6 product page and install guide", "VWVortex 'DIY – Dieselgeek Sigma Six Speed Short Shifter Install'", "VWVortex / Golfmk7 Sigma 6 install thread (same transmission)", "ECS 02Q transmission guide (selector shaft nut torque)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('battery',$j${"id": "battery", "title": "Battery replacement", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "battery-hero", "alsoFits": "All Mk5 platform cars (Golf, GTI, Jetta, Eos, A3); no battery coding on this generation", "category": "Electrical", "kind": "repair", "glance": {"timeFirst": "30 min", "timeRepeat": "15 min", "difficulty": 1, "cost": "$150–350", "risk": "Negative off first, on last · battery is heavy · acid", "why": "A weak battery on a modern VW does strange things before it dies: random warning lights, a DSG that acts up, a radio that resets. Five years is a fair life; if yours is older or the car has been slow to crank on a cold morning, this is a half-hour job with one rule that matters.", "note": "No coding is needed on a Mk5, which is the whole reason this is easy. Later cars differ."}, "heroCap": "Battery under a plastic cover on the driver's side. Negative terminal off first, hold-down clamp at the base, lift it out. Group H6 (also called 48 or L3).", "lifespan": {"title": "When to expect it", "headline": ["Typically 4–6 years; sooner in hot climates"], "earliest": "3 years in the desert Southwest", "detail": "Slow cranking on a cold start, a dash that flickers on crank, or a jump start you needed once are the warnings. Any parts store will load-test it for free; below about 12.4 V resting, or a failed load test, replace it before it strands you or corrupts a module with low voltage.", "factors": ["Heat", "Short trips (never fully charged)", "Parasitic drain from an aftermarket stereo or alarm", "Sitting for weeks"], "inspect": ["Resting voltage once a season: 12.6 V is healthy, 12.4 is tired, 12.2 is done"], "confidence": {"level": "community", "n": 3, "note": "General practice; consistent."}}, "should": {"yesIf": ["Slow crank, especially cold", "Failed a load test or reads under 12.4 V rested", "Date sticker says 5+ years", "Odd electrical gremlins that come and go"], "codes": [], "notes": ["Size: Group H6 (DIN L3 / BCI 48). The Mk5 GTI's tray and hold-down are made for it. Optima's H6 is the DH6; Odyssey's is the 48-720.", "AGM or flooded: both work on a Mk5 because it has no battery management module that needs to be told. AGM tolerates heat and vibration better and costs more. Either is fine; AGM is the upgrade.", "Radio codes: most Mk5 head units don't ask for one, but check your manual or glovebox card before you disconnect. A cheap memory saver plugged into the OBD port avoids the question entirely."], "confidence": {"level": "high", "n": 3, "note": "Fitment and the no-coding point are consistent across sources; AGM guidance is standard practice."}}, "parts": [{"tier": "oe", "name": "Battery, Group H6 (L3/48), flooded or AGM", "pn": "e.g. Varta, Bosch, Interstate H6", "note": "12V, ~70 Ah, 700+ CCA", "price": "$150–250", "links": []}, {"tier": "oe", "name": "Terminal protector spray or grease, felt washers", "pn": "—", "note": "", "price": "$8", "links": []}], "aftermarket": [{"name": "Optima RedTop DH6", "note": "AGM, spiral cell, high cranking amps, very vibration resistant. The forum's default upgrade.", "price": "$280–350", "signal": "Forum favorite", "links": []}, {"name": "Optima YellowTop DH6", "note": "Deep-cycle AGM for cars with big stereos or lots of accessories; same case.", "price": "$300–360", "signal": "For accessory-heavy cars", "links": []}, {"name": "Odyssey 48-720 (Extreme)", "note": "AGM with a long warranty and excellent heat tolerance. Slightly taller; check the cover clears.", "price": "$300–380", "signal": "Longevity pick", "links": []}, {"name": "Varta / Bosch AGM H6", "note": "OE-supplier AGM at a friendlier price. Same battery as many factory fits.", "price": "$200–260", "signal": "Value AGM", "links": []}], "tools": [{"name": "10mm wrench (terminals), 13mm socket with extension (hold-down)"}, {"name": "Terminal brush, gloves, safety glasses"}, {"name": "Optional: OBD memory saver; multimeter"}], "before": ["Engine off, key out of the ignition, windows closed (you'll relearn one-touch afterwards).", "Note your radio code if your head unit has one.", "Negative terminal comes off first and goes on last. Every time."], "steps": [{"n": 1, "title": "Cover off", "blocks": [{"t": "text", "b": "Push the release tab on the battery cover, pivot it up and unhook it at the rear."}]}, {"n": 2, "title": "Negative, then positive", "caution": true, "blocks": [{"t": "text", "b": "10mm: loosen the negative (black, marked −) clamp nut, twist the clamp off the post and tuck the cable where it can't touch the terminal. Then the positive (red, under its flip cover)."}, {"t": "warn", "b": "Negative first. If the wrench touches the body while you're on the positive terminal with the negative still connected, you've made a welder. Glasses on; batteries vent hydrogen."}, {"t": "ill", "id": "battery-hero", "cap": "Order: negative off, positive off, clamp, lift. Reverse to install."}]}, {"n": 3, "title": "Hold-down and lift", "blocks": [{"t": "text", "b": "13mm on an extension: the hold-down clamp bolt at the base of the battery, on the inboard side. Remove the clamp. If the front half of the battery box is in the way, lift it off. Lift the battery straight up and out; it's about 45 lb and awkward. Keep it level."}]}, {"n": 4, "title": "Clean and drop in", "blocks": [{"t": "text", "b": "Brush the terminal clamps clean inside. Check the tray for acid crust and wipe it. New battery in, same orientation (positive toward the front, matching the cables), seated in the tray's lip. Hold-down clamp back on and snug: it should not rock, but you're clamping plastic, so don't crank it."}]}, {"n": 5, "title": "Positive, then negative", "blocks": [{"t": "text", "b": "Positive clamp on its post first, nut snug (10mm; snug, the clamps distort if over-tightened). Then the negative. A wipe of terminal protector on both. Box half and cover back on."}]}, {"n": 6, "title": "Relearn the little things", "blocks": [{"t": "text", "b": "Start it. Set the clock. One-touch windows: close each window fully and hold the switch up for a second more, then open fully and hold down a second; repeat for each. Turn the steering wheel lock to lock once so the steering-angle sensor recentres (clears the ESP light if it's on). Sunroof: hold close until it cycles. That's it; no coding on this car."}]}], "alsoReplace": [{"name": "Ground strap and terminal clamps", "why": "Green or crusty clamps cause the same symptoms as a bad battery. A new clamp is $10."}, {"name": "Check the alternator", "why": "With the new battery in and the engine running, you should see 13.8–14.4 V at the terminals. If not, the battery wasn't the problem."}], "check": {"tab": "Test first", "title": "Is it the battery?", "illId": "battery-hero", "illCap": "A multimeter answers most of this.", "rows": [{"see": "Rested voltage 12.6+, cranks fine", "means": "Battery is fine.", "do": "Look elsewhere for your symptom."}, {"see": "Rested 12.2–12.4, slow crank", "means": "Tired.", "do": "Load test; probably replace."}, {"see": "13.8–14.4 V running", "means": "Alternator is fine.", "do": "Battery only."}, {"see": "Under 13.5 V running, or over 15", "means": "Charging problem.", "do": "Alternator or regulator; a new battery will just die again."}], "c": {"level": "high", "n": 3, "note": "Standard electrical diagnosis."}}, "aftercare": ["Write the install date on the battery with a marker.", "Recycle the old one; the store credits the core."], "disagreements": [{"topic": "Does it need coding?", "pos": "Newer VWs do; people assume all do.", "call": "Not the Mk5. Plug and play."}, {"topic": "AGM or flooded?", "pos": "Forum arguments about cost.", "call": "Both work here; AGM is the nicer part if the budget allows."}], "sources": ["ECS 02Q transmission guide (battery removal steps and fastener sizes)", "Optima / Odyssey fitment listings", "Forum consensus on Mk5 relearn procedures and the absence of battery coding"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('headlights',$j${"id": "headlights", "title": "Headlight bulbs & housings", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "headlight-hero", "alsoFits": "2006–09 GTI (halogen and bi-xenon); Golf/Rabbit and Jetta share the technique, not the housings", "category": "Electrical", "kind": "repair", "variants": {"question": "Which headlights does your car have?", "hint": "US Mk5 GTIs came both ways. Bi-xenon housings have a projector with a bluish-white beam and a small inner halogen; halogen housings use two ordinary reflector bulbs.", "options": [{"id": "halogen", "label": "Halogen", "when": "H7 bulbs, yellow-white light, cheap to replace"}, {"id": "xenon", "label": "Bi-xenon (HID)", "when": "One D2S bulb does low and high via a shutter; ~$50 each"}]}, "glance": {"timeFirst": "1–1.5 hr (assembly out) · 20 min if you can reach in", "timeRepeat": "30 min", "difficulty": 2, "cost": "$20–40 halogen · $80–120 xenon pair · $300+ per housing", "risk": "HID ballast voltage · scratching the bumper · touching halogen glass", "why": "Bulbs dim before they die, and one dead low beam is a ticket. On this car the honest way to change either bulb type is to take the headlight out, which means loosening the bumper cover. It sounds worse than it is, and while it's out you can fix the fogged lens or swap the whole housing.", "note": "Pelican and the forums agree: possible in place with small hands on the passenger side, painful on the driver's side, easy with the assembly out."}, "heroCap": "Headlight held by screws that hide behind the bumper cover's top edge. Loosen the cover, unscrew the housing, pull it forward, and every bulb cap is in front of you.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Halogen H7 low beams: typically 1–3 years of nightly use", "only": ["halogen"]}, {"text": "D2S xenon bulbs: typically 5–8 years; they dim and shift colour rather than fail suddenly", "only": ["xenon"]}], "earliest": "Cheap 'blue' halogens can go in months", "detail": "Halogens burn out; xenons fade toward purple and lose output long before they quit. Replace xenons in pairs so the colours match, and because the second one is close behind. Housings themselves go hazy from UV on the outside (polish) or from a failed seal on the inside (replace).", "factors": ["Daytime running lights on all the time", "Vibration from a rough road", "Touching halogen glass on install"], "inspect": ["Look at your low beams on a garage wall once a year: colour match and pattern"], "confidence": {"level": "community", "n": 3, "note": "Owner experience; no factory interval."}}, "should": {"yesIf": ["Low beam out, or the dash says 'dipped beam'", "Beams noticeably different colours (xenon)", "Lens fogged inside or badly hazed", "You want to upgrade housings"], "codes": [], "notes": [{"text": "H7 for the low beam. Most Mk5 GTI halogen housings also use H7 for the high beam, but confirm by reading the old bulb's base before you buy. Any decent brand (Osram, Philips) beats a blue-tinted 'upgrade' bulb, which is dimmer and short-lived.", "only": ["halogen"]}, {"text": "The outer projector's single D2S bulb does both low and high beam; a shutter moves for high. The small inner lamp is an H7 'flash to pass' that some owners code to act as an extra high beam. When the dash complains about the low beam, it's the D2S. Buy a name brand (Philips, Osram) and replace both sides.", "only": ["xenon"]}, {"text": "The ballast makes several thousand volts to light a D2S. Battery disconnected, lights off, and never operate a ballast with the bulb out.", "only": ["xenon"]}, "LED 'H7 replacement' bulbs in halogen reflector housings scatter light and blind other drivers; most aren't legal for road use. A better halogen is the honest upgrade for a reflector; a housing swap to bi-xenon is the real one."], "confidence": {"level": "medium", "n": 3, "note": "Pelican article and forum threads; bulb-type detail confirmed for xenon, halogen high beam noted as 'confirm on the old bulb'."}}, "parts": [{"tier": "oe", "name": "H7 halogen bulbs (pair)", "pn": "Osram Night Breaker / Philips X-tremeVision", "note": "Replace in pairs", "price": "$20–40", "links": [], "only": ["halogen"]}, {"tier": "oe", "name": "D2S xenon bulbs (pair)", "pn": "Philips 85122 / Osram 66240", "note": "Replace in pairs; name brand only", "price": "$80–120", "links": [], "only": ["xenon"]}, {"tier": "oe", "name": "Headlight housing (each), if replacing", "pn": "halogen or bi-xenon by VIN", "note": "OE (Hella) or OE-supplier; aftermarket varies widely", "price": "$300–900", "links": []}, {"tier": "oe", "name": "Bumper cover clips/screws", "pn": "a few break every time", "note": "", "price": "$10", "links": []}], "aftermarket": [{"name": "OEM-style bi-xenon housings (Hella)", "note": "The real upgrade for a halogen car: projector beam, proper cutoff, and legal. Needs the xenon wiring/ballasts or a harness, plus the auto-levelling if you want it correct.", "price": "$700–1,200 / pair", "signal": "The proper upgrade", "links": []}, {"name": "Depo / TYC replacement housings", "note": "Budget replacements for a fogged or cracked lens. Fit varies; beam quality is fine for halogen, hit-and-miss for projectors.", "price": "$150–300 each", "signal": "Budget lens fix", "links": []}, {"name": "Osram Night Breaker / Philips X-treme H7", "note": "Brighter, whiter halogens that are still legal. Shorter life than standard.", "price": "$25–40 / pair", "signal": "Best legal halogen", "links": [], "only": ["halogen"]}], "tools": [{"name": "T25 and T30 Torx, 10mm socket, trim tool for bumper clips"}, {"name": "Nitrile gloves (halogen glass), a soft blanket to set the housing on"}, {"name": "Flashlight; a friend to hold the bumper corner"}], "before": ["Battery negative disconnected, especially for xenon.", "Don't touch halogen glass with bare fingers; the oil creates a hot spot and the bulb fails early. If you did, wipe it with alcohol.", "Lay a blanket on the fender edge; you'll rest the housing there."], "steps": [{"n": 1, "title": "Try the shortcut (passenger side, halogen)", "only": ["halogen"], "blocks": [{"t": "text", "b": "With the airbox snorkel out of the way, small hands can reach the low-beam cap on the passenger side from above: twist the round cap off, unplug the bulb, release its wire clip, swap it. If you can do both sides this way, you're done in twenty minutes. Most people can't reach the driver's side past the fuse box and battery; for that side, continue."}]}, {"n": 2, "title": "Loosen the bumper cover's top edge", "blocks": [{"t": "text", "b": "Behind the grille and along the top of the bumper cover: Torx screws into the radiator support (T25/T30) and clips. Remove the screws along the top and the ones in the wheel-arch liner at the bumper corner (T25) so the corner of the cover can be pulled forward a few inches. Pelican's advice is to just remove the cover entirely; it's another fifteen minutes and saves scratching it."}, {"t": "ill", "id": "headlight-hero", "cap": "The housing screws are behind the bumper cover's edge. Loosen the cover, and they're right there."}]}, {"n": 3, "title": "Headlight out", "blocks": [{"t": "text", "b": "With the cover pulled forward, the headlight mounting screws are visible (top edge and outer side). Remove them, unplug the main connector on the back of the housing, and slide the housing forward and out. Set it face-down on the blanket."}, {"t": "warn", "b": "Xenon: the ballast is on the housing. Don't unplug or plug anything with the lights on, and don't power a ballast without a bulb.", "only": ["xenon"]}]}, {"n": 4, "title": "Swap the bulbs", "blocks": [{"t": "text", "b": "Round caps on the back: twist off. Low beam H7: unplug, squeeze the wire retainer clip, lift the bulb out, new one in with the tab orientation matching, clip, plug, cap. High beam: same. Gloves on the glass.", "only": ["halogen"]}, {"t": "text", "b": "Remove the projector's rear cap, unplug the igniter connector from the D2S, release the bulb's retaining ring or clip, lift the bulb straight out without touching the glass, seat the new one in the same orientation, retainer, igniter, cap. Do the other side too; colours must match.", "only": ["xenon"]}, {"t": "text", "b": "While it's out: if the lens is hazy outside, polish it now with a headlight restoration kit; it's a hundred times easier on the bench. Moisture inside means a failed seal, and that's a housing, not a bulb."}]}, {"n": 5, "title": "Housing back in, cover back on", "blocks": [{"t": "text", "b": "Plug the housing in, slide it into its locating pins, screws in. Bumper cover corner back, screws and clips. Battery negative reconnected."}]}, {"n": 6, "title": "Aim check", "blocks": [{"t": "text", "b": "Park 25 feet from a wall on level ground. Low-beam cutoffs should be level with each other and just below headlight height. Adjusters are on the back of the housing (T-handle or hex). Xenon cars with auto-levelling: turn the car on and watch the beams settle; if one stays low, the level sensor arm on the control arm is disconnected."}]}], "alsoReplace": [{"name": "Turn signal and DRL bulbs", "why": "Same housing, same trip. The amber bulbs fade and the sockets corrode."}, {"name": "Lens restoration", "why": "Housing on a bench is when to polish and UV-coat it."}, {"name": "Headlight washer nozzle / level sensor check", "why": "Xenon cars: while the bumper corner is loose, check the washer hose and that the level sensor arm is attached.", "only": ["xenon"]}], "check": {"tab": "Bulb or housing?", "title": "Bulb, housing, or something else?", "illId": "headlight-hero", "illCap": "Colour, moisture and the dash message narrow it quickly.", "rows": [{"see": "One low beam out, dash message", "means": "Bulb (D2S on xenon, H7 on halogen).", "do": "Replace, in pairs."}, {"see": "Beam flickers or takes several tries to light (xenon)", "means": "Bulb at end of life, or the ballast/igniter.", "do": "New bulbs first; if it persists, ballast."}, {"see": "Fog inside the lens", "means": "Seal failed.", "do": "Housing, or a careful reseal."}, {"see": "Both dim, yellow lens", "means": "UV haze on the polycarbonate.", "do": "Polish and coat."}], "c": {"level": "community", "n": 3, "note": "Owner threads and vendor guidance."}}, "aftercare": ["Check aim after a week.", "Xenon colour mismatch that persists: the ballasts differ or one bulb is a different brand."], "disagreements": [{"topic": "Can you do it in place?", "pos": "Some owners manage the passenger side; Pelican says take the assembly out.", "call": "Try the shortcut on the passenger side; take it out for the driver's side and for any xenon."}, {"topic": "Halogen high-beam bulb type", "pos": "H7 on most; not confirmed from a factory table.", "call": "Read the old bulb."}, {"topic": "LED drop-ins", "pos": "Popular; cheap.", "call": "Not in a reflector housing. Glare, and not legal on the road."}], "sources": ["Pelican Parts Mk5 GTI headlight bulb and assembly article", "VWVortex 'GTI Headlight Bulb Replacement' (bi-xenon detail)", "Owner threads on in-place bulb access", "Bulb and housing listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('plugs',$j${"id": "plugs", "title": "Spark plugs & coil packs", "fits": "2006–2009 VW GTI · 2.0T FSI & TSI", "heroId": "ignition-hero", "alsoFits": "All 2.0T FSI and TSI (same plugs and coils)", "category": "Engine", "kind": "repair", "variants": {"question": "Stock or tuned?", "hint": "Tuned cars run more cylinder pressure and want a colder plug with a slightly smaller gap.", "options": [{"id": "stock", "label": "Stock or Stage 1", "when": "Factory-spec plug at 0.8 mm (.032\")"}, {"id": "tuned", "label": "Stage 2, K04 or bigger", "when": "One range colder, gapped to 0.7 mm (.028\")"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$40–60 plugs · $60–120 coils", "risk": "Cross-threading a plug · dropping debris in the plug well", "why": "Plugs wear and coils die, and on a turbo engine both show up as a misfire under boost before anything else. It's a twenty-minute job with the right socket, and coils on this engine just pull out: no bolts.", "note": "Every source agrees on the procedure. The arguments are about plug choice and gap, so those are laid out below."}, "heroCap": "Coil packs sit in the plug wells on top of the valve cover, one per cylinder, held by friction. Unplug, pull straight up, and the plug is below on a 5/8\" (16mm) socket.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Plugs: every 40,000 miles; coils when they fail", "only": ["stock"]}, {"text": "Plugs: every 20,000–30,000 miles on a tuned car; iridium lasts longer than copper", "only": ["tuned"]}], "earliest": "Copper race plugs (BKR7E) need changing every 12,000–15,000", "detail": "A tired plug misfires under load first: a stumble at full boost in third that goes away at part throttle. A dying coil is the same symptom on one cylinder, with a code that names it. Coils on the FSI were revised several times; the latest black revision and the red 'R8' coil are the same part in different colours.", "factors": ["Tune", "Oil in the plug wells from a leaking valve cover gasket (kills coils)", "Wrong gap for the boost level"], "inspect": ["Any misfire code: pull the coil on that cylinder and swap it with a neighbour. If the code follows the coil, it's the coil."], "confidence": {"level": "community", "n": 4, "note": "Owner practice and vendor kit notes; the factory table wasn't fetched this pass."}}, "should": {"yesIf": ["Misfire under boost, worse when it's cold and damp", "Misfire code on a specific cylinder (P0301–P0304)", "40k since the last plugs, or unknown", "Just tuned it and still on stock plugs"], "codes": ["P0300", "P0301", "P0302", "P0303", "P0304"], "notes": ["Plug choice, decoded: Bosch FR6KPP332S is the factory plug. NGK PFR7S8EG is the same family one heat range colder and is what most kits ship now. NGK BKR7EIX is an iridium plug one range colder than the Bosch, favoured for tuned cars. 'Colder' means the plug sheds heat faster; it does not add power on a stock car.", {"text": "Gap: pre-gapped 0.8 mm (.032\") is right for stock and Stage 1. Don't re-gap platinum tips with a tool; check with a wire gauge only.", "only": ["stock"]}, {"text": "Gap: close them to 0.7 mm (.028\"). Too wide and the spark blows out under boost, which is your full-throttle misfire; too narrow and cold starts and idle suffer. Tuners publish their number; APR's K04 guidance is .028 or a touch under.", "only": ["tuned"]}, "Coils: the red Audi R8 coil (06E905115E) and the current black VW coil (07K905715G / 06H905115B) are identical apart from colour and are the latest revision. Red doesn't make more spark; it just looks good and is a reliable part.", "FSI and TSI use the same plugs and the same coils."], "confidence": {"level": "high", "n": 4, "note": "Plug families, gaps and coil equivalence agree across a parts specialist's listing and multiple forum threads."}}, "parts": [{"tier": "oe", "name": "Spark plugs (×4), NGK PFR7S8EG or Bosch FR6KPP332S", "pn": "06H 905 601 A", "note": "Pre-gapped .032\"", "price": "$40–60", "links": [], "only": ["stock"]}, {"tier": "aftermarket", "name": "Spark plugs (×4), NGK BKR7EIX iridium", "pn": "NGK 2667", "note": "One range colder; gap to .028\"", "price": "$40–50", "links": [], "only": ["tuned"]}, {"tier": "oe", "name": "Ignition coils (×4), latest revision", "pn": "07K905715G / 06H905115B (black) · 06E905115E (red)", "note": "Identical internals", "price": "$60–120", "links": []}, {"tier": "oe", "name": "Dielectric grease, anti-seize (tiny amount, optional)", "pn": "—", "note": "", "price": "$8", "links": []}], "aftermarket": [{"name": "Red 'R8' coils (06E905115E)", "note": "Same part as the latest black coil, different colour. Cheap, reliable, and the forums love the look. No performance change.", "price": "$60–90 / set", "signal": "Same part, red", "links": []}, {"name": "NGK BKR8EIX (two ranges colder)", "note": "For big-turbo builds. Too cold for a Stage 2 daily; it'll foul.", "price": "$40–50", "signal": "Big-turbo only", "links": []}, {"name": "NGK BKR7E copper", "note": "Race plug: cheap, great spark, 12–15k life. For cars that see the plug wrench often.", "price": "$12", "signal": "Track consumable", "links": []}], "tools": [{"name": "5/8\" (16mm) thin-wall spark plug socket with rubber insert, 3/8\" ratchet and extension"}, {"name": "Torque wrench to 30 Nm"}, {"name": "Wire-type gap gauge (not a coin-style disc)"}, {"name": "Coil puller or a strong grip; small flat screwdriver for the connector locks; compressed air or a vacuum for the wells"}], "before": ["Engine cold. Plug threads in a hot aluminium head strip easily.", "Blow or vacuum the wells out before the plugs come out so nothing drops into the cylinder.", "Do one cylinder at a time so nothing gets mixed up."], "steps": [{"n": 1, "title": "Cover off, unplug the coils", "blocks": [{"t": "text", "b": "Engine cover off (air filter guide). Four coils in a row on the valve cover. Press or lift each connector's lock tab with a small screwdriver and unplug it."}]}, {"n": 2, "title": "Pull the coils", "blocks": [{"t": "text", "b": "Grip the coil by its body and pull straight up; they're a friction fit and can be stubborn. A coil puller tool helps; a wide screwdriver under the coil's lip, gently, is the owner method. Look at each one: cracks in the boot or oil on it mean the coil is dead or the cover gasket is leaking."}, {"t": "ill", "id": "ignition-hero", "cap": "No bolts. Unplug, pull straight up, plug is directly below."}]}, {"n": 3, "title": "Plugs out", "blocks": [{"t": "text", "b": "Blow the wells clear. 5/8\" plug socket on an extension, break each plug loose and spin it out. Read them as they come out (see the table below); a plug that's oily or white tells you something."}]}, {"n": 4, "title": "Gap and fit the new plugs", "caution": true, "blocks": [{"t": "text", "b": "Check the gap with a wire gauge without touching the centre electrode: 0.8 mm (.032\") for stock. If it's off, adjust by bending the ground strap only, gently.", "only": ["stock"]}, {"t": "text", "b": "Check and set the gap to 0.7 mm (.028\") with a wire gauge, bending only the ground strap. Iridium centre electrodes chip if you lever on them.", "only": ["tuned"]}, {"t": "text", "b": "Thread each plug in by hand, using the socket without the ratchet, until it seats. If it resists before seating, back out and restart; never force it. Then torque."}, {"t": "torque", "label": "Spark plugs (flat seat with gasket)", "nm": 25, "alt": [30], "c": {"level": "varies", "n": 2, "note": "No factory figure was confirmed this pass; kit sheets and forums quote 25–30 Nm for this gasketed flat-seat plug. Either is fine. Hand-tight plus a firm quarter turn lands here."}}, {"t": "warn", "b": "Cross-threading a plug in an aluminium head is the one way this job goes badly. Hand start, every time."}]}, {"n": 5, "title": "Coils in, plugs in the connectors", "blocks": [{"t": "text", "b": "Dab of dielectric grease inside each coil boot. Push each coil down until it seats over the plug with a definite stop. Connectors on until they click. Cover on."}]}, {"n": 6, "title": "Start and drive", "blocks": [{"t": "text", "b": "Idle should be smooth immediately. Drive it and give it full throttle in a middle gear once warm; a stumble that's gone is the point. A stumble that remains with new plugs and coils is not ignition: think PCV, diverter valve, or fuel."}]}], "alsoReplace": [{"name": "Valve cover gasket", "why": "Oil in the plug wells kills coils. If the wells are wet, the gasket is the cause and it's a one-hour job."}, {"name": "PCV valve", "why": "Rough idle blamed on plugs is often the PCV. Same access."}], "check": {"tab": "Read the plugs", "title": "Reading the old plugs", "illId": "ignition-hero", "illCap": "Tan is right. Everything else is a clue.", "rows": [{"see": "Light tan to grey electrode, no deposits", "means": "Healthy engine, plug simply aged.", "do": "Replace, same type."}, {"see": "Black, sooty and dry", "means": "Rich, or the plug is too cold for the car, or lots of idling.", "do": "Check gap and heat range; if you fitted BKR8s on a Stage 1, that's why."}, {"see": "Oily, wet", "means": "Oil in the well from the cover gasket, or oil past the rings/PCV.", "do": "Gasket first; new coil on that cylinder."}, {"see": "White, blistered, tiny beads on the electrode", "means": "Too hot: lean, too much boost, or the plug is too hot a range.", "do": "Colder plug and a look at the tune before you damage a piston."}], "c": {"level": "community", "n": 3, "note": "Standard plug reading; consistent with forum experience on this engine."}}, "aftercare": ["Note mileage and plug type in the glovebox.", "Misfire returns on one cylinder: swap coils between cylinders and see if it moves."], "disagreements": [{"topic": "Gap", "pos": ".032 vs .028 vs .024.", "call": ".032 stock, .028 tuned; .024 is APR's K04 kit number."}, {"topic": "Do red coils help?", "pos": "Forum lore says more spark.", "call": "Identical to the latest black coil. Buy them for the colour."}, {"topic": "Plug torque", "pos": "25 vs 30 Nm; factory value not confirmed.", "call": "25–30, flagged."}], "sources": ["VWVortex 'Correct Spark Plug Gap 2.0T FSI'", "Audizine red-coil and plug swap threads", "Europa Parts ignition kit listing (coil equivalence, plug families)", "UroTuning tune-up kit listing", "Black Forest Industries BKR7E note"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
