-- 015: TSI engine under the Mk5 GTI; tasks may share a guide via guide_id
alter table tasks add column if not exists guide_id text;
update tasks set guide_id = id where guide_id is null;
update powertrains set note = '2006–2008.5 · timing belt · manual or DSG' where id = 'bpy' and model_id = 'gti';
-- guides.id must exist in tasks for the FK; stub guides above have matching task rows.
